INSERT INTO `cycletech_tmaterial_products` (`nid`, `ccode`, `cmaterial_products`, `eng_cmaterial_products`, `ctag`, `cimage`, `cimage_365`, `cicon`, `cnote`, `cnote_365`, `nstatus`, `nspecial`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `cproduct_fb`, `cbanner1`, `cbanner2`, `cbanner3`, `clink_banner1`, `clink_banner2`, `clink_banner3`, `nid_group`) VALUES
(1, 'thiet-bi-quan-trac', 'THIẾT BỊ QUAN TRẮC', '', '', '', '', 'fas fa-satellite-dish', 'Hệ thống thiết bị quan trắc, cảm biến đo bức xạ mặt trời, cảm biến nhiệt độ, cảm biến đo gió và trạm thời tiết phục vụ giám sát năng lượng mặt trời và quan trắc khí tượng.', NULL, 1, 0, '2', 1, NULL, '2026-09-29', NULL, NULL, NULL, NULL, NULL, '', '', '', 0),
(2, 'tru-sac-xe-dien', 'TRỤ SẠC XE ĐIỆN', '', '', '', '', 'fas fa-charging-station', 'Giải pháp trạm sạc xe điện thông minh, trụ sạc AC dân dụng, trụ sạc nhanh DC công suất cao và hệ thống sạc tích hợp thương mại.', NULL, 1, 0, '1', 1, NULL, '2026-09-29', NULL, NULL, NULL, NULL, NULL, '', '', '', 0),
(3, 'bo-loc-song-hai', 'BỘ LỌC SÓNG HÀI', NULL, NULL, '', '', 'fas fa-bolt', '<h2>GIẢI PHÁP LỌC SÓNG HÀI CHỦ ĐỘNG AHF</h2>\n<p><strong>Giải pháp kiểm soát sóng hài và nâng cao chất lượng điện năng toàn diện cho hệ thống điện công nghiệp và dân dụng.</strong></p>\n<p>Trong các hệ thống điện hiện đại, sự phát triển của các thiết bị điện tử công suất, biến tần, UPS, bộ nguồn, thiết bị tự động hóa và inverter làm gia tăng đáng kể các tải phi tuyến. Đây là một trong những nguyên nhân chính tạo ra sóng hài, gây méo dạng dòng điện, tăng tổn hao và ảnh hưởng đến độ ổn định của hệ thống điện.</p>\n<p><strong>Active Harmonic Filter (AHF)</strong> là giải pháp lọc sóng hài chủ động, cho phép giám sát và bù dòng điện hài theo thời gian thực. Thay vì sử dụng các bộ lọc thụ động cố định, AHF chủ động tạo ra dòng điện bù phù hợp với thành phần sóng hài của tải, giúp cải thiện chất lượng dòng điện phía lưới.</p>\n<p style=\"text-align: center;\"><img src=\"fileman/Uploads/BLSH/image1.png\" alt=\"Bộ lọc sóng hài chủ động AHF dạng module và treo tường\" /></p>\n<p style=\"text-align: center;\"><img src=\"fileman/Uploads/BLSH/image2.png\" alt=\"Tủ lọc sóng hài chủ động AHF Cabinet tích hợp nhiều module\" style=\"max-width: 60%;\" /></p>\n<h3>1. Nguyên lý hoạt động của AHF</h3>\n<p>AHF sử dụng biến dòng CT (Current Transformer) để đo dòng điện của tải và phân tích các thành phần sóng hài trong hệ thống. Bộ điều khiển trung tâm sau đó xác định thành phần cần bù và điều khiển bộ nghịch lưu tạo ra dòng điện bù có biên độ và góc pha đối nghịch.</p>\n<p>Dòng điện bù được đưa vào hệ thống nhằm triệt tiêu các thành phần sóng hài do tải phi tuyến tạo ra. Nhờ đó, dòng điện lấy từ lưới được cải thiện và dạng sóng trở nên gần với dạng hình sin chuẩn cơ bản.</p>\n<p>Theo thông số của dòng <strong>SinE AHF</strong>, thiết bị hỗ trợ bù sóng hài từ <strong>bậc 2 đến bậc 50</strong>, với khả năng giảm độ méo dòng hài (THDi) xuống <strong>dưới 5%</strong> (giảm trên 95% sóng hài tại tải định mức).</p>\n<p style=\"text-align: center;\"><img src=\"fileman/Uploads/BLSH/image3.png\" alt=\"Sơ đồ nguyên lý bù dòng điện và biểu đồ độ méo sóng hài trước và sau khi lọc AHF\" /></p>\n<h3>2. Công nghệ Three-Level NPC – Hiệu suất cao, dòng ripple thấp</h3>\n<p>Dòng AHF SinE sử dụng cấu trúc biến đổi ba mức <strong>NPC (Neutral Point Clamped)</strong>. So với cấu trúc hai mức truyền thống, công nghệ ba mức tạo ra ba mức điện áp đầu ra, giúp cải thiện chất lượng điện áp và dòng điện đầu ra.</p>\n<p>Cấu trúc này mang lại hai lợi ích đáng chú ý:</p>\n<ul>\n    <li><strong>Giảm tổn hao chuyển mạch:</strong> Điện áp tác động lên mỗi linh kiện bán dẫn (IGBT) thấp hơn, góp phần giảm tổn hao nhiệt và nâng cao hiệu suất tổng thể.</li>\n    <li><strong>Giảm dòng điện ripple (gợn sóng):</strong> Điện áp đầu ra có chất lượng tốt hơn, giúp giảm dòng gợn và giảm yêu cầu kích thước đối với bộ lọc đầu ra.</li>\n</ul>\n<p style=\"text-align: center;\"><img src=\"fileman/Uploads/BLSH/image4.png\" alt=\"Sơ đồ cấu trúc Three-Level NPC và dạng sóng điện áp - dòng điện đầu ra\" /></p>\n<h3>3. Thiết kế module linh hoạt, dễ mở rộng</h3>\n<p>Một ưu điểm nổi bật của giải pháp AHF là thiết kế theo dạng module, giúp linh hoạt lựa chọn công suất phù hợp với từng hệ thống và thuận tiện mở rộng khi phụ tải tăng trong tương lai:</p>\n<ul>\n    <li>Dải công suất bù linh hoạt từ <strong>30A đến 200A</strong> cho mỗi module.</li>\n    <li>Hỗ trợ kết nối song song tối đa lên đến <strong>20 module</strong> trong cùng một hệ thống tủ.</li>\n    <li>Hỗ trợ các cấu hình lưới điện <strong>3P3W (3 pha 3 dây)</strong> và <strong>3P4W (3 pha 4 dây)</strong>, với nhiều cấp điện áp tùy chọn: <strong>200V, 400V, 480V, 690V và 800V</strong>.</li>\n</ul>\n<p style=\"text-align: center;\"><img src=\"fileman/Uploads/BLSH/image7.png\" alt=\"Module AHF dạng lắp tủ Rack với màn hình cảm ứng HMI\" style=\"max-width: 80%;\" /></p>\n<p style=\"text-align: center;\"><img src=\"fileman/Uploads/BLSH/image5.png\" alt=\"Module AHF dạng gắn tường Wall-mounted\" style=\"max-width: 60%;\" /></p>\n<p style=\"text-align: center;\"><img src=\"fileman/Uploads/BLSH/image6.png\" alt=\"Cổng đấu nối nguồn động lực và các cổng truyền thông RS485, CAN, biến dòng CT\" style=\"max-width: 80%;\" /></p>\n<h3>4. Nhiều phương án lắp đặt cho mọi không gian</h3>\n<p>AHF được thiết kế để phù hợp với nhiều điều kiện không gian và cấu trúc tủ điện khác nhau:</p>\n<ul>\n    <li><strong>Rack-mounted:</strong> Phù hợp lắp đặt trong tủ điện phân phối hoặc hệ thống tủ rack tiêu chuẩn.</li>\n    <li><strong>Wall-mounted:</strong> Dạng gắn tường độc lập, phù hợp với phòng điện và những vị trí cần tối ưu không gian sàn.</li>\n    <li><strong>Vertical installation:</strong> Bố trí theo phương đứng, phù hợp với các hệ thống có không gian lắp đặt hạn chế.</li>\n</ul>\n<p style=\"text-align: center;\"><img src=\"fileman/Uploads/BLSH/image8.png\" alt=\"Bản vẽ kích thước và phương án lắp đặt Rack-mount và Wall-mounted\" /></p>\n<h3>5. Không chỉ lọc sóng hài</h3>\n<p>Bên cạnh chức năng chính là lọc sóng hài chủ động, thiết bị AHF còn tích hợp đồng thời nhiều tính năng nâng cao chất lượng điện năng:</p>\n<ul>\n    <li><strong>Bù công suất phản kháng:</strong> Tự động bù cả chiều cảm kháng và dung kháng, nâng cao hệ số công suất cosφ tiến tới 1.0.</li>\n    <li><strong>Bù mất cân bằng pha:</strong> Tự động cân bằng tải giữa các pha, triệt tiêu dòng điện chạy trên dây trung tính.</li>\n    <li><strong>Giám sát và điều khiển thông qua HMI:</strong> Màn hình cảm ứng hiển thị chi tiết các thông số đo lường, dạng sóng điện áp/dòng điện và phổ phân tích sóng hài FFT.</li>\n    <li><strong>Giao tiếp truyền thông:</strong> Hỗ trợ cổng giao tiếp RS485 (Modbus RTU) và CAN Bus kết nối với hệ thống SCADA / BMS.</li>\n    <li><strong>Chức năng bảo vệ toàn diện:</strong> Tích hợp bảo vệ quá tải, ngắn mạch, quá nhiệt, quá áp/thấp áp, bảo vệ inverter và cảnh báo sự cố quạt làm mát, đảm bảo hệ thống vận hành an toàn 24/7.</li>\n</ul>\n<h3>6. Ứng dụng thực tế của giải pháp AHF</h3>\n<p>Giải pháp lọc sóng hài chủ động phù hợp với mọi hệ thống có tỷ lệ tải phi tuyến cao:</p>\n<ul>\n    <li><strong>Nhà máy sản xuất công nghiệp:</strong> Dây chuyền biến tần, máy CNC, động cơ servo, máy hàn, hệ thống tự động hóa.</li>\n    <li><strong>Trung tâm dữ liệu (Data Center):</strong> Hệ thống máy chủ, UPS công suất lớn và các bộ nguồn chuyển mạch viễn thông.</li>\n    <li><strong>Hệ thống năng lượng tái tạo:</strong> Nhà máy điện mặt trời, trang trại điện gió sử dụng hệ thống inverter công suất cao.</li>\n    <li><strong>Sản xuất điện tử & linh kiện bán dẫn:</strong> Yêu cầu nguồn điện chất lượng cao, sạch và ổn định tuyệt đối.</li>\n    <li><strong>Cơ sở hạ tầng & giao thông:</strong> Hệ thống metro đường sắt, sân bay, cảng biển và các bệnh viện lớn.</li>\n</ul>\n<h3>7. Cycle Electric – Giải pháp chất lượng điện năng toàn diện</h3>\n<p>Đối với mỗi công trình, mức độ và đặc tính sóng hài là khác nhau. Vì vậy, việc lựa chọn công suất và cấu hình AHF cần được thực hiện dựa trên khảo sát hệ thống, đo kiểm chất lượng điện năng và phân tích phổ sóng hài thực tế.</p>\n<p><strong>Cycle Electric</strong> cung cấp giải pháp tổng thể từ <em>Khảo sát &rarr; Đo kiểm phổ sóng hài &rarr; Phân tích dữ liệu &rarr; Lựa chọn thiết bị &rarr; Thiết kế tủ &rarr; Lắp đặt &rarr; Cài đặt & Nghiệm thu bàn giao</em>, giúp doanh nghiệp kiểm soát hoàn toàn sóng hài và nâng cao độ ổn định cho lưới điện.</p>\n<p>Nếu hệ thống của bạn đang gặp các hiện tượng như chỉ số THDi cao, dây trung tính quá nhiệt, máy biến áp/dây cáp phát nóng bất thường, thiết bị điện tử bị treo lỗi hoặc cần đáp ứng quy định kỹ thuật về chất lượng điện năng của EVN, giải pháp AHF chính là sự lựa chọn tối ưu.</p>\n<p><strong>Liên hệ Cycle Electric</strong> ngay hôm nay để được kỹ sư chuyên môn khảo sát và tư vấn giải pháp lọc sóng hài tối ưu nhất cho hệ thống của bạn.</p>', NULL, 1, 0, '3', 1, NULL, '2026-09-16', NULL, NULL, NULL, NULL, NULL, '', '', '', 0),
(4, 'bo-luu-tru-nang-luong-bess', 'BỘ LƯU TRỮ NĂNG LƯỢNG (BESS)', NULL, NULL, '', '', 'fas fa-battery-full', 'Hệ thống pin lưu trữ năng lượng BESS làm mát không khí, làm mát chất lỏng, container ESS và bộ lưu trữ năng lượng dân dụng / công nghiệp.', NULL, 1, 0, '4', 1, NULL, '2026-09-16', NULL, NULL, NULL, NULL, NULL, '', '', '', 0),
(5, 'lam-mat-tu-dien-rittal', 'LÀM MÁT & PHỤ KIỆN TỦ ĐIỆN RITTAL', NULL, NULL, '', '', 'fas fa-fan', 'Máy lạnh tủ điện Rittal TopTherm, Blue e, quạt hút nóc EC, quạt gắn phin lọc và phụ kiện điều khiển nhiệt độ, độ ẩm tủ điện tiêu chuẩn IP54, IP55.', NULL, 1, 0, '5', 1, NULL, '2026-09-16', NULL, NULL, NULL, NULL, NULL, '', '', '', 0),
(6, 'dong-ho-do-da-nang', 'ĐỒNG HỒ ĐO ĐA NĂNG', '', '', '', '', 'fas fa-tachometer-alt', 'Đồng hồ đo đa năng LOVATO DMG series cao cấp (DMG500, DMG510, DMG600, DMG610, DMG615, DMG7000, DMG7500, DMG8000, DMG9000).', NULL, 1, 0, '6', 1, NULL, '2026-09-16', NULL, NULL, NULL, NULL, NULL, '', '', '', 0),
(7, 'bien-tan-inverter', 'BIẾN TẦN INVERTER', NULL, NULL, '', '', 'fas fa-solar-panel', 'Biến tần năng lượng mặt trời Sungrow hiệu suất cao, ổn định và bền bỉ.', NULL, 1, 0, '7', 1, NULL, '2026-09-16', NULL, NULL, NULL, NULL, NULL, '', '', '', 0);

