INSERT INTO `cycletech_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `ctype`, `ccode`, `cproducts`, `cloai_tin`, `ctag`, `nview`, `fprice`, `fprice_sale`, `cdescription`, `fb_cdescription`, `cgioi_thieu`, `cdia_diem`, `nid_loai_tin`, `nid_loai_bds`, `nid_province`, `nid_district`, `nid_huong`, `cdien_tich`, `eng_cdetail`, `cdetail`, `cimage`, `cproduct_fb`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nhome`, `nnew`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `ctime_update`, `cphong_an`, `cnha_bep`, `csan_thuong`, `ccho_de_xe`, `cchinh_chu`, `cchieu_ngang`, `cchieu_dai`, `cso_lau`, `cso_phong_ngu`, `cphap_ly`, `cduong_truoc_nha`, `nspecial`, `ccode_product`, `ckeyword`) VALUES
(1, 4, 15, 0, NULL, 'container-luu-tru-nang-luong-bess-lam-mat-bang-khong-khi-eco-e20ft2860ws', 'Container lưu trữ năng lượng BESS làm mát bằng không khí ECO-E20FT2860WS', NULL, '', NULL, 220000, 190000, '\r\n<p>Container pin lưu trữ năng lượng ESS Làm mát bằng không khí, Model: ECO-E20FT2860WS Sản phẩm container lưu trữ năng lượng ESS làm mát bằng không khí 20 ft được tích hợp hệ thống PACK, BMS, PCS, EMS, HVAC và phòng...</p>\r\n<script data-ts=\"1743739391117\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Container lưu trữ năng lượng BESS làm mát bằng không khí ECO-E20FT2860WS', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Container pin lưu trữ năng lượng ESS Làm mát bằng không khí,</strong></p>\r\n\r\n<p><strong>Model: ECO-E20FT2860WS</strong></p>\r\n\r\n<p>Sản phẩm container lưu trữ năng lượng ESS làm mát bằng không khí 20 ft được tích hợp hệ thống PACK, BMS, PCS, EMS, HVAC và phòng cháy chữa cháy trong một container với những ưu điểm như mật độ năng lượng cao, vận chuyển dễ dàng, lắp đặt nhanh và mức độ bảo vệ cao. Với điện áp đầu ra AC 690Vac, nó có thể được nối vào lưới ở cấp điện áp từ 6kV trở lên kết hợp với máy biến áp tăng áp. Sản phẩm container ESS làm mát bằng không khí dài 20 ft có thể được áp dụng cho phía phát điện, phía lưới điện cũng như các kịch bản C&amp;I ESS có yêu cầu nghiêm ngặt về công suất và năng lượng.</p>\r\n\r\n<p><strong>Tính năng sản phẩm</strong></p>\r\n\r\n<ul>\r\n	<li>An toàn và tin cậy: Mật độ năng lượng cao, tuổi thọ cao và độ tin cậy với bin LFP chất lượng</li>\r\n	<li>Điều khiển nhiệt độ thông minh: Nhiệt độ thay đổi nhỏ hơn 6*C trên cả hệ thống</li>\r\n	<li>Kết nối String thông minh: Chiến lược một cluster pin một mô-đun-PCS để đạt được sự kiểm soát chính xác tính nhất quán của tế bào</li>\r\n	<li>Điều khiển nhiệt độ chính xác: Mỗi bộ điều hòa tương ứng với một ngăn chứa pin để kiểm soát thông gió một cách nhất quán và chính xác.</li>\r\n	<li>Kinh tế và hiệu quả: Tiêu thụ năng lượng tự dùng thấp và hiệu suất sạc/xả cao, hỗ trợ nhiều tình huống khác nhau như lưới điện siêu nhỏ, nguồn điện dự phòng, khởi động đen, đáp ứng nhu cầu.</li>\r\n	<li>Bảo trì thông minh: Kiến trúc BMS &amp; EMS ba cấp để đạt được khả năng giám sát thời gian thực về PACK, PCS, HVAC, an toàn cháy nổ, v.v. để giảm chi phí và kế hoạch O&amp;M</li>\r\n</ul>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<table>\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<p><strong>Mục</strong></p>\r\n			</td>\r\n			<td>\r\n			<p><strong>Thông số kỹ thuật</strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p>Phần DC</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Loại cell</p>\r\n			</td>\r\n			<td>\r\n			<p>LFP</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Thông số Cell</p>\r\n			</td>\r\n			<td>\r\n			<p>3.2V/280Ah</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấu hình</p>\r\n			</td>\r\n			<td>\r\n			<p>8*1P400S</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Năng lượng lưu trữ danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>2867.2kWh</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Giải điện áp</p>\r\n			</td>\r\n			<td>\r\n			<p>1120~1460V</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Rated Charge/Discharge Rate</p>\r\n			</td>\r\n			<td>\r\n			<p>0.5P</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p><strong>Phần AC</strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Công suất danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>1433.6kW</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Điện áp định mức</p>\r\n			</td>\r\n			<td>\r\n			<p>AC690V</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Tần số danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>50Hz/60Hz</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấu hình PCS</p>\r\n			</td>\r\n			<td>\r\n			<p>200kW/module</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Số lượng PCS</p>\r\n			</td>\r\n			<td>\r\n			<p>8 units</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Phương pháp cách ly</p>\r\n			</td>\r\n			<td>\r\n			<p>Non-transformer isolation</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Làm mát PCS</p>\r\n			</td>\r\n			<td>\r\n			<p>Air cooling</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p><strong>Thông số chung</strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Kích thước (W*H*D):</p>\r\n			</td>\r\n			<td>\r\n			<p>6058*2438*2896mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Khối lượng</p>\r\n			</td>\r\n			<td>\r\n			<p>28t</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấp độ bảo vệ</p>\r\n			</td>\r\n			<td>\r\n			<p>IP55</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Nhiệt độ làm việc</p>\r\n			</td>\r\n			<td>\r\n			<p>-25℃ to 55℃ (giảm công suất nếu nhiệt độ &gt;45℃)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Độ ẩm</p>\r\n			</td>\r\n			<td>\r\n			<p>0% to 95% (Không đọng sương)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cao độ</p>\r\n			</td>\r\n			<td>\r\n			<p>2000m (derating above 2,000m)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Làm mát</p>\r\n			</td>\r\n			<td>\r\n			<p>Gió cưỡng bức với điều khiển nhiệt độ</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>An toàn cháy nổ</p>\r\n			</td>\r\n			<td>\r\n			<p>Bảo vệ chống cháy với khí 1230, phát hiện khí nguy hiểm + xả + bảo vệ lửa với nước</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Truyền thông</p>\r\n			</td>\r\n			<td>\r\n			<p>Ethernet</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1743739391113\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'container-ess_20250404060311.png', 'container-ess_20250404060311.png', 'resize_container-ess_20250404060311.png', 0, '', NULL, 1, 0, 0, 1, '1', 1, 1, '2025-02-11', '2025-04-04', '1743739391', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(2, 4, 16, 0, NULL, 'tu-pin-luu-tru-nang-luong-bess-lam-mat-bang-chat-long-eco-b372ls', 'Tủ pin lưu trữ năng lượng BESS Làm mát bằng chất lỏng ECO-B372LS', NULL, '', NULL, 220000, 190000, '\r\n<p>Tủ pin lưu trữ năng lượng BESS Làm mát bằng chất lỏng ECO-B372LS Tủ pin làm mát bằng chất lỏng áp dụng chiến lược cân bằng nhiệt độ và làm mát bằng chất lỏng ở cấp độ tủ tiên tiến. Chênh lệch...</p>\r\n<script data-ts=\"1743741392898\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Tủ pin lưu trữ năng lượng BESS Làm mát bằng chất lỏng ECO-B372LS', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Tủ pin lưu trữ năng lượng BESS Làm mát bằng chất lỏng</strong></p>\r\n\r\n<p><strong>ECO-B372LS</strong></p>\r\n\r\n<p>Tủ pin làm mát bằng chất lỏng áp dụng chiến lược cân bằng nhiệt độ và làm mát bằng chất lỏng ở cấp độ tủ tiên tiến. Chênh lệch nhiệt độ tế giữa các cell nhỏ hơn 3°C, giúp cải thiện hơn nữa tính nhất quán của nhiệt độ cell và kéo dài tuổi thọ pin. Thiết kế mô-đun giúp giải pháp song song trở nên linh hoạt hơn và có thể kết hợp với PCS tập trung để tạo thành ESS với mật độ năng lượng cao hơn, giúp cải thiện đáng kể tính kinh tế, an toàn và thuận tiện khi xây dựng của các dự án ESS.</p>\r\n\r\n<p><strong>Tính năng sản phẩm</strong></p>\r\n\r\n<ul>\r\n	<li>Kích thước nhỏ gọn: giảm kích thước so với cùng công suất làm mát bằng khí</li>\r\n	<li>Mật độ năng lượng cao: lưu trữ 233kWh trong 1 tủ và đảm bảo độ bền lâu dài</li>\r\n	<li>Hiệu suất: Thiết kế tối ưu cấu trúc PACK, đạt hiệu quả làm mát cao và tiêu thụ năng lượng thấp</li>\r\n	<li>Độ bền cao: Tuổi thọ pin lên tới 8000 lần xạc xả, hiệu suất tuyệt vời của hệ thống pin</li>\r\n	<li>Dễ dàng mở rộng: Thiết kế module, dễ dàng mở rộng</li>\r\n	<li>An toàn cao: An toàn cháy nổ trong PACK với ba cấp độ bảo vệ, ngăn chặn sự thoát nhiệt.</li>\r\n</ul>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<table>\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<p><strong>Mục</strong></p>\r\n			</td>\r\n			<td>\r\n			<p><strong>Thông số kỹ thuật</strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấu hình</p>\r\n			</td>\r\n			<td>\r\n			<p>1P416S</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Năng lượng lưu trữ</p>\r\n			</td>\r\n			<td>\r\n			<p>372kWh</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Điện áp định mức</p>\r\n			</td>\r\n			<td>\r\n			<p>1331.2Vdc</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Giải điện áp Dc</p>\r\n			</td>\r\n			<td>\r\n			<p>1165-1498Vdc</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấp độ bảo vệ của PACK</p>\r\n			</td>\r\n			<td>\r\n			<p>IP65</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Rated Charge/Discharge Rate</p>\r\n			</td>\r\n			<td>\r\n			<p>0.5C</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Max. Charge/Discharge Rate</p>\r\n			</td>\r\n			<td>\r\n			<p>0.6C（60s）</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Nhiệt độ hoạt động</p>\r\n			</td>\r\n			<td>\r\n			<p>-20℃~55℃</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>An toàn cháy nổ</p>\r\n			</td>\r\n			<td>\r\n			<p>Phát hiện khí dễ cháy/phát hiện khói/phát hiện nhiệt độ + cảnh báo chủ động + ngăn chặn cháy cấp mô-đun (Perfluoro)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấp độ bảo vệ tủ</p>\r\n			</td>\r\n			<td>\r\n			<p>IP55</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Làm mát</p>\r\n			</td>\r\n			<td>\r\n			<p>Chiller+in-PACK cooling</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cao độ</p>\r\n			</td>\r\n			<td>\r\n			<p>≤2000m（derating above 2,000m）</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Kích thước (R*C*S)</p>\r\n			</td>\r\n			<td>\r\n			<p>1300*1300*2400（mm）</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Tiêu chuẩn</p>\r\n			</td>\r\n			<td>\r\n			<p>UN38.3、IEC62619、UL1973、UL9540、CE-EMC</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1743741392892\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', '3e-battery-cabinet_20250404063633.png', '3e-battery-cabinet_20250404063633.png', 'resize_3e-battery-cabinet_20250404063633.png', 0, '', NULL, 1, 0, 0, 1, '2', 1, 1, '2025-02-11', '2025-04-04', '1743741393', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(3, 4, 16, 0, NULL, 'tu-luu-tru-nang-luong-bess-lam-mat-bang-chat-long-eco-e233ls', 'Tủ lưu trữ năng lượng BESS Làm mát bằng chất lỏng ECO-E233LS', NULL, '', NULL, 220000, 190000, '\r\n<p>Tủ lưu trữ năng lượng ESS làm mát bằng chất lỏng Model: ECO-E233LS Tủ ESS làm mát bằng chất lỏng tất cả trong một áp dụng chiến lược cân bằng nhiệt độ và làm mát bằng chất lỏng ở cấp độ tủ...</p>\r\n<script data-ts=\"1743741507307\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Tủ lưu trữ năng lượng BESS Làm mát bằng chất lỏng ECO-E233LS', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>Tủ lưu trữ năng lượng ESS làm mát bằng chất lỏng</p>\r\n\r\n<p>Model: ECO-E233LS</p>\r\n\r\n<p>Tủ ESS làm mát bằng chất lỏng tất cả trong một áp dụng chiến lược cân bằng nhiệt độ và làm mát bằng chất lỏng ở cấp độ tủ tiên tiến. Chênh lệch nhiệt độ cho từng cell pin nhỏ hơn 3°C, giúp cải thiện hơn nữa tính nhất quán của nhiệt độ cell pin và kéo dài tuổi thọ pin. Thiết kế mô-đun giúp giải pháp vận hành song song các tủ ESS linh hoạt hơn và có mật độ năng lượng cao hơn, giúp cải thiện đáng kể tính kinh tế, an toàn và thuận tiện trong xây dựng của các dự án ESS.</p>\r\n\r\n<p>Tính năng sản phẩm</p>\r\n\r\n<ul>\r\n	<li>Cấu trúc nhỏ gọn; Diện tích lắp đặt chỉ 1.4m2, Giảm diện tích lắp đặt tới 35% so với loại làm mát bằng khí.</li>\r\n	<li>Mật độ năng lượng cao: lưu trữ 233kWh trong 1 tủ và đảm bảo độ bền lâu dài</li>\r\n	<li>Hiệu suất: Thiết kế tối ưu cấu trúc PACK, đạt hiệu quả làm mát cao và tiêu thụ năng lượng thấp</li>\r\n	<li>Độ bền cao: Tuổi thọ pin lên tới 8000 lần xạc xả, hiệu suất tuyệt vời của hệ thống pin</li>\r\n	<li>Dễ dàng mở rộng: Thiết kế module, dễ dàng mở rộng</li>\r\n	<li>An toàn cao: An toàn cháy nổ trong PACK với ba cấp độ bảo vệ, ngăn chặn sự thoát nhiệt</li>\r\n</ul>\r\n\r\n<p>Thông số kỹ thuật</p>\r\n\r\n<table>\r\n	<tbody>\r\n		<tr>\r\n			<td rowspan=\"2\">\r\n			<p>Mục</p>\r\n			</td>\r\n			<td rowspan=\"2\">\r\n			<p>Thông số kỹ thuật</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p>Phần DC</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cell type</p>\r\n			</td>\r\n			<td>\r\n			<p>LFP 3.2V/280Ah</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>PACK</p>\r\n			</td>\r\n			<td>\r\n			<p>46.6kWh/1P52S</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Công suất pin</p>\r\n			</td>\r\n			<td>\r\n			<p>233kWh/1P260S</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Giải điện áp hoạt động</p>\r\n			</td>\r\n			<td>\r\n			<p>728-936Vdc</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấp độ bảo vệ PACK</p>\r\n			</td>\r\n			<td>\r\n			<p>IP65</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p>Phần AC</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Công suất danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>100kW</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Công suất lớn nhất</p>\r\n			</td>\r\n			<td>\r\n			<p>110kW</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>THDi</p>\r\n			</td>\r\n			<td>\r\n			<p>＜3%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<ul>\r\n				<li>DC Ratio</li>\r\n			</ul>\r\n			</td>\r\n			<td>\r\n			<p>＜0.5%Ipn</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Điện áp danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>400Vac</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Hệ số công suất</p>\r\n			</td>\r\n			<td>\r\n			<p>-1 lagging~1 leading</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Tần số danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>50Hz/60Hz</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p>Thông số chung</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td rowspan=\"2\">\r\n			<p>Hiệu suất của hệ thống</p>\r\n			</td>\r\n			<td rowspan=\"2\">\r\n			<p>≥91%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Charge/Discharge Rate</p>\r\n			</td>\r\n			<td>\r\n			<p>≤0.5P</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>DoD</p>\r\n			</td>\r\n			<td>\r\n			<p>95%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>SOC Accuracy</p>\r\n			</td>\r\n			<td>\r\n			<p>＜3%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cycle Life</p>\r\n			</td>\r\n			<td>\r\n			<p>≥8000 lần</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Switching Time</p>\r\n			</td>\r\n			<td>\r\n			<p>＜100ms</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Truyền thông</p>\r\n			</td>\r\n			<td>\r\n			<p>Ethernet /RS485</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấp độ bảo vệ</p>\r\n			</td>\r\n			<td>\r\n			<p>IP55</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Loại làm mát</p>\r\n			</td>\r\n			<td>\r\n			<p>Làm mát bằng chất lỏng</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Nhiệt độ làm việc</p>\r\n			</td>\r\n			<td>\r\n			<p>-25~55℃</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Độ ẩm</p>\r\n			</td>\r\n			<td>\r\n			<p>5~95%RH，Không đọng sương</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Độ ồn</p>\r\n			</td>\r\n			<td>\r\n			<p>≤75dB</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cao độ</p>\r\n			</td>\r\n			<td>\r\n			<p>＜2000m（Giảm công suất nếu trên 2,000m)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>An toàn cháy nổ</p>\r\n			</td>\r\n			<td>\r\n			<p>Phát hiện khí dễ cháy/phát hiện khói/phát hiện nhiệt độ + cảnh báo chủ động + ngăn chặn cháy cấp mô-đun (Perfluoro)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Kích thước (R*S*C)</p>\r\n			</td>\r\n			<td>\r\n			<p>1050*1350*2400（mm）</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Khối lượng</p>\r\n			</td>\r\n			<td>\r\n			<p>2800kg</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Tiêu chuẩn đáp ứng</p>\r\n			</td>\r\n			<td>\r\n			<p>UN38.3、IEC61619、UL1973、UL9540 、CE-EMC</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1743741507301\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'liquid-cabinet_20250404063827.png', 'liquid-cabinet_20250404063827.png', 'resize_liquid-cabinet_20250404063827.png', 0, '', NULL, 1, 1, 0, 0, '3', 1, 1, '2025-02-11', '2025-04-04', '1743741507', '', '', '', '', '', '', '', '', '', '', '', 1, '', ''),
(4, 4, 16, 0, NULL, 'tu-pin-luu-tru-nang-luong-ess-lam-mat-bang-khong-khi-eco-e215ws', 'Tủ Pin lưu trữ năng lượng ESS Làm mát bằng không khí: ECO-E215WS', NULL, '', NULL, 220000, 190000, '\r\n<p>Tủ pin lưu trữ năng lượng ESS làm mát bằng không khí Model: ECO-E215WS Tủ lưu trữ điện năng ESS làm mát bằng không khí được tích hợp pin có tuổi thọ cao, BMS cân bằng hai chiều hiệu quả, PCS hiệu...</p>\r\n<script data-ts=\"1743741705520\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Tủ Pin lưu trữ năng lượng ESS Làm mát bằng không khí: ECO-E215WS', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Tủ pin lưu trữ năng lượng ESS làm mát bằng không khí</strong></p>\r\n\r\n<p><strong>Model: ECO-E215WS</strong></p>\r\n\r\n<p>Tủ lưu trữ điện năng ESS làm mát bằng không khí được tích hợp pin có tuổi thọ cao, BMS cân bằng hai chiều hiệu quả, PCS hiệu suất cao, hệ thống an toàn chủ động, phân phối thông minh và HVAC trong một tủ, cho phép vận hành lâu dài với độ an toàn, ổn định và độ tin cậy. Thông qua kết nối song song phía AC, nó giúp triển khai nhanh chóng hệ thống lưu trữ điện năng ESS với khả năng mở rộng công suất linh hoạt</p>\r\n\r\n<p><strong>Tính năng sản phẩm</strong></p>\r\n\r\n<ul>\r\n	<li>Tiết kiệm và hiệu quả: Hiệu suất chuyển đổi trên 90%, độ sâu xả pin (DoD) lớn hơn 95%.</li>\r\n	<li>An toàn và tin cậy: Cấp độ bảo vệ IP55, tối ưu thiết kế thông gió, nhiệt độ cell pin thay đổi nhỏ hơn 5*C</li>\r\n	<li>Kích thước nhỏ gọn: Chỉ 1.6m2 dễ dàng vận chuyển và lắp đặt</li>\r\n	<li>Dễ dàng mở rộng: Thiết kế module, dễ dàng mở rộng vận hành song song</li>\r\n	<li>Tự phát triển: đội ngũ R&amp;D nhiều kinh nghiệm, tự sản xuất PCS, BMS và EMS với chất lượng cao</li>\r\n	<li>Vận hành và bảo trì thông minh: Giám sát vận hành qua APP và cloud</li>\r\n</ul>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<table>\r\n	<tbody>\r\n		<tr>\r\n			<td rowspan=\"2\">\r\n			<p><strong>Mục</strong></p>\r\n			</td>\r\n			<td rowspan=\"2\">\r\n			<p><strong>Thông số kỹ thuật</strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p>Phần DC</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cell type</p>\r\n			</td>\r\n			<td>\r\n			<p>LFP 3.2V/280Ah</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>PACK</p>\r\n			</td>\r\n			<td>\r\n			<p>17.92kWh/1P20S</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Công suất pin</p>\r\n			</td>\r\n			<td>\r\n			<p>215kWh/1P240S</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Giải điện áp hoạt động</p>\r\n			</td>\r\n			<td>\r\n			<p>672-894Vdc</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Điện áp định mức</p>\r\n			</td>\r\n			<td>\r\n			<p>768VDC</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p>Phần AC</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Công suất danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>100kW</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Công suất lớn nhất</p>\r\n			</td>\r\n			<td>\r\n			<p>110kW (60s)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>THDi</p>\r\n			</td>\r\n			<td>\r\n			<p>＜3%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>DC Ratio</p>\r\n			</td>\r\n			<td>\r\n			<p>＜0.5%Ipn</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Điện áp danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>400Vac</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Hệ số công suất</p>\r\n			</td>\r\n			<td>\r\n			<p>-1 lagging~1 leading</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Tần số danh định</p>\r\n			</td>\r\n			<td>\r\n			<p>50Hz/60Hz</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<p>Thông số chung</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td rowspan=\"2\">\r\n			<p>Hiệu suất của hệ thống</p>\r\n			</td>\r\n			<td rowspan=\"2\">\r\n			<p>≥90%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Charge/Discharge Rate</p>\r\n			</td>\r\n			<td>\r\n			<p>≤0.5P</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>DoD</p>\r\n			</td>\r\n			<td>\r\n			<p>95%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cycle Life</p>\r\n			</td>\r\n			<td>\r\n			<p>≥8000 lần</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Switching Time</p>\r\n			</td>\r\n			<td>\r\n			<p>＜100ms</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Truyền thông</p>\r\n			</td>\r\n			<td>\r\n			<p>Ethernet /RS485</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cấp độ bảo vệ</p>\r\n			</td>\r\n			<td>\r\n			<p>IP55</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Loại làm mát</p>\r\n			</td>\r\n			<td>\r\n			<p>Làm mát bằng khí cưỡng bức</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Nhiệt độ làm việc</p>\r\n			</td>\r\n			<td>\r\n			<p>-25~55℃</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Độ ẩm</p>\r\n			</td>\r\n			<td>\r\n			<p>5~95%RH，Không đọng sương</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Độ ồn</p>\r\n			</td>\r\n			<td>\r\n			<p>≤75dB</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Cao độ</p>\r\n			</td>\r\n			<td>\r\n			<p>＜2000m（Giảm công suất nếu trên 2,000m)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>An toàn cháy nổ</p>\r\n			</td>\r\n			<td>\r\n			<p>Aerosol và cảnh báo chủ động</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Kích thước (R*S*C)</p>\r\n			</td>\r\n			<td>\r\n			<p>1250*1300*2400（mm）</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Khối lượng</p>\r\n			</td>\r\n			<td>\r\n			<p>2500kg</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Tiêu chuẩn đáp ứng</p>\r\n			</td>\r\n			<td>\r\n			<p>UN38.3、IEC61619、UL1973、UL9540 、CE-EMC</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1743741705515\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', '1_20250404064145.png', '1_20250404064145.png', 'resize_1_20250404064145.png', 0, '', NULL, 1, 1, 0, 0, '4', 1, 1, '2025-02-11', '2025-04-04', '1743741705', '', '', '', '', '', '', '', '', '', '', '', 1, '', ''),
(5, 4, 17, 0, NULL, 'bo-pin-luu-tru-nang-luong-dan-dung', 'Bộ pin lưu trữ năng lượng dân dụng', NULL, '', NULL, 220000, 190000, '\r\n<p>Bộ lưu trữ năng lượng dân dụng hay hệ thống lưu trữ năng lượng hộ gia đình hoặc gọi đơn giản là pin lưu trữ là hệ thống sử dụng công nghệ lưu trữ năng lượng bằng pin Lithium để lưu trữ điện được sản xuất để sử dụng trong nhà trong tương lai.</p>\r\n<script data-ts=\"1743742303051\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ pin lưu trữ năng lượng dân dụng', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Bộ pin&nbsp;lưu trữ năng lượng dân dụng</strong>&nbsp;hay hệ thống lưu trữ năng lượng hộ gia đình hoặc gọi đơn giản là pin lưu trữ&nbsp;là hệ thống sử dụng công nghệ lưu trữ năng lượng bằng pin Lithium để lưu trữ điện được sản xuất để sử dụng trong nhà trong tương lai.</p>\r\n\r\n<p>Hệ thống lưu trữ năng lượng được sử dụng để lưu trữ điện năng trong giờ thấp điểm và sử dụng&nbsp;trong giờ cao điểm để bù đắp cho sự thiếu hụt điện năng tiêu thụ. Bộ lưu trữ năng lượng ESS còn được sử dụng để tích trữ&nbsp;năng lượng được sản xuất ra bởi các hệ năng lượng mặt trời áp mái trong các giờ trưa nắng và sử dụng lại tại các khung giờ ít nắng hoặc sử dụng vào ban đêm.</p>\r\n\r\n<p><img alt=\"Bộ pin lưu trữ năng lượng dân dụng\" data-thumb=\"original\" original-height=\"507\" original-width=\"898\" src=\"https://bizweb.dktcdn.net/100/445/560/files/bo-luu-tru-nang-luong-dan-dung.png?v=1690874369031\"></p>\r\n\r\n<p>Tần suất mất điện ngày càng tăng do điều kiện thời tiết khắc nghiệt trên khắp thế giới trong những năm gần đây cũng đã nâng cao nhận thức về nhu cầu lắp đặt hệ thống pin lưu trữ năng lượng của các hộ gia đình, có thể hỗ trợ hoạt động của các cơ sở như dịch vụ thoát hiểm, y tế và cứu hộ nếu xảy ra sự cố. thiên tai xảy ra và gây mất điện.</p>\r\n\r\n<p>Bộ lưu trữ năng lượng của Elecnova với hiệu suất cao và tuổi thọ dài đáp ứng mọi nhu cầu của các hộ gia đình. Dòng sản phẩm bộ lưu trữ năng lượng Elecnova được chia thành 3 sản phẩm chính</p>\r\n\r\n<p><strong>1. Loại treo tường: SFR-HES-W</strong></p>\r\n\r\n<p>Là sản phẩm được thiết kế với mẫu nhỏ gọn và để treo tường trong nhà hoặc ngoài hiên, giúp tăng thẩm mỹ của ngôi nhà</p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"1394\" original-width=\"912\" src=\"https://bizweb.dktcdn.net/100/445/560/files/bo-luu-tru-nang-luong-gia-dinh.jpg?v=1690877470981\"></p>\r\n\r\n<p><strong>2. Bộ lưu trữ năng lượng gia đình điện áp thấp - SFR-HES-L</strong></p>\r\n\r\n<p>Với dòng sản phẩm này, Elecnova cung cấp 3 dải công suất 15.36kWh, 20.48kWh, 25.6kWh giúp đảm bảo nhu cầu cho gia đình cỡ vừa có khoảng 3 - 4 phòng ngủ.</p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"1400\" original-width=\"930\" src=\"https://bizweb.dktcdn.net/100/445/560/files/bo-luu-tru-nang-luong-gia-dinh-3.jpg?v=1690877588442\"></p>\r\n\r\n<p><strong>3. Bộ lưu trữ năng lượng công suất cao&nbsp;</strong></p>\r\n\r\n<p>Với dòng sản phẩm này, Elecnova chú trọng tới các khách hàng muốn lưu thời gian dài hoặc có nhu cầu sử dụng nhiều.</p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"1378\" original-width=\"952\" src=\"https://bizweb.dktcdn.net/100/445/560/files/bo-luu-tru-nang-luong-gia-dinh-5.jpg?v=1690877800415\"></p>\r\n\r\n<p>Với các sản phẩm của Elecnova, chúng tôi cam kết:</p>\r\n\r\n<p>&nbsp; - Toàn bộ pin chúng tôi sử dụng là GRADE A</p>\r\n\r\n<p>&nbsp; - Bảo hành 5 - 10 năm tùy theo dải công suất</p>\r\n\r\n<p>&nbsp; - Thích hợp với đa số Inverter</p>\r\n<script data-ts=\"1743742303049\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'bo-luu-tru-nang-luong-gia-dinh-6_20250404065143.jpg', 'bo-luu-tru-nang-luong-gia-dinh-6_20250404065143.jpg', 'resize_bo-luu-tru-nang-luong-gia-dinh-6_20250404065143.jpg', 0, '', NULL, 1, 0, 0, 0, '5', 1, 1, '2025-02-11', '2025-04-04', '1743742303', '', '', '', '', '', '', '', '', '', '', '', 1, '', ''),
(6, 4, 16, 0, NULL, 'bo-luu-tru-nang-luong-ess-cong-nghiep', 'Bộ lưu trữ năng lượng (ESS) công nghiệp', NULL, '', NULL, 220000, 190000, '\r\n<p>Bộ&nbsp;lưu trữ năng lượng (ESS) hay đơn giản&nbsp;là&nbsp;bộ lưu trữ năng lượng ESS&nbsp;là một thiết bị&nbsp;được sử dụng để lưu trữ năng lượng và cung cấp lại để sử dụng sau này. Hệ thống lưu trữ năng lượng nói chung...</p>\r\n<script data-ts=\"1743748598552\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ lưu trữ năng lượng (ESS) công nghiệp', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Bộ&nbsp;lưu trữ năng lượng (ESS)&nbsp;</strong>hay đơn giản&nbsp;là&nbsp;bộ lưu trữ năng lượng ESS&nbsp;là một thiết bị&nbsp;được sử dụng để lưu trữ năng lượng và cung cấp lại để sử dụng sau này. Hệ thống lưu trữ năng lượng nói chung có thể bao gồm: Pin, hóa chất, điện hóa, cơ khí và nhiệt, .</p>\r\n\r\n<p><strong>Bộ lưu trữ năng lượng (ESS)</strong>&nbsp;của Elecnova, model: ECO-ESS là bộ&nbsp;lưu trữ năng lượng sử dụng công nghệ Pin và công nghệ chuyển đổi tiên tiến. Hệ thống lưu trữ năng lượng của Elecnova giúp dễ dàng lưu trữ và cung cấp năng lượng ở đâu và khi cần thiết tạo ra một cơ sở hạ tầng năng lượng linh hoạt hơn và tiết kiệm chi phí cho người tiêu dùng và Hơn nữa, những điều này đảm bảo độ tin cậy và ổn định của hệ thống bằng cách đáp ứng nhanh chóng với nguồn điện biến động.</p>\r\n\r\n<p><strong>Bộ&nbsp;lưu trữ năng lượng (ESS) Elecnova</strong>&nbsp;giúp lưu trữ năng lượng sạch từ các hệ năng lượng mặt trời hoặc hệ điện gió.&nbsp; Ngay cả khi mặt trời không chiếu sáng hoặc không có gió, bộ lưu trữ năng lượng vẫn&nbsp;lưu trữ năng lượng dựa trên lưới điện và&nbsp;giúp có thể giải quyết gián đoạn năng lượng mặt trời hoặc gió và cung cấp năng lượng sạch một cách nhất quán cho các ứng dụng dân cư, thương mại và công nghiệp.&nbsp;</p>\r\n\r\n<p><strong>Dòng sản phẩm&nbsp;bộ lưu trữ năng lượng ESS&nbsp;công nghiệp</strong>ECO<strong>-ESS&nbsp;của Elecnova</strong>&nbsp;được thiết kế với dải công suất từ 50kW - 500KW, để phù hợp với các ứng dụng trong các nhà xưởng hoặc các trung tâm thương mại, tòa nhà, các nhà máy.</p>\r\n\r\n<p>Hãy cùng tìm hiểu nguyên lý cấu tạo như phía dưới đây:</p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"880\" original-width=\"936\" src=\"https://bizweb.dktcdn.net/100/445/560/files/ess-software.jpg?v=1686033479497\"></p>\r\n\r\n<p><strong>1. Các thành phần chính của b</strong><strong>ộ lưu trữ năng lượng ESS - ECO-ESS Elecnova</strong></p>\r\n\r\n<p>Một bộ lưu trữ năng lượng (ESS) ECO-ESS bao gồm hai thành phần chính:<br>\r\n<strong>- Hệ thống chuyển đổi nguồn (PCS)</strong>&nbsp;xử lý chuyển đổi AC-to-DC và DC-to-AC (AC –Dòng điện xoay chiều và Dòng điện một chiều - Dòng điện một chiều là các loại năng lượng điện tái tạo), với năng lượng sạc vào pin để sạc pin hoặc được chuyển đổi từ bộ lưu trữ pin thành nguồn điện xoay chiều và được cung cấp vào lưới.</p>\r\n\r\n<p><strong>- Hệ thống quản lý pin (BMS)</strong>&nbsp;chịu trách nhiệm sạc pin, cân bằng và giám sát tình trạng pin&nbsp;cùng với một bộ vi điều khiển cung cấp khả năng điều khiển và liên lạc giữa các hệ thống.</p>\r\n\r\n<p><strong>2. Sơ đồ nguyên lý và cấu trúc sản phẩm</strong></p>\r\n\r\n<p><strong>Sơ đồ nguyên lý</strong></p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"636\" original-width=\"1158\" src=\"https://bizweb.dktcdn.net/100/445/560/files/elecnova-ess-single-line-diagram.jpg?v=1686032277232\"></p>\r\n\r\n<p><strong>Cấu trúc sản phẩm</strong></p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"584\" original-width=\"1972\" src=\"https://bizweb.dktcdn.net/100/445/560/files/bcm-structure-copy.jpg?v=1686032311055\"><img data-thumb=\"original\" original-height=\"1270\" original-width=\"2248\" src=\"https://bizweb.dktcdn.net/100/445/560/files/bcm-structure-2-copy.jpg?v=1686032312270\"></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>3. Các ứng dụng của bộ lưu trữ năng lượng ESS Elecnova</strong></p>\r\n\r\n<p>- Sử dụng để lưu trữ năng lượng cho các hệ năng lượng mặt trời, điện gió, năng lượng tái tạo và sử dụng lại sau này. Thông thường là các hệ điện mặt trời áp mái cho các nhà xưởng hoặc các hệ điện gió nhỏ</p>\r\n\r\n<p>- Sử dụng để lưu trữ điện tại thời điểm thấp điểm và bán lại vào lúc cao điểm.</p>\r\n\r\n<p>- Sử dụng cho môi trường bền vững, giảm thải carbon, giúp đạt được các chứng chỉ bền vững cho các nhà máy/ cơ sở sản xuất kinh doanh</p>\r\n\r\n<p>- Chủ động trong việc sử dụng điện và quản lý điện năng</p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"662\" original-width=\"1138\" src=\"https://bizweb.dktcdn.net/100/445/560/files/ess-application-2.jpg?v=1686067869338\"></p>\r\n\r\n<p><strong>4. Lợi ích của bộ lưu trữ năng lượng ESS Elecnova</strong></p>\r\n\r\n<p><img alt=\"☘️\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t95/2/16/2618.png\" width=\"16\">&nbsp;Tiết kiệm điện (khi dùng kết hợp với hệ năng lượng mặt trời)</p>\r\n\r\n<p><img alt=\"☘️\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t95/2/16/2618.png\" width=\"16\">&nbsp;Tiết kiệm điện lên đến 3000VNĐ/Kwh đối với cơ sở sản xuất kinh doanh (nhờ chênh lệch trong giờ thấp điểm/ cao điểm)</p>\r\n\r\n<p><img alt=\"☘️\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t95/2/16/2618.png\" width=\"16\">&nbsp;Sử dụng năng lượng độc lập</p>\r\n\r\n<p><img alt=\"☘️\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t95/2/16/2618.png\" width=\"16\">&nbsp;Giá sử dụng điện rẻ hơn so với sử dụng qua máy phát điện thông thường</p>\r\n\r\n<p><img alt=\"☘️\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t95/2/16/2618.png\" width=\"16\">&nbsp;Góp phần vào giảm thải carbon vì môi trường bên vững</p>\r\n\r\n<p><img alt=\"☘️\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t95/2/16/2618.png\" width=\"16\">&nbsp;Tăng giá trị căn nhà/ cơ sở sản xuất/ kinh doanh khi cam kết cho môi trường bền vững</p>\r\n\r\n<p><img alt=\"☘️\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t95/2/16/2618.png\" width=\"16\">&nbsp;Tuổi thọ cao, giúp khách hàng luôn luôn yên tâm sử dụng điện</p>\r\n\r\n<p><strong>5. Tư vấn lắp đặt và lựa chọn nhà cung cấp bộ lưu trữ năng lượng ESS</strong></p>\r\n\r\n<p>Elecnova Việt Nam cung cấp giải pháp và thiết bị cho bộ lưu trữ năng lượng cho khách hàng từ giải pháp từ công suất bé cho hộ gia đình đến công suất lớn dành cho công nghiệp. Chúng tôi cung cấp dịch vụ trọn gói từ khảo sát công trình, tư vấn cho khách hàng đến tính toán lập báo cáo khả thi và đầu tư cho dự án.</p>\r\n\r\n<p>Chúng tôi cam kết:</p>\r\n\r\n<p>- Dịch vụ tư vấn lập báo cáo miễn phí</p>\r\n\r\n<p>- Bảo hành các thiết bị và sản phẩm 2 năm (Ắc quy lên đến 10 năm)</p>\r\n<script data-ts=\"1743748598546\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'elecnova-bess-1_20250404065614.png', 'elecnova-bess-1_20250404065614.png', 'resize_elecnova-bess-1_20250404065614.png', 0, '', NULL, 1, 0, 0, 0, '6', 1, 1, '2025-02-11', '2025-04-04', '1743748598', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(7, 3, 13, 0, NULL, 'tu-loc-song-hai-tich-cuc-ahf', 'Tủ lọc sóng hài tích cực AHF', NULL, '', NULL, 220000, 190000, '\r\n<p>Tủ lọc sóng hài tích cực của Elecnova Việt Nam là giải pháp mới giúp cải thiện chất lượng điện của nhà máy, khu công nghiệp. Tủ lọc sóng hài tích cực của Elecnova ứng dụng công nghệ mới nhất,...</p>\r\n<script data-ts=\"1744688013724\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Tủ lọc sóng hài tích cực AHF', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\"><strong>Tủ lọc sóng hài tích cực của Elecnova Việt Nam</strong>&nbsp;là giải pháp mới giúp cải thiện chất lượng điện của nhà máy, khu công nghiệp. Tủ lọc sóng hài tích cực của Elecnova ứng dụng công nghệ mới nhất, sử dụng bộ đo tín hiệu để thu thập tín hiệu sóng hài trên hệ thống qua bộ vi xử lý DSP, sau đó đưa tín hiệu ra bộ nghịch lưu IGBT để phát lại lượng sóng hài có giá trị bằng bộ sóng hài trên hệ thống nhưng ngược pha và triệt tiêu sóng hài trên hệ thống.</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\"><img data-thumb=\"original\" src=\"https://bizweb.dktcdn.net/100/445/560/files/bo-loc-song-hai-chu-dong-3.png?v=1649044393190\"></p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">Nguyên lý bộ lọc sóng hài</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\"><strong>Nhiều chức năng hơn, nhiều chế độ hơn</strong></p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Bù sóng hài, bù công suất phản kháng, cân bằng điện áp - Tích hợp trong 1 tủ lọc sóng hài</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Với chức năng bù phân chia sóng hài, có thể đặt tỷ lệ bù phản kháng</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Màn hình cảm ứng màu HD 7 (10) inch, màn hình có thể hiển thị các thông số hoạt động của hệ thống và thiết bị trong thời gian thực</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\"><strong>Bảo vệ toàn diện để hoạt động ổn định</strong></p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Do thuật toán giới hạn dòng điện tự động được thiết lập cả RMS và giá trị đỉnh, khi dòng điện hài tải lớn hơn đầu ra của thiết bị, dòng đầu ra của thiết bị có thể được giới hạn tự động ở mức 100% mà không có nguy cơ quá tải</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Bảo vệ hoàn toàn với các chức năng bảo vệ quá dòng, quá áp, dưới điện áp, quá nhiệt và các chức năng bảo vệ khác để đảm bảo an toàn và độ tin cậy khi vận hành</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\"><strong>Chiến lược điều khiển nâng cao và thiết kế cấu trúc liên kết</strong></p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Cải tiến công nghệ phát hiện dựa trên lý thuyết công suất phản kháng tức thời, có thể phát hiện dòng sóng hài trong thời gian thực và tự động theo dõi các thay đổi sóng hài tải, với khả năng kiểm soát cao và phản hồi nhanh</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Thuật toán khai thác sóng hài tách biệt theo pha duy nhất có thể đạt được điều khiển độc lập của từng pha khi tải không cân bằng trong ba pha. Khi đủ công suất, có thể chọn chức năng loại bỏ sự mất cân bằng</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Bằng cách lọc cấu trúc liên kết LCL khi dòng điện hài được xuất ra, nhiễu sóng hài chuyển mạch IGBT tần số cao sẽ không được đưa vào và không có cộng hưởng đối với bất kỳ trở kháng nào của hệ thống lưới</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\"><strong>Tích hợp cao, mô-đun, tuần tự hóa</strong></p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Thiết kế mô-đun, kích thước nhỏ, trọng lượng nhẹ, mật độ năng lượng cao, dễ dàng lắp đặt và bảo trì</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Kết hợp các máy song song để đáp ứng các yêu cầu công suất khác nhau, nâng cao độ tin cậy và khả năng bảo trì của thiết bị trong khi vẫn đạt được sản xuất tiêu chuẩn hóa, tạo điều kiện thuận lợi đáng kể cho việc lắp đặt và bảo trì hệ thống</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\">● Thiết kế ống dẫn khí độc lập mô-đun đơn có thể cách ly bụi môi trường hiệu quả và nâng cao hiệu quả tản nhiệt</p>\r\n\r\n<p data-placeholder=\"Bản dịch\" dir=\"ltr\"><img data-thumb=\"original\" original-height=\"500\" original-width=\"500\" src=\"https://bizweb.dktcdn.net/100/445/560/files/loc-song-hai-2.png?v=1682326937299\"></p>\r\n\r\n<h4 dir=\"ltr\"><strong>Thông số kỹ thuật</strong></h4>\r\n\r\n<table>\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<p>Mục</p>\r\n			</td>\r\n			<td>\r\n			<p>Thông số kỹ thuật</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Điện áp định mức</p>\r\n			</td>\r\n			<td>\r\n			<p>400×(1±20%)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Tần số định mức</p>\r\n			</td>\r\n			<td>\r\n			<p>50/60Hz±10%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Phương án đi dây</p>\r\n			</td>\r\n			<td>\r\n			<p>3 pha 4 dây</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Khả năng lọc sóng hài</p>\r\n			</td>\r\n			<td>\r\n			<p>50~600A</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Thời gian đáp ứng</p>\r\n			</td>\r\n			<td>\r\n			<p>≤10ms</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Bảo vệ quá tải</p>\r\n			</td>\r\n			<td>\r\n			<p>Có thể cài đặt</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Tổn hao</p>\r\n			</td>\r\n			<td>\r\n			<p>&lt;3%</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Chế độ làm việc</p>\r\n			</td>\r\n			<td>\r\n			<p>Tự động hoặc bằng tay</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Giao diện truyền thông</p>\r\n			</td>\r\n			<td>\r\n			<p>RS485/Ethernet (Tùy chọn)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Mức bảo vệ</p>\r\n			</td>\r\n			<td>\r\n			<p>IP20</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Giao diện truyền thông</p>\r\n			</td>\r\n			<td>\r\n			<p>7/10 Inch cảm ứng</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Độ cao</p>\r\n			</td>\r\n			<td>\r\n			<p>≤1000m</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Chế độ làm việc song song</p>\r\n			</td>\r\n			<td>\r\n			<p>Có thể</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Chế độ làm mát</p>\r\n			</td>\r\n			<td>\r\n			<p>Làm mát cưỡng bức</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Nhiệt độ môi trường</p>\r\n			</td>\r\n			<td>\r\n			<p>－25℃~45℃</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Nhiệt độ lưu trữ</p>\r\n			</td>\r\n			<td>\r\n			<p>－40℃~70℃</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Độ ẩm làm việc/ Lưu trữ</p>\r\n			</td>\r\n			<td>\r\n			<p>20% ≤ 95%, Không đọng sương</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Kích thước tủ</p>\r\n			</td>\r\n			<td>\r\n			<p>1000×1000×2200 mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Độ ồn</p>\r\n			</td>\r\n			<td>\r\n			<p>&lt;65dB(A)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>Khác</p>\r\n			</td>\r\n			<td>\r\n			<p>Các kích thước có thể để tùy chọn</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><strong>CAM KẾT CỦA ELECNOVA:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Tư vấn về chất lượng điện năng miễn phí</p>\r\n	</li>\r\n	<li>\r\n	<p>Đo và lập báo cáo chất lượng điện năng miễn phí</p>\r\n	</li>\r\n	<li>\r\n	<p>Đa dạng giải pháp với các chi phí phù hợp với các nhà máy</p>\r\n	</li>\r\n	<li>\r\n	<p>Được thử nghiệm sản phẩm trực tiếp</p>\r\n	</li>\r\n	<li>\r\n	<p>Bảo hành trong 2 năm</p>\r\n	</li>\r\n	<li>\r\n	<p>Cam kết đạt theo tiêu chuẩn IEEE519/2014 và tiêu chuẩn 30-2019/BCT-TT của Bộ Công Thương</p>\r\n	</li>\r\n	<li>\r\n	<p>THDi có thể giảm về mức nhỏ hơn &lt;5% (Nhiều trường hợp xuống 2, 3%)</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Một số hình ảnh tham khảo:</strong></p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"1175\" original-width=\"2560\" src=\"https://bizweb.dktcdn.net/100/445/560/products/loc-song-hai-nha-may-cap-ls-vina-c3dfc2b2-37b6-475f-b338-eb3ad226b5f8.jpg?v=1732585824303\"></p>\r\n\r\n<p>Nhà máy LS vina Cable, sóng hài THDi&lt;3.79%</p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"1009\" original-width=\"1681\" src=\"https://bizweb.dktcdn.net/100/445/560/files/vinfast-bo-loc-song-hai-4-be44fbc8-3a42-44b1-b82c-852422fdb2c0.jpg?v=1732586181099\"></p>\r\n\r\n<p>Nhà máy Vinfast, sóng hài THDi&lt;3.18%</p>\r\n\r\n<p><strong>CÁC CÔNG TRÌNH THAM KHẢO CỦA ELECNOVA VIỆT NAM</strong></p>\r\n\r\n<p>- Nhà máy Luxshare ICT Bắc Giang</p>\r\n\r\n<p>- Nhà máy Nichirin Bắc Giang</p>\r\n\r\n<p>- Nhà máy đúc nhôm Sinchi</p>\r\n\r\n<p>- Nhà máy ING Textile (Shireoak)</p>\r\n\r\n<p>- Nhà máy Pinaco Đồng Nai</p>\r\n\r\n<p>- Nhà máy Framas Bình Dương</p>\r\n\r\n<p>và nhiều công trình trên khắp cả nước</p>\r\n<script data-ts=\"1744688013717\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', '16353863349602t72oa_20250404083843.png', '16353863349602t72oa_20250404083843.png', 'resize_16353863349602t72oa_20250404083843.png', 0, '', NULL, 0, 0, 0, 0, '7', 1, 1, '2025-02-11', '2025-04-15', '1744688014', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(8, 3, 14, 0, NULL, 'bo-loc-song-hai-tich-cuc-ahf', 'Bộ lọc sóng hài tích cực AHF', NULL, '', NULL, 220000, 190000, '<p>Bộ lọc sóng hài tích cực SFR-APF của Elecnova là một loại sản phẩm để cải tiến chất lượng điện năng mới để lọc sóng hài chủ động và bù công suất phản kháng. Với bộ lọc sóng hài Elecnova, có thể cam kết đạt sóng hài THDi<5%, đáp ứng các thông tư 30-2019/BCT-TT, tiêu chuẩn IEEE519/2014</p>\r\n<script data-ts=\"1744687997794\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ lọc sóng hài tích cực AHF', '', '', 0, 0, 0, 0, 0, '', NULL, '<p><strong>Bộ lọc sóng hài tích cực SFR-APF </strong>là một loại sản phẩm cải tiến chất lượng điện năng mới cho hiện tượng méo hài trong mạch. Với lợi thế của Biến đổi Fourier nhanh (FFT) và công nghệ nghịch lưu 3 cấp, Bộ lọc sóng hài chủ động SFR-APF có hiệu suất 97% để lọc sóng hài và bù công suất phản kháng theo thời gian thực.</p>\r\n\r\n<p><strong>Bộ lọc sóng hài Elecnova được chia thành 2 dòng chính:</strong></p>\r\n\r\n<p>- Loại gắn tường (Wall-mounted)</p>\r\n\r\n<p>- Loại mô đun</p>\r\n\r\n<p>Loại bộ lọc sóng hài gắn trên tường được sử dụng rộng rãi ở yêu cầu bộ lọc sóng hài độc lập ngay bên cạnh tải. Màn hình LCD 4,3 \"đáp ứng các chức năng cấu hình và hiển thị cho hoạt động của mô-đun. SFR-APF đã tuân thủ tiêu chuẩn IEEE-519 và các chứng chỉ CE, thích ứng với thị trường toàn cầu.</p>\r\n\r\n<p>Loại mô đun được thiết kế đóng theo tủ điện và có khả năng mở rộng công suất lớn. Thường được thiết kế đi kèm với màn hình 7 inch</p>\r\n\r\n<p>Bộ lọc sóng hài tích cực Elecnova  được sử dụng rộng rãi trong ngành điện, luyện kim, dầu khí, cảng, công nghiệp hóa chất và các doanh nghiệp công nghiệp và khai thác mỏ.</p>\r\n\r\n<p><strong>Ưu điểm của bộ lọc sóng hài:</strong></p>\r\n\r\n<ul>\r\n	<li>Khắc phục các sự cố của sóng hài (Nóng cáp, gây tiếng ồn, gây nhiễu, nổ tụ điện)</li>\r\n	<li>Tiết kiệm điện</li>\r\n	<li>Nâng cao chất lượng điện</li>\r\n</ul>\r\n\r\n<p><strong>Cấu tạo và nguyên lý hoạt động:</strong></p>\r\n\r\n<p>Bộ lọc sóng hài – APF của Elecnova thu tín hiệu dòng điện của tải bởi biến dòng, tách sóng hài bằng FFT thông minh (Fast Fourier Transform) bởi DSP sau đó gửi đến IGBT bên trong bằng tín hiệu PWM. APF sẽ tạo ra dòng điện bù có cùng giá trị nhưng ngược pha với sóng hài để đạt được chức năng lọc động thời gian thực</p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"795\" original-width=\"1210\" src=\"https://bizweb.dktcdn.net/100/445/560/files/nguyen-ly-126d297d-e2d5-43de-b678-5785374db007.png?v=1644550761094\"></p>\r\n\r\n<p><strong>Cấu trúc bộ lọc sóng hài tích cực:</strong></p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"435\" original-width=\"1108\" src=\"https://bizweb.dktcdn.net/100/445/560/files/cau-truc.png?v=1644550840381\"></p>\r\n\r\n<p><strong>Các phương pháp lắp đặt lọc sóng hài:</strong></p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"473\" original-width=\"1054\" src=\"https://bizweb.dktcdn.net/100/445/560/files/lap-dat.png?v=1644550803439\"></p>\r\n\r\n<p><strong>CAM KẾT CỦA ELECNOVA:</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Tư vấn về chất lượng điện năng miễn phí</p>\r\n	</li>\r\n	<li>\r\n	<p>Đo và lập báo cáo chất lượng điện năng miễn phí</p>\r\n	</li>\r\n	<li>\r\n	<p>Đa dạng giải pháp với các chi phí phù hợp với các nhà máy</p>\r\n	</li>\r\n	<li>\r\n	<p>Được thử nghiệm sản phẩm trực tiếp</p>\r\n	</li>\r\n	<li>\r\n	<p>Bảo hành trong 2 năm</p>\r\n	</li>\r\n	<li>\r\n	<p>Cam kết đạt theo tiêu chuẩn IEEE519/2014 và tiêu chuẩn 30-2019/BCT-TT của Bộ Công Thương</p>\r\n	</li>\r\n	<li>\r\n	<p>THDi có thể giảm về mức nhỏ hơn <5% (Nhiều trường hợp xuống 2, 3%)</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Một số hình ảnh sau lọc:</strong></p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"1175\" original-width=\"2560\" src=\"https://bizweb.dktcdn.net/100/445/560/files/loc-song-hai-nha-may-cap-ls-vina-62198107-f391-40d0-9b07-032aee6ceb23.jpg?v=1732585968134\"></p>\r\n\r\n<p>Dự án LS Cable Vina, sau lọc giảm về 3.76%</p>\r\n\r\n<p><img data-thumb=\"original\" original-height=\"1009\" original-width=\"1681\" src=\"https://bizweb.dktcdn.net/100/445/560/files/vinfast-bo-loc-song-hai-4-4682bc32-6524-42ba-9b38-359601242e30.jpg?v=1732586004652\"></p>\r\n\r\n<p>Dự án Vinfast: THDi = 3.18%</p>\r\n\r\n<p><strong>CÁC CÔNG TRÌNH THAM KHẢO CỦA ELECNOVA VIỆT NAM</strong></p>\r\n\r\n<p>- Nhà máy Luxshare ICT Bắc Giang</p>\r\n\r\n<p>- Nhà máy Nichirin Bắc Giang</p>\r\n\r\n<p>- Nhà máy đúc nhôm Sinchi</p>\r\n\r\n<p>- Nhà máy ING Textile (Shireoak)</p>\r\n\r\n<p>- Nhà máy Pinaco Đồng Nai</p>\r\n\r\n<p>- Nhà máy Framas Bình Dương</p>\r\n\r\n<p>- Nhà máy BOSCH</p>\r\n\r\n<p>và nhiều công trình trên khắp cả nước</p>\r\n<script data-ts=\"1744687997790\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'iec_20250404084033.png', 'iec_20250404084033.png', 'resize_iec_20250404084033.png', 0, '', NULL, 0, 0, 0, 0, '8', 1, 1, '2025-02-11', '2025-04-15', '1744688017', '', '', '', '', '', '', '', '', '', '', '', NULL, '', '');
INSERT INTO `cycletech_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `ctype`, `ccode`, `cproducts`, `cloai_tin`, `ctag`, `nview`, `fprice`, `fprice_sale`, `cdescription`, `fb_cdescription`, `cgioi_thieu`, `cdia_diem`, `nid_loai_tin`, `nid_loai_bds`, `nid_province`, `nid_district`, `nid_huong`, `cdien_tich`, `eng_cdetail`, `cdetail`, `cimage`, `cproduct_fb`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nhome`, `nnew`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `ctime_update`, `cphong_an`, `cnha_bep`, `csan_thuong`, `ccho_de_xe`, `cchinh_chu`, `cchieu_ngang`, `cchieu_dai`, `cso_lau`, `cso_phong_ngu`, `cphap_ly`, `cduong_truoc_nha`, `nspecial`, `ccode_product`, `ckeyword`) VALUES
(9, 1, 1, 0, NULL, 'cam-bien-buc-xa-silicon-silicon-irradiance-sensor', 'Cảm biến bức xạ silicon (Silicon Irradiance Sensor)', NULL, '', NULL, 220000, 190000, '\r\n<p>Đo cường độ bức xạ trên hệ thống quang điện của bạn một cách chính xác với mức giá phải chăng bằng các cảm biến bức xạ mặt trời silicon mạnh mẽ của IMT Technology (cảm biến Si)</p>\r\n\r\n<p>Thiết kế của phần tử cảm biến tương tự như thiết kế của mô-đun PV; điều này có nghĩa là phản ứng phổ (SR) và bộ điều chỉnh góc tới (IAM) của chúng có thể so sánh được. Do đó, các cảm biến này cực kỳ phù hợp để làm tài liệu tham khảo cho việc giám sát hệ thống PV.</p>\r\n<script data-ts=\"1743750657409\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Cảm biến bức xạ silicon (Silicon Irradiance Sensor)', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Lợi ích &amp; Tính năng</strong></p>\r\n\r\n<ul>\r\n	<li>Pin mặt trời tham chiếu để giám sát PV</li>\r\n	<li>Độ không chắc chắn về phép đo hiệu chuẩn: 1,2% (lớp A theo IEC 61724-1)</li>\r\n	<li>Khả năng sử dụng ngoài trời được xác minh bằng các thử nghiệm theo IEC 61215</li>\r\n	<li>Rất ít lỗi không khớp do các đặc tính quang học như các mô-đun PV</li>\r\n	<li>Hiệu chuẩn liên quan đến quang phổ theo IEC 60904-3, AM1.5</li>\r\n	<li>Độ tuyến tính đặc biệt cao hơn đáng kể so với các yêu cầu của IEC 60904-10</li>\r\n	<li>Pt1000 theo IEC 60751 Lớp A để đo nhiệt độ của pin</li>\r\n	<li>Được phát triển và sản xuất tại Đức</li>\r\n</ul>\r\n\r\n<p><strong>Thông số kỹ thuật chung</strong></p>\r\n\r\n<ul>\r\n	<li>Pin quang điện: Silic đơn tinh thể; 50 mm x 33 mm, nhà cung cấp: BigSun, loại: B156X1D2A-2010</li>\r\n	<li>Vỏ: Nhôm sơn tĩnh điện, 155 mm x 85 mm x 39 mm, 350 đến 470 g</li>\r\n	<li>Cấp độ bảo vệ: IP 67</li>\r\n	<li>Nhiệt độ hoạt động: -35 đến +80°C</li>\r\n	<li>Chiều dài cáp kết nối: 3 m, vỏ bọc PUR, có lớp bảo vệ, chống tia UV và thời tiết, LiYC11Y, 4 x 0,14 mm²</li>\r\n	<li>Nguồn điện: 24 VDC thông thường</li>\r\n</ul>\r\n\r\n<p><strong>Các loại cảm biến</strong></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"width: 200px;\"><strong>Loại Cảm Biến</strong></td>\r\n			<td style=\"width: 300px;\"><strong>Thông số đo được</strong></td>\r\n			<td><strong>Ghi Chú</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td>Si-RS485TC-T-MB</td>\r\n			<td>1. Bức xạ mặt trời<br>\r\n			2. Nhiệt độ tế bào</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Si-RS485TC-2T-MB</td>\r\n			<td>1. Bức xạ mặt trời<br>\r\n			2. Nhiệt độ tế bào<br>\r\n			3. Nhiệt độ môi trường</td>\r\n			<td>- Cảm biến nhiệt độ môi trường được kết nối chắc chắn (cáp kết nối 3 m)<br>\r\n			- Tùy chọn Shield-Tamb-Si để bảo vệ thời tiết và bức xạ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Si-RS485TC-T-Tm-MB</td>\r\n			<td>1. Bức xạ mặt trời<br>\r\n			2. Nhiệt độ cell<br>\r\n			3. Nhiệt độ mô-đun PV</td>\r\n			<td>Cảm biến nhiệt độ mô-đun được kết nối chắc chắn (cáp kết nối 3 m)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Si-RS485TC-2T-v-MB</td>\r\n			<td>1. Bức xạ mặt trời<br>\r\n			2. Nhiệt độ cell<br>\r\n			3. Nhiệt độ (mô-đun PV<br>\r\n			hoặc nhiệt độ môi trường)<br>\r\n			4. Tốc độ gió</td>\r\n			<td>Two waterproof connectors for one temperature sensor and one wind speed sensor To order separately • External sensors with preconfigurated plug • Optional Shield-Tamb-Si as a weather and radiation protection</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Si-RS485TC-3T-MB</td>\r\n			<td>1. Bức xạ mặt trời<br>\r\n			2. Nhiệt độ cell<br>\r\n			3. Nhiệt độ 1 (mô-đun PV<br>\r\n			hoặc nhiệt độ môi trường)<br>\r\n			4. Nhiệt độ 2 (mô-đun PV</td>\r\n			<td>Hai đầu nối chống thấm nước cho hai cảm biến nhiệt độ (ví dụ Tmodul-Si và Tamb-Si)<br>\r\n			Để đặt hàng riêng<br>\r\n			• Cảm biến bên ngoài có phích cắm được cấu hình sẵn<br>\r\n			• Shield-Tamb-Si tùy chọn để bảo vệ khỏi thời tiết và bức xạ</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1743750657405\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'cb1_20250404084408.jpg', 'cb1_20250404084408.jpg', 'resize_cb1_20250404084408.jpg', 0, '', NULL, 0, 1, 0, 0, '9', 1, 1, '2025-02-11', '2025-04-04', '1743750657', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(10, 1, 3, 0, NULL, 'cam-bien-nhiet-do-mo-dun-pv-pv-module-temperature-sensores', 'Cảm biến nhiệt độ mô-đun PV (PV Module Temperature Sensores)', NULL, '', NULL, 220000, 190000, '\r\n<p>Theo dõi chính xác nhiệt độ mô-đun trên hệ thống PV</p>\r\n\r\n<p>Đo nhiệt độ mô-đun PV của bạn với độ chính xác cao nhất và độ trôi tối thiểu để đánh giá năng suất của hệ thống. Cảm biến nhiệt độ mô-đun của chúng tôi được trang bị vỏ nhôm chắc chắn và cáp chống chịu thời tiết mạnh mẽ. Nhờ sử dụng các thành phần cao cấp, các cảm biến đạt được độ chính xác cao và lý tưởng để sử dụng trong môi trường công nghiệp và sử dụng tại chỗ (ví dụ: nhiệt độ mô-đun PV). Thiết kế nhỏ gọn của thành phần cảm biến cũng làm cho nó hoàn hảo để đo nhiệt độ của các mô-đun hai mặt.</p>\r\n<script data-ts=\"1743750593780\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Cảm biến nhiệt độ mô-đun PV (PV Module Temperature Sensores)', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Lợi ích &amp; Tính năng</strong></p>\r\n\r\n<ul>\r\n	<li>Cảm biến tuân thủ tất cả các yêu cầu của IEC 61724-1, bao gồm cả đối với các mô-đun hai mặt.</li>\r\n	<li>Phần tử cảm biến rất nhỏ; bao phủ ít hơn 2% trong các ô M6 kích thước đầy đủ hoặc ô M12 cắt một nửa.</li>\r\n	<li>Độ dẫn nhiệt của chất kết dính &gt; 500/m²/K.</li>\r\n	<li>Phần tử cảm biến chính xác Pt1000 theo IEC 60751 Loại A1.</li>\r\n	<li>Phần tử cảm biến, bao gồm băng dính cực kỳ chắc chắn để sử dụng lâu dài.</li>\r\n	<li>Vỏ nhôm cực kỳ chắc chắn</li>\r\n	<li>Thiết bị điện tử đo lường có độ chính xác cao bao gồm chứng chỉ hiệu chuẩn cho tất cả các mẫu đang hoạt động.</li>\r\n	<li>Được phát triển và sản xuất tại Đức</li>\r\n</ul>\r\n\r\n<p><strong>Thông số kỹ thuật chung</strong></p>\r\n\r\n<ul>\r\n	<li>Tất cả các loại (trừ Tm-Pt100)</li>\r\n	<li>Linh kiện cảm biến: Pt1000 loại A theo EN 60751</li>\r\n	<li>Vỏ cảm biến: Khối nhôm tự dính, 35 mm x 12 mm x 6 mm</li>\r\n	<li>Cáp cảm biến (Pt1000): Vỏ bọc PUR, có lớp bảo vệ (LiYC11Y, 2 x 0,25 mm²), chiều dài: 3 m</li>\r\n	<li>Vật liệu vỏ: Nhôm sơn tĩnh điện</li>\r\n	<li>Nhiệt độ hoạt động Linh kiện cảm biến: -40 đến +90°C, vỏ: -40 đến +80°C</li>\r\n	<li>Cấp độ bảo vệ: IP67</li>\r\n</ul>\r\n\r\n<p><strong>Các loại cảm biến</strong></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"width: 200px;\">Tm-RS485-MB</td>\r\n			<td>Tín hiệu đầu ra RS485<br>\r\n			Phạm vi đo -40 đến +90°C<br>\r\n			Độ không chắc chắn (-40 đến +80°C) 1 K<br>\r\n			Điện áp cung cấp 24 VDC (10 đến 28 VDC)<br>\r\n			Dòng điện tiêu thụ Điển hình 25 mA ở 24 VDC<br>\r\n			Cách điện galvanic 1000 VDC giữa nguồn điện áp và RS485<br>\r\n			Phần tử cảm biến Pt1000 loại A theo EN 60751<br>\r\n			Vỏ phần tử cảm biến Khối nhôm tự dính, 35 mm x 12 mm x 6 mm<br>\r\n			Cáp cảm biến (Pt1000) Chiều dài: 3 m, phủ PUR, có lớp bảo vệ (LiYC11Y, 2 x 0,25 mm²)<br>\r\n			Vật liệu vỏ Nhôm sơn tĩnh điện<br>\r\n			Kích thước vỏ / mức độ bảo vệ 98 mm x 64 mm x 34 mm / IP 67<br>\r\n			Trọng lượng 500 g<br>\r\n			Nhiệt độ hoạt động Phần tử cảm biến -40 đến +90°C (xem hướng dẫn lắp đặt bên dưới)<br>\r\n			Vỏ -40 đến + 80°C<br>\r\n			Kết nối điện Chiều dài: 3 m, phủ PUR, được che chắn<br>\r\n			LiYC11Y, 4 x 0,14 mm²<br>\r\n			&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Aptos,sans-serif\"><span lang=\"EN-US\" new=\"\" roman=\"\" style=\"font-family:\" times=\"\">Tm-I-4090/Tm-V-4090</span></span></span></span></p>\r\n			</td>\r\n			<td>Tín hiệu đầu ra 4-20mA/0-10V<br>\r\n			Điện áp cung cấp 12 đến 28 VDC<br>\r\n			Phần tử cảm biến Pt1000 loại A theo EN 60751<br>\r\n			Vỏ phần tử cảm biến Khối nhôm tự dính, 35 mm x 12 mm x 6 mm<br>\r\n			Cáp cảm biến (Pt1000) Chiều dài: 3 m, phủ PUR, có lớp bảo vệ (LiYC11Y, 2 x 0,25 mm²)<br>\r\n			Vật liệu vỏ Nhôm sơn tĩnh điện<br>\r\n			Kích thước vỏ / mức độ bảo vệ 64 mm x 58 mm x 34 mm / IP 67<br>\r\n			Trọng lượng 350 g<br>\r\n			Nhiệt độ hoạt động Phần tử cảm biến -40 đến +90°C (xem hướng dẫn lắp đặt)<br>\r\n			Vỏ -40 đến + 80°C<br>\r\n			Chiều dài cáp kết nối: 3 m, phủ PUR, có lớp bảo vệ (LiYC11Y, 4 x 0,14 mm²)</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1743750593777\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'cb2_20250404090939.jpg', 'cb2_20250404090939.jpg', 'resize_cb2_20250404090939.jpg', 0, '', NULL, 0, 0, 0, 0, '10', 1, 1, '2025-02-11', '2025-04-04', '1743750593', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(11, 1, 4, 0, NULL, 'cam-bien-nhiet-do-moi-truong-ambient-temperature-sensors', 'Cảm biến nhiệt độ môi trường (Ambient Temperature Sensors)', NULL, '', NULL, 220000, 190000, '\r\n<p>Theo dõi chính xác nhiệt độ không khí trong quang điện và hơn thế nữa. Đảm bảo đo chính xác nhiệt độ bên ngoài trên hệ thống PV của bạn nhờ theo dõi nhiệt độ môi trường liên tục. Cảm biến nhiệt độ môi trường của chúng tôi được trang bị vỏ nhôm chắc chắn và cáp chống chịu thời tiết mạnh mẽ. Nhờ sử dụng các thành phần cao cấp, cảm biến đạt được độ chính xác cao và lý tưởng để sử dụng trong môi trường công nghiệp và sử dụng tại chỗ (ví dụ: hệ thống PV hoặc phòng thiết bị giám sát).</p>\r\n<script data-ts=\"1743750906825\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Cảm biến nhiệt độ môi trường (Ambient Temperature Sensors)', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Lợi ích &amp; Tính năng</strong></p>\r\n\r\n<ul>\r\n	<li>Cảm biến có khả năng chống chịu thời tiết và bức xạ đáp ứng mọi yêu cầu của IEC 61724-1</li>\r\n	<li>Phần tử cảm biến chính xác Pt1000 / Pt100 theo IEC 60751 Loại A</li>\r\n	<li>Vỏ nhôm cực kỳ chắc chắn</li>\r\n	<li>Thiết bị điện tử đo lường có độ chính xác cao bao gồm chứng chỉ hiệu chuẩn cho tất cả các mẫu đang hoạt động</li>\r\n	<li>Được phát triển và sản xuất tại Đức</li>\r\n</ul>\r\n\r\n<p><strong>Thông số kỹ thuật chung</strong></p>\r\n\r\n<ul>\r\n	<li>Vật liệu vỏ Nhôm sơn tĩnh điện</li>\r\n	<li>Nhiệt độ hoạt động Phần tử cảm biến: -40 đến +90°C, vỏ: -40 đến +80°C</li>\r\n	<li>Mức độ bảo vệ IP67</li>\r\n</ul>\r\n\r\n<p><strong>Các loại cảm biến</strong></p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td>Ta-ext-RS485-MB</td>\r\n			<td>Tín hiệu đầu ra RS485<br>\r\n			Phạm vi đo -40 đến +90°C<br>\r\n			Độ không chắc chắn (-40 đến +80°C) 1 K<br>\r\n			Điện áp cung cấp 24 VDC (10 đến 28 VDC)<br>\r\n			Dòng điện tiêu thụ Điển hình 25 mA ở 24 VDC<br>\r\n			Cách điện galvanic 1000 VDC giữa nguồn điện áp và RS485<br>\r\n			Phần tử cảm biến Pt1000 loại AA theo EN 60751<br>\r\n			Vỏ phần tử cảm biến Ống thép INOX, đường kính 6 mm, dài 50 mm<br>\r\n			Cáp cảm biến (Pt1000) Chiều dài: 3 m, phủ PUR, có vỏ bọc (LiYC11Y, 2 x 0,25 mm²)<br>\r\n			Vật liệu vỏ Nhôm sơn tĩnh điện<br>\r\n			Kích thước vỏ / mức độ bảo vệ 98 mm x 64 mm x 34 mm / IP 67<br>\r\n			Trọng lượng 500 g<br>\r\n			Nhiệt độ hoạt động Phần tử cảm biến: -40 đến +90°C / Vỏ: -40 đến +80°C<br>\r\n			Chiều dài cáp kết nối: 3 m, phủ PUR, có lớp bảo vệ (LiYC11Y, 4 x 0,14 mm²)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Ta-I-4090/ Ta-V-4090</td>\r\n			<td>Tín hiệu đầu ra 0 đến 10V / 4-20mA ở -40 đến +90°C<br>\r\n			Điện áp cung cấp 12 đến 28 VDC<br>\r\n			Phần tử cảm biến Pt1000 loại A theo EN 60751<br>\r\n			Vỏ phần tử cảm biến Ống thép INOX, đường kính 6 mm, dài 23 mm<br>\r\n			Vật liệu vỏ Nhôm sơn tĩnh điện<br>\r\n			Kích thước vỏ / mức độ bảo vệ 64 mm x 58 mm x 34 mm / IP 67<br>\r\n			Trọng lượng 260 g<br>\r\n			Nhiệt độ hoạt động Phần tử cảm biến -40 đến +90°C (xem hướng dẫn lắp đặt)<br>\r\n			Vỏ -40 đến + 80°C<br>\r\n			Chiều dài cáp kết nối: 3 m, phủ PUR, có vỏ bọc (LiYC11Y, 4 x 0,14 mm²)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Ta-ext-I-4090 / Ta-ext-V-4090</td>\r\n			<td>Tín hiệu đầu ra 0 đến 10 V / 4-20mA ở -40 đến +90°C<br>\r\n			Điện áp cung cấp 12 đến 28 VDC<br>\r\n			Phần tử cảm biến Pt1000 loại AA theo EN 60751<br>\r\n			Vỏ phần tử cảm biến Ống thép INOX, đường kính 6 mm, dài 50 mm<br>\r\n			Cáp cảm biến (Pt1000) Chiều dài: 3 m, phủ PUR, có vỏ bọc (LiYC11Y, 2 x 0,25 mm²)<br>\r\n			Vật liệu vỏ Nhôm sơn tĩnh điện<br>\r\n			Kích thước vỏ / mức độ bảo vệ 64 mm x 58 mm x 34 mm / IP 67<br>\r\n			Trọng lượng 370 g<br>\r\n			Nhiệt độ hoạt động Phần tử cảm biến -40 đến +90°C (xem hướng dẫn lắp đặt)<br>\r\n			Vỏ -40 đến + 80°C<br>\r\n			Chiều dài cáp kết nối: 3 m, phủ PUR, có vỏ bọc (LiYC11Y, 4 x 0,14 mm²)</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1743750906821\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'cb3_20250404091506.jpg', 'cb3_20250404091506.jpg', 'resize_cb3_20250404091506.jpg', 0, '', NULL, 0, 0, 0, 0, '11', 1, 1, '2025-02-11', '2025-04-04', '1743750906', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(12, 1, 1, 0, NULL, 'cam-bien-do-buc-xa-mat-troi-pyranometer', 'Cảm Biến Đo Bức Xạ Mặt Trời Pyranometer', NULL, '', NULL, 220000, 190000, '\r\n<p>Có được góc nhìn toàn cảnh về bức xạ khí tượng với máy đo bức xạ mặt trời cao cấp.</p>\r\n\r\n<p>Các máy đo bức xạ mặt trời này được phát triển để sử dụng trong mọi điều kiện thời tiết, từ khí hậu Bắc Cực đến điều kiện sa mạc. Chúng được sử dụng trên toàn thế giới cho nhiều mục đích, trong khí tượng học, thủy văn, nghiên cứu khí hậu, ghi lại bức xạ mặt trời, thử nghiệm vật liệu, giám sát nhà kính và tự động hóa tòa nhà, chỉ kể đến một vài ứng dụng.</p>\r\n\r\n<p>Trong quang điện, máy đo bức xạ mặt trời chủ yếu được sử dụng trong nghiên cứu và phát triển.</p>\r\n<script data-ts=\"1744347837166\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Cảm Biến Đo Bức Xạ Mặt Trời Pyranometer', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>Lợi ích &amp; Tính năng</strong></p>\r\n\r\n<ul>\r\n	<li>Phẳng về mặt quang phổ, từ loại C đến vượt quá yêu cầu của loại A theo tiêu chuẩn ISO 9060</li>\r\n	<li>Được lắp đặt trên toàn thế giới bởi các mạng lưới khí tượng và khí hậu quốc gia</li>\r\n	<li>Được sử dụng trong giám sát PV</li>\r\n	<li>Đầu ra tương tự hoặc MODBUS theo tiêu chuẩn công nghiệp</li>\r\n	<li>Thời gian trung bình giữa các lần hỏng hóc (MTBF) vượt quá 10 năm</li>\r\n	<li>Bảo hành của nhà sản xuất trên toàn thế giới trong 5 năm</li>\r\n</ul>\r\n\r\n<p><strong>Thông số kỹ thuật chung</strong></p>\r\n\r\n<ul>\r\n	<li>Tín hiệu đầu ra kỹ thuật số RS485 / MODBUS</li>\r\n	<li>Tín hiệu đầu ra tương tự 1 V (phiên bản -V) hoặc 4 đến 20 mA (phiên bản -A)</li>\r\n	<li>Loại cảm biến Phần tử cảm biến nhiệt độ</li>\r\n	<li>Nhiệt độ hoạt động -40 đến +70°C</li>\r\n	<li>Mức độ bảo vệ IP67</li>\r\n</ul>\r\n\r\n<p><strong>Các loại cảm biến</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td>SMP3-A / SMP3-V</td>\r\n			<td>Phân loại theo ISO 9060 Quang phổ phẳng Lớp C<br>\r\n			Tín hiệu đầu ra kỹ thuật số RS485 / MODBUS<br>\r\n			Tín hiệu đầu ra tương tự 1 V (phiên bản -V) hoặc 4 đến 20 mA (phiên bản -A)<br>\r\n			Loại cảm biến Phần tử cảm biến nhiệt độ<br>\r\n			Nhiệt độ hoạt động -40 đến +70°C<br>\r\n			Mức độ bảo vệ IP67</td>\r\n		</tr>\r\n		<tr>\r\n			<td>SMP6-A / SMP6-V</td>\r\n			<td>Phân loại theo ISO 9060 Quang phổ phẳng Lớp B<br>\r\n			Tín hiệu đầu ra kỹ thuật số RS485 / MODBUS<br>\r\n			Tín hiệu đầu ra tương tự 1 V (phiên bản -V) hoặc 4 đến 20 mA (phiên bản -A)<br>\r\n			Loại cảm biến Phần tử cảm biến nhiệt độ<br>\r\n			Nhiệt độ hoạt động -40 đến +70°C<br>\r\n			Mức độ bảo vệ IP67</td>\r\n		</tr>\r\n		<tr>\r\n			<td>SMP10-A / SMP10-V</td>\r\n			<td>Phân loại theo ISO 9060 Quang phổ phẳng Lớp A<br>\r\n			Tín hiệu đầu ra kỹ thuật số RS485 / MODBUS<br>\r\n			Tín hiệu đầu ra tương tự 1 V (phiên bản -V) hoặc 4 đến 20 mA (phiên bản -A)<br>\r\n			Loại cảm biến Phần tử cảm biến nhiệt độ<br>\r\n			Nhiệt độ hoạt động -40 đến +70°C<br>\r\n			Mức độ bảo vệ IP67</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Aptos,sans-serif\"><span lang=\"EN-US\" new=\"\" roman=\"\" style=\"font-family:\" times=\"\">RT1</span></span></span></span></p>\r\n			</td>\r\n			<td>Dải đo bức xạ 0 – 2000 W/m2<br>\r\n			Độ chính xác/độ phân giải 1 W/m2<br>\r\n			Dải quang phổ 400 – 1100 nm<br>\r\n			Dải đo nhiệt độ tấm pin -20 đến 100 oC, ±1 oC<br>\r\n			Tín hiệu kết nối, RS485 Modbus to host &amp; Cảm biến nhiệt độ tấm pin<br>\r\n			Dải điện áp 5 tới 30 Vdc<br>\r\n			Nhiệt độ môi trường xung quanh – 400C tới 800C</td>\r\n		</tr>\r\n		<tr>\r\n			<td>SR20-D2</td>\r\n			<td>Phân loại ISO 9060:2018: Pyranometer loại A phổ phẳng.<br>\r\n			Phân loại ISO 9060:1990: tiêu chuẩn thứ cấp.<br>\r\n			Tuân thủ IEC 61724-1:2021, giám sát PV loại A.<br>\r\n			Đầu ra: 4-20mA, Modbus RS-485.<br>\r\n			Độ chính xác hiệu chuẩn: &lt;1.2% (k = 2).<br>\r\n			Phạm vi bước sóng: 285 đến 3000 x 10⁻⁹ m.<br>\r\n			Nhiệt độ hoạt động: -40 đến +80 °C.<br>\r\n			Chiều dài cáp chuẩn: 5 m.<br>\r\n			Điện áp hoạt động định mức: 5-30VDC.<br>\r\n			Giao thức truyền thông: Modbus.<br>\r\n			Giao diện phần cứng: 2 dây (half duplex) RS 485.<br>\r\n			Đầu ra số: Bức xạ trong W/m² và nhiệt độ °C.<br>\r\n			Đầu ra tương tự: 4-20mA<br>\r\n			Phạm vi truyền tải: 0-1600 W/m².<br>\r\n			Tiêu chuẩn ISO 9060:2008: Quang phổ phẳng loại A.<br>\r\n			Dãi quang phổ đo: 285 đến 3000 x 10⁻⁹ m.<br>\r\n			Nhiệt độ hoạt động: -40 đến +80 °C.<br>\r\n			Điện áp định mức: 5-30VDC<br>\r\n			Chiều dài cáp kết nối: 5m<br>\r\n			Tùy chọn ngõ ra: Modbus RTU hoặc Analog (4-20mA)<br>\r\n			Phạm vi truyền tải: 0-1600 W/m².</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1744347837162\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'cb4_20250404091944.jpg', 'cb4_20250404091944.jpg', 'resize_cb4_20250404091944.jpg', 0, '', NULL, 0, 0, 0, 0, '12', 1, 1, '2025-02-11', '2025-04-11', '1744347836', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(13, 5, 20, 0, NULL, 'phu-kien-cho-bo-lam-mat-cooling-units', 'Phụ kiện cho bộ làm mát cooling units', NULL, '', NULL, 220000, 190000, '\r\n<p>Bao gồm các phụ kiện sau: Công nghệ lọc, Đường dẫn khí, Phân phối nước, Kiểm soát/điều chỉnh, Phụ kiện lắp đặt</p>\r\n<script data-ts=\"1744798482337\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Phụ kiện cho bộ làm mát cooling units', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p><strong>For details, please see the catalog below.</strong></p>\r\n\r\n<p><a href=\"http://issvn.com.vn/upload/catalogue/Ph%E1%BB%A5%20ki%E1%BB%87n%20cho%20m%C3%A1y%20l%E1%BA%A1nh_0824831013.pdf\"><em>Accessories for climate control</em></a></p>\r\n<script data-ts=\"1744798482336\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p5_1_20250409014542.jpg', 'p5_1_20250409014542.jpg', 'resize_p5_1_20250409014542.jpg', 0, '', NULL, 1, 0, 0, 0, '13', 1, 1, '2025-02-11', '2025-04-16', '1744798482', '', '', '', '', '', '', '', '', '', '', '', NULL, '', ''),
(14, 5, 19, 0, NULL, 'quat-gan-phin-loc-dong-top-therm-3237-100', 'Quạt gắn phin lọc dòng Top Therm 3237.100', NULL, '', NULL, 220000, 190000, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744798494013\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Quạt gắn phin lọc dòng Top Therm 3237.100', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<table border=\"2\" cellpadding=\"0\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Số bài viết:</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>SK 3237.100</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Màu sắc</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>RAL 7035</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Cái quạt</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Động cơ cực hướng trục, bóng mờ</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Cung cấp bao gồm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Thiết bị hoàn chỉnh đã sẵn sàng để lắp đặt, bao gồm cả tấm lọc sợi cắt nhỏ</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Lưu lượng không khí, luồng không khí không bị cản trở (với bộ lọc sợi cắt nhỏ )</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở 50 Hz: 20 m³/h<br>\r\n			Ở 60 Hz: 25 m³/h</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Lưu lượng không khí với bộ lọc đầu ra bao gồm thảm lọc sợi cắt nhỏ (số lượng x số đơn hàng)</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>1 x 3237200: 15/18 m³/h</p>\r\n\r\n			<p>2 x 3237200: 16/20 m³/h</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Điện áp hoạt động định mức</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>230V, 1~, 50Hz/60Hz</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Điện năng tiêu thụ Pel</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở tần số 50 Hz: 12 W<br>\r\n			Ở 60 Hz: 10 W</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Dòng tiêu thụ</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>At 50 Hz:&nbsp;0.065 A<br>\r\n			At 60 Hz:&nbsp;0.07 A</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Kích thước</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Chiều rộng: 116,5 mm<br>\r\n			Chiều cao: 116,5 mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Mặt cắt lắp đặt</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Chiều rộng cắt: 92 mm<br>\r\n			Chiều cao cắt: 92 mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Độ sâu cài đặt</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>43mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Loại bảo vệ theo tiêu chuẩn IEC 60 529</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>IP54 với bộ lọc sợi cắt nhỏ</p>\r\n\r\n			<p>IP56 với bộ lọc sợi cắt nhỏ và nắp chống ống</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Hạng mục bảo vệ NEMA</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Loại 12 có lọc sợi cắt nhỏ</p>\r\n\r\n			<p>Loại 3, 3R có bộ lọc sợi nhỏ và nắp chống ống mềm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Ghi chú</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Để tăng thông lượng không khí, có thể tùy ý sử dụng bộ lọc xếp nếp (xem đường cong đặc tính). Thích hợp để sử dụng với các bộ phận quạt và bộ lọc, quạt gắn trên mái nhà và bộ lọc đầu ra.</p>\r\n\r\n			<p>Với bộ quạt và bộ lọc 3237.XXX, kết nối điện được thực hiện thông qua hai dây đơn (chiều dài khoảng 300 mm) trên thiết bị, đối với tất cả các bộ quạt và bộ lọc khác, sử dụng đầu nối lò xo không vít</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Tuổi thọ của quạt (L10, 40 °C)</strong></p>\r\n\r\n			<p><strong>&nbsp;</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở 50 Hz: 55.000 giờ<br>\r\n			Ở 60 Hz: 60.000 giờ</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Mức độ ồn</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở 50 Hz: 38 dB(A)<br>\r\n			Ở 60 Hz: 43 dB(A)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Gói của</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>1 cái.</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Trọng lượng/gói</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>0,46 kg</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>EAN</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>4028177637580</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>ETIM 7.0</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>EC000855</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>ECLASS</strong><strong>&nbsp;8.0</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>27180716</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Mô tả Sản phẩm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Bộ quạt và bộ lọc SK TopTherm , 20/25 m³/h, 230 V, 1~, 50/60 Hz, WHD: 116,5 x 116,5 x 16 mm</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1744798494005\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p5_2_20250409014751.jpg', 'p5_2_20250409014751.jpg', 'resize_p5_2_20250409014751.jpg', 0, '', NULL, 1, 0, 0, 0, '14', 1, 1, '2025-02-11', '2025-04-16', '1744798494', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(15, 5, 19, 0, NULL, 'quat-gan-phin-loc-dong-top-therm-3239-600', 'Quạt gắn phin lọc dòng Top Therm 3239.600', NULL, '', NULL, 220000, 190000, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744798507575\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Quạt gắn phin lọc dòng Top Therm 3239.600', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<table border=\"2\" cellpadding=\"0\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Số bài viết:</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>SK 3239.600</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Màu sắc</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>RAL 7035</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Cái quạt</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Động cơ cực hướng trục, bóng mờ</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Cung cấp bao gồm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Thiết bị hoàn chỉnh đã sẵn sàng để lắp đặt, bao gồm cả tấm lọc sợi cắt nhỏ</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Thông lượng không khí (luồng không khí không bị cản trở)</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở 50 Hz: 100 m³/h<br>\r\n			Ở 60 Hz: 115 m³/h</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Lưu lượng không khí với bộ lọc đầu ra bao gồm thảm lọc sợi cắt nhỏ (số lượng x số đơn hàng)</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>1 x 3237200: 74/87 m³/h</p>\r\n\r\n			<p>2 x 3237200: 84/98 m³/h</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Điện áp hoạt động định mức</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>230V, 1~, 50Hz/60Hz</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Điện năng tiêu thụ Pel</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở tần số 50 Hz: 15 W<br>\r\n			Ở 60 Hz: 14 W</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Đánh giá tối đa hiện tại.</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở 50 Hz: 0,12 A<br>\r\n			Ở 60 Hz: 0,09 A</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Kích thước</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Chiều rộng: 204 mm<br>\r\n			Chiều cao: 204 mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Mặt cắt lắp đặt</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Chiều rộng cắt ra: 177 mm<br>\r\n			Chiều cao cắt ra: 177 mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Phiên bản EMC</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Đúng</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Loại bảo vệ theo tiêu chuẩn IEC 60 529</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>IP54 với bộ lọc sợi cắt nhỏ</p>\r\n\r\n			<p>IP56 với bộ lọc sợi cắt nhỏ và nắp chống ống</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Hạng mục bảo vệ NEMA</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Loại 12 có lọc sợi cắt nhỏ</p>\r\n\r\n			<p>Loại 3, 3R có bộ lọc sợi nhỏ và nắp chống ống mềm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Ghi chú</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Để cải thiện hiệu quả sử dụng năng lượng và kéo dài tuổi thọ của