(18, 5, 19, 0, NULL, 'quat-gan-phin-loc-dong-top-therm-3243-600', 'Quạt gắn phin lọc dòng Top Therm 3243.600', NULL, '', NULL, 220000, 190000, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744798532245\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Quạt gắn phin lọc dòng Top Therm 3243.600', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<table border=\"2\" cellpadding=\"0\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Số bài viết:</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>SK 3243.100</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Màu sắc</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>RAL 7035</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Cái quạt</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Động cơ chéo, 1 ~ tụ điện</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Cung cấp bao gồm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Thiết bị hoàn chỉnh đã sẵn sàng để lắp đặt, bao gồm cả tấm lọc sợi cắt nhỏ</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Lưu lượng không khí, luồng không khí không bị cản trở (với bộ lọc sợi cắt nhỏ )</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở 50 Hz: 540 m³/h<br>\r\n			Ở 60 Hz: 590 m³/h</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Lưu lượng không khí với bộ lọc đầu ra bao gồm thảm lọc sợi cắt nhỏ (số lượng x số đơn hàng)</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>1 x 3243200: 405/460 m³/h</p>\r\n\r\n			<p>2 x 3243200: 475/520 m³/h</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Điện áp hoạt động định mức</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>230V, 1~, 50Hz/60Hz</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Điện năng tiêu thụ Pel</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Với DC: 70 W</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Đánh giá tối đa hiện tại.</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở 50 Hz: 0,37 A<br>\r\n			Ở 60 Hz: 0,39 A</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Kích thước</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Chiều rộng: 323 mm<br>\r\n			Chiều cao: 323 mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Mặt cắt lắp đặt</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Chiều rộng cắt ra: 292 mm<br>\r\n			Chiều cao cắt ra: 292 mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Loại bảo vệ theo tiêu chuẩn IEC 60 529</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>IP54 với bộ lọc sợi cắt nhỏ /bộ lọc xếp nếp</p>\r\n\r\n			<p>IP56 với bộ lọc sợi cắt nhỏ /bộ lọc xếp nếp và nắp chống ống mềm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Hạng mục bảo vệ NEMA</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Loại 12 có lọc sợi cắt nhỏ</p>\r\n\r\n			<p>Loại 3, 3R, 4, 4X có bộ lọc sợi nhỏ và nắp chống ống</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Ghi chú</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Để cải thiện hiệu quả sử dụng năng lượng và kéo dài tuổi thọ của thiết bị, chúng tôi khuyên bạn nên sử dụng bộ điều chỉnh nhiệt độ hoặc màn hình hiển thị nhiệt độ</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Tuổi thọ của quạt (L10, 40 °C)</strong></p>\r\n\r\n			<p><strong>&nbsp;</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở 50 Hz: 65.000 h<br>\r\n			Tại 60 Hz: 61.000 h</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Mức độ ồn</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Ở tần số 50 Hz: 59 dB(A)<br>\r\n			Tại 60 Hz: 61 dB(A)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Gói của</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>1 cái.</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Trọng lượng/gói</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>3,56 kg</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>EAN</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>4028177652477</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>ETIM 7.0</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>EC000320</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>ECLASS&nbsp;</strong><strong>&nbsp;8.0</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>27180716</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"276\">\r\n			<p><strong>Mô tả Sản phẩm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"348\">\r\n			<p>Bộ quạt và bộ lọc SK TopTherm , 540/590 m³/h, 230 V, 1~, 50/60 Hz, WHD: 323 x 323 x 25 mm</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1744798532237\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p5_6_20250409015654.jpg', 'p5_6_20250409015654.jpg', 'resize_p5_6_20250409015654.jpg', 0, '', NULL, 1, 0, 0, 0, '18', 1, 1, '2025-02-11', '2025-04-16', '1744798533', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(19, 5, 20, 0, NULL, 'thiet-bi-suoi-rittal-3105-310', 'Thiệt bị sưởi Rittal 3105.310', NULL, '', NULL, 220000, 190000, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744798544714\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Thiệt bị sưởi Rittal 3105.310', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<table border=\"2\" cellpadding=\"0\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Số bài viết</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>SK 3105.310</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Mô tả Sản phẩm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>Máy sưởi bao vây để điều chỉnh độ ẩm tương đối, ngăn nhiệt độ giảm xuống dưới điểm sương và ngăn chặn sự ngưng tụ hình thành bên trong bao vây.</p>\r\n\r\n			<p>Điều này ngăn ngừa hậu quả thiệt hại liên quan đến ăn mòn hoặc đoản mạch điện</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Vật liệu</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>Nhôm , anodized</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Cung cấp bao gồm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>Bộ gia nhiệt PTC Thiết bị đầu cuối kết nối nhanh Các bộ phận lắp ráp</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Ghi chú</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>Nên sử dụng bộ điều nhiệt để kiểm soát nhiệt độ chính xác bên trong vỏ bọc</p>\r\n\r\n			<p>Để ngăn ngừa sự ngưng tụ trên các cụm lắp ráp, nên sử dụng bộ điều chỉnh độ ẩm để điều chỉnh nhiệt độ.</p>\r\n\r\n			<p>Trong các thùng chứa lớn hơn, khả năng phân bổ nhiệt đều đạt được tốt nhất bằng cách lắp đặt một số bộ sưởi có công suất thấp</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Lưu ý về mẫu số</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>Hỗ trợ nhiệt độ hoạt động -44 ° C. Tuyên bố của nhà sản xuất có sẵn theo yêu cầu</p>\r\n\r\n			<p>Điện áp đặc biệt có sẵn theo yêu cầu. Chúng tôi có quyền thực hiện các sửa đổi kỹ thuật</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Sản lượng nhiệt liên tục ở 10 ° C</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>8 W - 10 W</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Điện áp hoạt động định mức</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>110V - 240V, 1~, 50Hz/60Hz</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Kích thước</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>Chiều rộng: 45mm</p>\r\n\r\n			<p>Chiều cao: 120mm</p>\r\n\r\n			<p>Độ sâu: 46mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Cầu chì trước</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>Cầu dao/cầu chì thu nhỏ: 2 A</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Hạng mục bảo vệ IP theo tiêu chuẩn IEC 60 529</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>IP 20</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Lớp bảo vệ</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>II (cách nhiệt hoàn toàn)</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Nhiệt độ hoạt động</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>-33°C...65°C</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Gói của</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>1 chiếc</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Trọng lượng/gói</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>0,212 kg</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Mã số thuế hải quan</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>85162999</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>EAN</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>4028177638617</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>ETIM 7.0</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>EC000737</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>ECLASS</strong><strong>&nbsp;8.0</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>27180710</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"246\">\r\n			<p><strong>Mô tả Sản phẩm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"378\">\r\n			<p>Máy sưởi vỏ SK, không quạt, 8-10 W, 110-240 V, 1~, 50/60 Hz, WHD: 45 x 120 x 46 mm</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1744798544708\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p5_7_20250409015810.jpg', 'p5_7_20250409015810.jpg', 'resize_p5_7_20250409015810.jpg', 0, '', NULL, 1, 0, 0, 0, '19', 1, 1, '2025-02-11', '2025-04-16', '1744798546', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(20, 5, 20, 0, NULL, 'fine-filters-3183-100', 'FINE FILTERS 3183.100', NULL, '', NULL, 220000, 190000, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744798465156\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'FINE FILTERS 3183.100', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<table border=\"2\" cellpadding=\"0\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Số bài viết</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>SK 3183.100</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Mô tả Sản phẩm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>Được làm bằng thảm sợi cắt nhỏ với cấu trúc tiến bộ. Chịu nhiệt độ tới 100 °C, loại tự dập tắt F1 đến DIN 53 438. Phía không khí chứa đầy bụi: Cấu trúc mở. Phía không khí sạch: Cấu trúc khép kín. Lọc đáng tin cậy hầu như tất cả các loại bụi có kích thước hạt lên tới 1 µm.</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Vật liệu</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>Sợi hóa học</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Ghi chú</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>Dữ liệu hiệu suất, danh mục bảo vệ và phê duyệt thiết bị chỉ được đảm bảo khi sử dụng cùng với thảm lọc Rittal chính hãng.</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Để phù hợp với Model No.</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>3243....</p>\r\n\r\n			<p>3244....</p>\r\n\r\n			<p>3245....</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Kích thước</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>Chiều rộng: 289 mm<br>\r\n			Chiều cao: 289 mm<br>\r\n			Chiều sâu: 12 mm</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Lớp lọc</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>theo DIN EN 779: F5/M5 đến DIN EN ISO 16890: ISO Thô 75% ISO ePM10 50 %</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Trọng lượng/gói</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>0,115 kg</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Gói của</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>5 chiếc.</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Mã số thuế hải quan</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>56039390</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>EAN</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>4028177038332</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>ETIM 7.0</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>EC002513</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>ECLASS</strong><strong>8.0</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>27180706</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p><strong>Mô tả Sản phẩm</strong></p>\r\n			</td>\r\n			<td valign=\"top\" width=\"312\">\r\n			<p>Thảm lọc SK, dùng cho quạt lọc, cho SK 3243…/3244…/3245…, WHD: 289 x 289 x 12 mm</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<script data-ts=\"1744798465149\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p5_8_20250409015858.jpg', 'p5_8_20250409015858.jpg', 'resize_p5_8_20250409015858.jpg', 0, '', NULL, 1, 0, 0, 0, '20', 1, 1, '2025-02-11', '2025-04-16', '1744798465', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(21, 5, 20, 0, NULL, 'bo-loc-xep-nep-sk-3174-120', 'Bộ lọc xếp nếp SK 3174.120', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744182029585\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ lọc xếp nếp SK 3174.120', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>WHD: 265x100x18 mm</p>\r\n\r\n<p>Design: for roof-mounted fans</p>\r\n\r\n<p>Material: Pleated filter: Based on polyester, meltblown polycarbonate</p>\r\n\r\n<p>To fit Model No.: 3138.xxx; 3139.xxx; 3140.xxx</p>\r\n\r\n<p>IP protection category to IEC 60 529: IP54 in fan-and-filter units/roof-mounted fans/outlet filters</p>\r\n\r\n<p>Note: Performance data, protection category and device approvals are only guaranteed when used in conjunction with original Rittal filter mats.</p>\r\n<script data-ts=\"1744182029584\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p6_1_20250409020029.png', 'p6_1_20250409020029.png', 'resize_p6_1_20250409020029.png', NULL, '', NULL, 1, 0, 0, 0, '21', 1, 1, '2025-04-09', '2025-04-09', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(22, 5, 20, 0, NULL, 'bo-dieu-khien-ec-rittal', 'Bộ điều khiển EC Rittal', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744182240990\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ điều khiển EC Rittal', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>Rated operating voltage: 100 V – 250 V, 50 Hz/60 Hz</p>\r\n\r\n<p>Setting range: 5 °C...55 °C</p>\r\n\r\n<p>Speed: 100 %</p>\r\n\r\n<p>Supply includes: Speed control; NTC sensor, length 1.80 m</p>\r\n\r\n<p>To fit Model No.: 3240.500; 3241.500; 3243.500; 3244.500; 3245.XXX; 3140.500; 3140.510</p>\r\n\r\n<p>Function principle: Activation and monitoring of up to 4 EC fan-and-filter units; For mounting on a 35 mm support rail EN&nbsp;50&nbsp;022; External temperature sensor to record the actual temperature; Status LED to display the operating status; Alarm relay for reporting overtemperature, fan defect, cable break and sensor failure</p>\r\n<script data-ts=\"1744182240989\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p6_2_20250409020401.png', 'p6_2_20250409020401.png', 'resize_p6_2_20250409020401.png', NULL, '', NULL, 1, 0, 0, 0, '22', 1, 1, '2025-04-09', '2025-04-09', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(23, 5, 20, 0, NULL, 'bo-loc-dau-ra-rittal', 'Bộ lọc đầu ra Rittal', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744182283759\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ lọc đầu ra Rittal', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>WHD: 323 x 323 x 25 mm</p>\r\n\r\n<p>Material: ABS</p>\r\n\r\n<p>Colour: RAL 7035</p>\r\n\r\n<p>Supply includes: Outlet filter;&nbsp; Chopped-fibre filter mat</p>\r\n\r\n<p>To fit Model No.: SK 3243.1xx/3243.5xx/3244.1xx/3244.5xx/3245.5xx</p>\r\n<script data-ts=\"1744182283758\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p6_3_20250409020444.jpg', 'p6_3_20250409020444.jpg', 'resize_p6_3_20250409020444.jpg', NULL, '', NULL, 1, 0, 0, 0, '23', 1, 1, '2025-04-09', '2025-04-09', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(24, 5, 20, 0, NULL, 'bo-giam-sat-do-am-hygrostat-rittal-sk-3118000', 'Bộ giám sát độ ẩm Hygrostat Rittal SK 3118000', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744182326662\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ giám sát độ ẩm Hygrostat Rittal SK 3118000', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>Contact population: Single-pole change-over contact as a quick-break contact</p>\r\n\r\n<p>Permissible contact load: AC ~ 5 (0.2) A (inductive load at cos φ = 0.6)/DC = max. 20 WSetting range: 50 – 100% relative humidity</p>\r\n\r\n<p>Switching difference: approx. 4%</p>\r\n\r\n<p>Colour: RAL 7035</p>\r\n\r\n<p>WHD: 71 x 71 x 33.5 mm</p>\r\n\r\n<p>Rated operating voltage: 24&nbsp;V - 250&nbsp;V, 1~; 24 - 48 V (DC)</p>\r\n\r\n<p>Packs of: 1 pc(s).</p>\r\n\r\n<p>Weight/pack: 0.1 kg</p>\r\n<script data-ts=\"1744182326661\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p6_4_20250409020526.png', 'p6_4_20250409020526.png', 'resize_p6_4_20250409020526.png', NULL, '', NULL, 1, 0, 0, 0, '24', 1, 1, '2025-04-09', '2025-04-09', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(25, 5, 20, 0, NULL, 'bo-dieu-khien-nhiet-do-rittal-sk-3110000', 'Bộ điều khiển nhiệt độ Rittal SK 3110000', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744182382980\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ điều khiển nhiệt độ Rittal SK 3110000', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>Colour: RAL 7035</p>\r\n\r\n<p>WHD: 71 x 71 x 33.5 mm</p>\r\n\r\n<p>Setting range: 5 °C...60 °C</p>\r\n\r\n<p>Rated operating voltage: 24&nbsp;V - 230&nbsp;V, 1~; 24&nbsp;V - 60&nbsp;V&nbsp;(DC)</p>\r\n\r\n<p>Bi-metal controller as a temperature-sensitive element with thermal feedback</p>\r\n\r\n<p>Contact population: Single-pole change-over contact as a quick-break contact</p>\r\n\r\n<p>Permissible contact load: Category 5 – 3 (heating) AC 10 (4) A (inductive load at cos φ = 0.6)/category 5- 4 (cooling): AC 5 (4) A (inductive load at cos φ = 0.6)/DC = max. 30 W</p>\r\n\r\n<p>Switching difference: approx. 1 K ± 0.8 K</p>\r\n\r\n<p>Packs of: 1 pc(s).</p>\r\n\r\n<p>Weight/pack: 0.105 kg</p>\r\n<script data-ts=\"1744182382978\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p6_5_20250409020623.png', 'p6_5_20250409020623.png', 'resize_p6_5_20250409020623.png', NULL, '', NULL, 1, 0, 0, 0, '25', 1, 1, '2025-04-09', '2025-04-09', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(26, 5, 19, 0, NULL, 'quat-hut-noc-tu-dien-cong-nghe-ec-rittal-sk-3140510', 'Quạt hút nóc tủ điện công nghệ EC Rittal SK 3140510', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744182434839\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Quạt hút nóc tủ điện công nghệ EC Rittal SK 3140510', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>Colour: RAL 7035</p>\r\n\r\n<p>WHD: 400 x 133 x 400 mm,&nbsp;EC-Technology</p>\r\n\r\n<p>Air throughput, unimpeded air flow (without filter mats):&nbsp;At 50 Hz:&nbsp;1,069 m³/h;&nbsp;At 60 Hz:&nbsp;1,069 m³/h</p>\r\n\r\n<p>Rated operating voltage:&nbsp;115&nbsp;V, 1~, 60&nbsp;Hz</p>\r\n\r\n<p>Power consumption Pel:&nbsp;At 60 Hz:&nbsp;112 W</p>\r\n\r\n<p>Rated current max:&nbsp;At 60 Hz:&nbsp;1.51 A</p>\r\n\r\n<p>Operating temperature range: -20 °C...55 °C</p>\r\n\r\n<p>Storage temperature range:&nbsp;-40 °C...70 °C</p>\r\n<script data-ts=\"1744182434837\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p6_6_20250409020715.png', 'p6_6_20250409020715.png', 'resize_p6_6_20250409020715.png', NULL, '', NULL, 1, 0, 0, 0, '26', 1, 1, '2025-04-09', '2025-04-09', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(27, 5, 19, 0, NULL, 'quat-hut-noc-tu-dien-cong-nghe-ec-rittal-sk-3140500', 'Quạt hút nóc tủ điện công nghệ EC Rittal SK 3140500', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744182476984\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Quạt hút nóc tủ điện công nghệ EC Rittal SK 3140500', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>Colour: RAL 7035</p>\r\n\r\n<p>WHD: 400 x 133 x 400 mm,&nbsp;EC-Technology</p>\r\n\r\n<p>Air throughput, unimpeded air flow (without filter mats):&nbsp;At 50 Hz:&nbsp;1,069 m³/h;&nbsp;At 60 Hz:&nbsp;1,069 m³/h</p>\r\n\r\n<p>Rated operating voltage:&nbsp;220&nbsp;V - 240&nbsp;V, 1~, 50&nbsp;Hz/60&nbsp;Hz</p>\r\n\r\n<p>Power consumption Pel:&nbsp;At 50 Hz:&nbsp;129 W;&nbsp;At 60 Hz:&nbsp;129 W</p>\r\n\r\n<p>Rated current max:&nbsp;At 50 Hz:&nbsp;1 A;&nbsp;At 60 Hz:&nbsp;1 A</p>\r\n\r\n<p>Operating temperature range:&nbsp;--20 °C...55 °C</p>\r\n\r\n<p>Storage temperature range:&nbsp;-40 °C...70 °C</p>\r\n<script data-ts=\"1744182476982\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p6_7_20250409020757.png', 'p6_7_20250409020757.png', 'resize_p6_7_20250409020757.png', NULL, '', NULL, 1, 0, 0, 0, '27', 1, 1, '2025-04-09', '2025-04-09', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(28, 5, 19, 0, NULL, 'quat-hut-noc-tu-dien-rittal-3140140', 'Quạt hút nóc tủ điện Rittal 3140140', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744182519115\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Quạt hút nóc tủ điện Rittal 3140140', '', '', 0, 0, 0, 0, 0, '', NULL, '\r\n<p>Colour: RAL 7035</p>\r\n\r\n<p>WHD: 400 x 133 x 400 mm</p>\r\n\r\n<p>Air throughput, unimpeded air flow (without filter mats):&nbsp;At 50 Hz:&nbsp;863 m³/h; At 60 Hz:&nbsp;942 m³/h</p>\r\n\r\n<p>Rated operating voltage:&nbsp;380&nbsp;V - 415&nbsp;V, 3~, 50&nbsp;Hz/60&nbsp;Hz; 400&nbsp;V - 480&nbsp;V, 3~, 60&nbsp;Hz</p>\r\n\r\n<p>Power consumption Pel:&nbsp;At 50 Hz:&nbsp;98 W;&nbsp;At 60 Hz:&nbsp;130 W</p>\r\n\r\n<p>Rated current max:&nbsp;At 50 Hz:&nbsp;0.17 A;&nbsp;At 60 Hz:&nbsp;0.2 A</p>\r\n\r\n<p>Operating temperature range:&nbsp;--20 °C...55 °C</p>\r\n\r\n<p>Storage temperature range:&nbsp;-40 °C...70 °C</p>\r\n<script data-ts=\"1744182519114\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p6_8_20250409020839.png', 'p6_8_20250409020839.png', 'resize_p6_8_20250409020839.png', NULL, '', NULL, 1, 0, 0, 0, '28', 1, 1, '2025-04-09', '2025-04-09', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(29, 5, 18, NULL, NULL, 'may-lanh-tu-dien-rittal-sk-3370370', 'Máy lạnh tủ điện Rittal SK 3370370', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744601470121\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Máy lạnh tủ điện Rittal SK 3370370', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>Máy làm mát tủ điện, máy lạnh Rittal Compact Cooling Units. Công suất làm mát: 700 W. Điện áp hoạt động (V, ~, Hz): 220V, 1~ 50Hz / 60Hz. Thiết kế dạng mỏng (slim), tích hợp bộ điều khiển hiển thị kỹ thuật số cho dễ dàng vận hành và cảnh báo lỗi, môi chất lạnh R134a thân thiện với môi trường</p>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Công suất làm lạnh hữu ích theo tiêu chuẩn DIN 3168/EN 815: L35 L35 (℃ ): 700 W; L35 L50 (℃ ): 520 W</li>\r\n	<li>Điện áp hoạt động định mức: 220V, 1~ 50Hz / 60Hz</li>\r\n	<li>Dòng khởi động: 9.0 A / 9.6 A</li>\r\n	<li>Dòng định mức: 2.7 A / 2.7 A</li>\r\n	<li>Chất làm lạnh: R 134a, 280 g</li>\r\n	<li>Áp suất hoạt động cho phép: 35 bar</li>\r\n	<li>Phạm vi nhiệt độ: 20℃ ~ 50℃</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch nội: IP 54</li>\r\n</ul>\r\n<script data-ts=\"1744601470119\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p7_1_20250414032636.png', 'p7_1_20250414032636.png', 'resize_p7_1_20250414032636.png', 0, '', NULL, 1, 0, 0, 0, '29', 1, 1, '2025-04-14', '2025-04-14', '1744601497', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(30, 5, 18, NULL, NULL, 'may-lanh-tu-dien-rittal-sk-3370220', 'Máy lạnh tủ điện Rittal SK 3370220', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744601440392\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Máy lạnh tủ điện Rittal SK 3370220', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>Máy làm mát tủ điện, máy lạnh Rittal Compact Cooling Units. Công suất làm mát: 300 W. Điện áp hoạt động (V, ~, Hz): 220V, 1~ 50Hz / 60Hz. Thiết kế dạng mỏng (slim), tích hợp bộ điều khiển hiển thị kỹ thuật số cho dễ dàng vận hành và cảnh báo lỗi, môi chất lạnh R134a thân thiện với môi trường</p>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Công suất làm lạnh hữu ích theo tiêu chuẩn DIN 3168/EN 815: L35 L35 (℃ ): 300 W / 320 W; L35 L50 (℃ ): 150 W / 170 W</li>\r\n	<li>Điện áp hoạt động định mức: 220V, 1~ 50Hz / 60Hz</li>\r\n	<li>Dòng khởi động: 3.0 A / 3.4 A</li>\r\n	<li>Dòng định mức: 1.6 A / 1.8 A</li>\r\n	<li>Chất làm lạnh: R 134a, 100 g</li>\r\n	<li>Áp suất hoạt động cho phép: 35 bar</li>\r\n	<li>Phạm vi nhiệt độ: 20℃ ~ 50℃</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch nội: IP 54</li>\r\n</ul>\r\n\r\n<p><strong>Chi tiết sản phẩm</strong></p>\r\n\r\n<ul>\r\n	<li>Kích thước (mm):&nbsp;280 x 550 x 125</li>\r\n	<li>Trọng Lượng:&nbsp;13 kg</li>\r\n	<li>Màu sắc:&nbsp;RAL 7035</li>\r\n	<li>Chất liệu : Thép tấm</li>\r\n</ul>\r\n<script data-ts=\"1744601440390\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p7_2_20250414033040.jpg', 'p7_2_20250414033040.jpg', 'resize_p7_2_20250414033040.jpg', NULL, '', NULL, 1, 0, 0, 0, '30', 1, 1, '2025-04-14', '2025-04-14', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(31, 5, 18, NULL, NULL, 'may-lanh-tu-dien-rittal-wall-mounted-cooling-unit-3187630', 'Máy lạnh tủ điện Rittal Wall-mounted cooling unit 3187630', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744601765316\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Máy lạnh tủ điện Rittal Wall-mounted cooling unit 3187630', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>Bộ làm mát SK Blue e+, treo tường, 2,6 kW, 110-240 V, 1~, 380-480 V, 3~, 50-60 Hz,được làm bằng Thép không gỉ, WHD: 450 x 1600 x 294 mm</p>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Công suất làm lạnh hữu ích theo tiêu chuẩn DIN EN 14511:&nbsp;L35 L35/50 Hz:&nbsp;2.6 kW;&nbsp;L35 L35/60 Hz:&nbsp;2.6 kW;&nbsp;L35 L50/50 Hz:&nbsp;1.82 kW;&nbsp;L35 L50/60 Hz:&nbsp;1.82 kW</li>\r\n	<li>Điện áp hoạt động định mức:&nbsp;110&nbsp;V - 240&nbsp;V, 1~, 50&nbsp;Hz/60&nbsp;Hz;&nbsp;380&nbsp;V - 480&nbsp;V, 3~, 50&nbsp;Hz/60&nbsp;Hz</li>\r\n	<li>Công suất đầu vào định mức:&nbsp;1.05 kW</li>\r\n	<li>Thông lượng không khí: mạch ngoài&nbsp;1,250 m³/h; mạch trong&nbsp;1,250 m³/h</li>\r\n	<li>Tỷ lệ hiệu quả năng lượng (EER) 50/60 Hz L35 L35:&nbsp;L35 L35 (EER) 50 Hz:&nbsp;2.63;&nbsp;L35 L35 (EER) 60 Hz:&nbsp;2.63</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch trong:&nbsp;IP 55</li>\r\n	<li>Chất làm lạnh:&nbsp;R134a;&nbsp;1.15 kg</li>\r\n	<li>Nhiệt độ hoạt động:&nbsp;-20 °C...60 °C</li>\r\n	<li>Phạm vi nhiệt độ lưu trữ:&nbsp;-40 °C...70 °C</li>\r\n	<li>Phạm vi nhiệt độ:&nbsp;20 °C...50 °C</li>\r\n	<li>Áp suất hoạt động cho phép:&nbsp;24&nbsp;bar</li>\r\n</ul>\r\n\r\n<p><strong>Chi tiết sản phẩm</strong></p>\r\n\r\n<ul>\r\n	<li>Kích thước (Rộng x cao x sâu):&nbsp;450 mm x&nbsp;1,600 mm x&nbsp;294 mm</li>\r\n	<li>Trọng Lượng:&nbsp;54.8 kg&nbsp;</li>\r\n	<li>Màu sắc:&nbsp;RAL 9007</li>\r\n	<li>Chất liệu: Thép tấm</li>\r\n	<li>Thiết kế : treo tường</li>\r\n</ul>\r\n<script data-ts=\"1744601765313\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p7_3_20250414033605.jpg', 'p7_3_20250414033605.jpg', 'resize_p7_3_20250414033605.jpg', NULL, '', NULL, 1, 0, 0, 0, '31', 1, 1, '2025-04-14', '2025-04-14', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(32, 5, 18, NULL, NULL, 'may-lanh-tu-dien-rittal-toptherm-wall-mounted-cooling-unit-3304504', 'Máy lạnh tủ điện Rittal TopTherm wall-mounted cooling unit 3304504', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744601916868\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Máy lạnh tủ điện Rittal TopTherm wall-mounted cooling unit 3304504', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>Bộ làm mát SK Blue e, treo tường, NEMA 4X, 1,1 kW, 230 V, 1~, 50/60 Hz, Thép không gỉ, WHD: 405 x 1020 x 358 mm</p>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Công suất làm lạnh hữu ích theo tiêu chuẩn DIN EN 14511:&nbsp;L35 L35/50 Hz:&nbsp;1.1 kW;&nbsp;L35 L35/60 Hz:&nbsp;1.25 kW;&nbsp;L35 L50/50 Hz:&nbsp;0.91 kW;&nbsp;L35 L50/60 Hz:&nbsp;0.9 kW</li>\r\n	<li>Điện áp hoạt động định mức:&nbsp;230&nbsp;V, 1~, 50&nbsp;Hz/60&nbsp;Hz</li>\r\n	<li>Dòng khởi động:&nbsp;12 A/14 A</li>\r\n	<li>Dòng định mức:&nbsp;3.9 A/4.3 A</li>\r\n	<li>Thông lượng không khí mạch ngoài:&nbsp;805 m³/h</li>\r\n	<li>Thông lượng không khí mạch trong:&nbsp;600 m³/h</li>\r\n	<li>Tỷ lệ hiệu quả năng lượng (EER) 50/60 Hz L35 L35:&nbsp;L35 L35 (EER) 50 Hz:&nbsp;1.83;&nbsp;L35 L35 (EER) 60 Hz:&nbsp;1.84</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch ngoài:&nbsp;IP 34</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch trong:&nbsp;IP 55</li>\r\n	<li>Chất làm lạnh:&nbsp;R134a,&nbsp;0.325 kg</li>\r\n	<li>Nhiệt độ hoạt động:&nbsp;10 °C...55 °C</li>\r\n	<li>Phạm vi nhiệt độ lưu trữ:&nbsp;-40 °C...70 °C</li>\r\n	<li>Phạm vi nhiệt độ:&nbsp;20 °C...50 °C</li>\r\n	<li>Áp suất hoạt động cho phép:&nbsp;28&nbsp;bar</li>\r\n</ul>\r\n\r\n<p><strong>Chi tiết sản phẩm</strong></p>\r\n\r\n<ul>\r\n	<li>Kích thước (mm): 405mm x 1020mm x 358mm</li>\r\n	<li>Trọng Lượng: 49 kg</li>\r\n	<li>Màu sắc: 7035</li>\r\n	<li>chất liệu: Thép tấm</li>\r\n	<li>Thiết kế : treo tường</li>\r\n</ul>\r\n<script data-ts=\"1744601916865\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 