(33, 5, 18, NULL, NULL, 'may-lanh-tu-dien-rittal-sk-rtt-blue-e-wall-mounted-cooler-750w-3361-600', 'Máy lạnh tủ điện Rittal SK RTT Blue e Wall-mounted Cooler 750W_ 3361.600', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744602317797\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Máy lạnh tủ điện Rittal SK RTT Blue e Wall-mounted Cooler 750W_ 3361.600', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>Bộ làm mát SK Blue e, treo tường, 0,85 kW, 230 V, 1~, 50/60 Hz, Thép không gỉ, WHD: 280 x 550 x 280 mm</p>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Công suất làm lạnh hữu ích theo tiêu chuẩn DIN&nbsp;EN&nbsp;14511:&nbsp;L35 L35/50 Hz:&nbsp;0.85 kW,&nbsp;L35 L35/60 Hz:&nbsp;0.89 kW,&nbsp;L35 L50/50 Hz:&nbsp;0.67 kW,&nbsp;L35 L50/60 Hz:&nbsp;0.67 kW</li>\r\n	<li>Công suất làm lạnh&nbsp; L35 L30:&nbsp;L35 L35 (EER) 50 Hz:&nbsp;2.08,&nbsp;L35 L35 (EER) 60 Hz:&nbsp;2.03</li>\r\n	<li>Điện áp hoạt động định mức:&nbsp;230&nbsp;V, 1~, 50&nbsp;Hz/60&nbsp;Hz</li>\r\n	<li>Dòng khởi động: 6 A/9.6 A</li>\r\n	<li>Dòng định mức: 2.7 A&nbsp;</li>\r\n	<li>Chất làm lạnh:&nbsp;R134a,&nbsp;0.28 kg</li>\r\n	<li>Áp suất hoạt động cho phép:&nbsp;28&nbsp;bar</li>\r\n	<li>Phạm vi nhiệt độ:&nbsp;20 °C...55 °C</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch nội: IP 54</li>\r\n	<li>Kích thước (mm): 280 x 550 x 280</li>\r\n	<li>Trọng Lượng:&nbsp;22 kg</li>\r\n	<li>Màu sắc:&nbsp;RAL 9007</li>\r\n</ul>\r\n<script data-ts=\"1744602317794\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p7_6_20250414034518.jpg', 'p7_6_20250414034518.jpg', 'resize_p7_6_20250414034518.jpg', 0, '', NULL, 1, 0, 0, 0, '33', 1, 1, '2025-04-14', '2025-04-14', '1744602318', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(34, 5, 18, NULL, NULL, 'may-lanh-tu-dien-rittal-toptherm-wall-mounted-cooling-unit-3305508', 'Máy lạnh tủ điện Rittal, TopTherm wall-mounted cooling unit 3305508', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744602257082\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Máy lạnh tủ điện Rittal, TopTherm wall-mounted cooling unit 3305508', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>Bộ làm mát SK Blue e, treo tường, UL Loại 3R/ 4,, 1,53 kW, 230 V, 1~, 50/60 Hz,, Thép tấm,, WHD: 405 x 1020 x 358 mm,</p>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Điện áp hoạt động định mức: 230 V, 1~, 50 Hz/60 Hz</li>\r\n	<li>Kích thước (Rộng x Cao x Sâu): 405 x 1.020 x 358</li>\r\n	<li>Công suất làm lạnh hữu ích theo tiêu chuẩn DIN 14511: L35 L35/50 Hz: 1.53 kW, L35 L35/60 Hz: 1.84 kW, L35 L50/50 Hz: 1.08 kW, L35 L50/60 Hz: 1.3 kW&nbsp;</li>\r\n	<li>Dòng điện định mức: 5.5 A/5.8 A</li>\r\n	<li>Dòng khởi động: 12 A/ 14 A</li>\r\n	<li>Chất làm lạnh: R 134a, 0.5 kg</li>\r\n	<li>Áp suất hoạt động cho phép: 35 bar</li>\r\n	<li>Phạm vi nhiệt độ: 20℃ ~ 50℃</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch nội: IP 56</li>\r\n	<li>Trọng lượng: 51 kg</li>\r\n	<li>Màu sắc: RAL 7035</li>\r\n</ul>\r\n<script data-ts=\"1744602257079\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p7_5_20250414034417.jpg', 'p7_5_20250414034417.jpg', 'resize_p7_5_20250414034417.jpg', 0, '', NULL, 1, 0, 0, 0, '34', 1, 1, '2025-04-14', '2025-04-14', '1744602257', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(35, 5, 18, NULL, NULL, 'may-lanh-tu-dien-rittal-sk-rtt-blue-e-wall-mounted-cooler-4000w-3332-540', 'Máy lạnh tủ điện Rittal SK RTT Blue e Wall-mounted Cooler 4000W 3332.540', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744602384009\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Máy lạnh tủ điện Rittal SK RTT Blue e Wall-mounted Cooler 4000W 3332.540', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>Bộ làm mát SK Blue e, treo tường, 3,95 kW, 400-460 V, 3~, 50/60 Hz, Thép tấm, WHD: 500 x 1580 x 340 mm</p>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Công suất làm lạnh hữu ích theo tiêu chuẩn DIN&nbsp;EN&nbsp;14511:&nbsp;L35 L35/50 Hz:&nbsp;3.95 kW,&nbsp;L35 L35/60 Hz:&nbsp;4.35 kW,&nbsp;L35 L50/50 Hz:&nbsp;3.02 kW,&nbsp;L35 L50/60 Hz:&nbsp;3.52 kW</li>\r\n	<li>Điện áp hoạt động định mức:&nbsp;400&nbsp;V, 3~, 50&nbsp;Hz,&nbsp;460&nbsp;V, 3~, 60&nbsp;Hz</li>\r\n	<li>Dòng khởi động:&nbsp;9.2 A/11 A</li>\r\n	<li>Dòng định mức:&nbsp;4.2 A</li>\r\n	<li>Chất làm lạnh:&nbsp;R134a,&nbsp;2.995 kg</li>\r\n	<li>Áp suất hoạt động cho phép:&nbsp;28&nbsp;bar</li>\r\n	<li>Phạm vi nhiệt độ:&nbsp;20 °C...55 °C</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch nội:&nbsp;IP 54</li>\r\n	<li>Kích thước (mm): 500 x 1.580 x 340</li>\r\n	<li>Trọng Lượng:&nbsp;91 kg</li>\r\n	<li>Màu sắc:&nbsp;RAL 7035</li>\r\n</ul>\r\n<script data-ts=\"1744602384006\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p7_7_20250414034624.jpg', 'p7_7_20250414034624.jpg', 'resize_p7_7_20250414034624.jpg', NULL, '', NULL, 1, 0, 0, 0, '35', 1, 1, '2025-04-14', '2025-04-14', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(36, 5, 18, NULL, NULL, 'may-lanh-tu-dien-rittal-sk-rtt-blue-e-wall-mounted-cooler-2500w-3329-500', 'Máy lạnh tủ điện Rittal SK RTT Blue e Wall-mounted Cooler 2500W - 3329.500', NULL, '', NULL, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1744602444226\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Máy lạnh tủ điện Rittal SK RTT Blue e Wall-mounted Cooler 2500W - 3329.500', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>Bộ làm mát SK Blue e, treo tường, 2,55 kW, 230 V, 1~, 50/60 Hz, Thép tấm, WHD: 400 x 1580 x 295 mm</p>\r\n\r\n<p><strong>Thông số kỹ thuật</strong></p>\r\n\r\n<ul>\r\n	<li>Công suất làm lạnh hữu ích theo tiêu chuẩn DIN EN&nbsp;14511:&nbsp;L35 L35/50 Hz:&nbsp;2.55 kW,&nbsp;L35 L35/60 Hz:&nbsp;2.71 kW,&nbsp;L35 L50/50 Hz:&nbsp;1.8 kW,&nbsp;L35 L50/60 Hz:&nbsp;1.8 kW</li>\r\n	<li>Điện áp hoạt động định mức:&nbsp;230 V, 1~, 50 Hz/60 Hz</li>\r\n	<li>Dòng khởi động: 25 A/22 A</li>\r\n	<li>Dòng định mức: 7.9 A/ 9.3 A</li>\r\n	<li>Chất làm lạnh:&nbsp;R134a, 0.95 Kg</li>\r\n	<li>Áp suất hoạt động cho phép:&nbsp;28&nbsp;bar</li>\r\n	<li>Phạm vi nhiệt độ:&nbsp;20 °C...55 °C</li>\r\n	<li>Loại bảo vệ EN 60529 của mạch nội:&nbsp;IP 54</li>\r\n	<li>Kích thước (mm): 400 x 1.580 x 295</li>\r\n	<li>Trọng Lượng:&nbsp;69 kg</li>\r\n	<li>Màu sắc:&nbsp;RAL 7035</li>\r\n</ul>\r\n<script data-ts=\"1744602444223\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'p7_8_20250414034724.jpg', 'p7_8_20250414034724.jpg', 'resize_p7_8_20250414034724.jpg', NULL, '', NULL, 1, 0, 0, 0, '36', 1, 1, '2025-04-14', '2025-04-14', NULL, '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(37, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg500-lovato', 'Đồng hồ đo đa năng DMG500 LOVATO', NULL, '', NULL, 0, 0, '<p>Đồng hồ đo đa năng DMG500 LOVATO màn hình LCD có đèn nền kích thước 72x46mm, cấp chính xác Class 1, hỗ trợ phân tích sóng hài dòng điện đến bậc 15, lắp đặt mặt tủ tiêu chuẩn.</p>', 'Đồng hồ đo đa năng DMG500 LOVATO', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Đồng hồ đo điện đa năng LCD lắp mặt tủ (Flush mount), màn hình LCD có đèn nền hiển thị biểu tượng kích thước 72x46mm (2.8x1.8”), nguồn cấp phụ 100-440VAC / 120-250VDC, tích hợp cổng quang mặt trước.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Thiết bị đo lường kỹ thuật số đa năng</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 1 (Class 1 theo IEC/EN 62053-21)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 2 (Class 2 theo IEC/EN 62053-23)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 15 (15th order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> Không</li>\r\n	<li><b>Khả năng mở rộng:</b> Không</li>\r\n</ul>', 'p81_20250414043756.jpg', 'p81_20250414043756.jpg', 'resize_p81_20250414043756.jpg', 0, '', NULL, 1, 0, 0, 0, '37', 1, 1, '2025-04-14', '2025-04-14', '1744605476', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(38, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg510', 'Đồng hồ đo đa năng DMG510', NULL, '', NULL, 0, 0, '<p>Đồng hồ đo đa năng DMG510 LOVATO tích hợp sẵn cổng truyền thông RS485 (Modbus), màn hình LCD đèn nền sắc nét, cấp chính xác Class 1, phân tích sóng hài đến bậc 15.</p>', 'Đồng hồ đo đa năng DMG510', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Đồng hồ đo điện đa năng LCD lắp mặt tủ (Flush mount), màn hình LCD có đèn nền hiển thị biểu tượng kích thước 72x46mm (2.8x1.8”), nguồn cấp phụ 100-440VAC / 120-250VDC, tích hợp cổng quang mặt trước và cổng truyền thông RS485.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Thiết bị đo lường kỹ thuật số đa năng</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 1 (Class 1 theo IEC/EN 62053-21)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 2 (Class 2 theo IEC/EN 62053-23)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 15 (15th order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> RS485 (Modbus)</li>\r\n	<li><b>Khả năng mở rộng:</b> Không</li>\r\n</ul>', 'p81_20250414043805.jpg', 'p81_20250414043805.jpg', 'resize_p81_20250414043805.jpg', 0, '', NULL, 1, 0, 0, 0, '38', 1, 1, '2025-04-14', '2025-04-14', '1744605485', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(39, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg600-lovato', 'Đồng hồ đo đa năng DMG600 LOVATO', NULL, '', NULL, 0, 0, '<p>Đồng hồ đo đa năng DMG600 LOVATO màn hình LCD đồ họa có đèn nền, có khả năng mở rộng với các module EXP, cấp chính xác Class 1, phân tích sóng hài đến bậc 15.</p>', 'Đồng hồ đo đa năng DMG600 LOVATO', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Đồng hồ đo điện đa năng LCD lắp mặt tủ (Flush mount), có khả năng mở rộng module, màn hình LCD có đèn nền hiển thị biểu tượng kích thước 72x46mm (2.8x1.8”), nguồn cấp phụ 100-440VAC / 120-250VDC, tích hợp cổng quang mặt trước.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Thiết bị đo lường kỹ thuật số đa năng</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 1 (Class 1 theo IEC/EN 62053-21)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 2 (Class 2 theo IEC/EN 62053-23)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 15 (15th order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> Không</li>\r\n	<li><b>Khả năng mở rộng:</b> Có (Hỗ trợ module mở rộng EXP...)</li>\r\n</ul>', 'p81_20250414043813.jpg', 'p81_20250414043813.jpg', 'resize_p81_20250414043813.jpg', 0, '', NULL, 1, 0, 0, 0, '39', 1, 1, '2025-04-14', '2025-04-14', '1744605493', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(40, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg610-lovato', 'Đồng hồ đo đa năng DMG610 LOVATO', NULL, '', NULL, 0, 0, '<p>Đồng hồ đo đa năng DMG610 LOVATO tích hợp sẵn cổng RS485 và khả năng mở rộng module EXP, màn hình LCD đèn nền, phân tích sóng hài đến bậc 15.</p>', 'Đồng hồ đo đa năng DMG610 LOVATO', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Đồng hồ đo điện đa năng LCD lắp mặt tủ (Flush mount), có khả năng mở rộng module, màn hình LCD có đèn nền hiển thị biểu tượng kích thước 72x46mm (2.8x1.8”), nguồn cấp phụ 100-440VAC / 120-250VDC, tích hợp cổng quang mặt trước và cổng truyền thông RS485.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Thiết bị đo lường kỹ thuật số đa năng</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 1 (Class 1 theo IEC/EN 62053-21)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 2 (Class 2 theo IEC/EN 62053-23)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 15 (15th order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> RS485 (Modbus)</li>\r\n	<li><b>Khả năng mở rộng:</b> Có (Hỗ trợ module mở rộng EXP...)</li>\r\n</ul>', 'p81_20250414043823.jpg', 'p81_20250414043823.jpg', 'resize_p81_20250414043823.jpg', 0, '', NULL, 1, 0, 0, 0, '40', 1, 1, '2025-04-14', '2025-04-14', '1744605503', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(41, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg615-lovato', 'Đồng hồ đo đa năng DMG615 LOVATO', NULL, '', NULL, 0, 0, '<p>Đồng hồ đo đa năng DMG615 LOVATO độ chính xác cao Class 0.5s, tích hợp cổng RS485, có thể mở rộng module EXP, phân tích chất lượng điện năng chuyên sâu.</p>', 'Đồng hồ đo đa năng DMG615 LOVATO', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Đồng hồ đo điện đa năng LCD lắp mặt tủ (Flush mount), có khả năng mở rộng module. Độ chính xác cao vượt trội khi đo điện năng tác dụng với Cấp 0.5s. Màn hình LCD có đèn nền kích thước 72x46mm (2.8x1.8”), phân tích sóng hài, nguồn cấp phụ 100-440VAC / 120-250VDC, tích hợp cổng quang mặt trước và cổng RS485.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Thiết bị đo lường kỹ thuật số đa năng độ chính xác cao</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 0.5s (Class 0.5s theo IEC/EN 62053-22)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 2 (Class 2 theo IEC/EN 62053-23)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 15 (15th order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> RS485 (Modbus)</li>\r\n	<li><b>Khả năng mở rộng:</b> Có (Hỗ trợ module mở rộng EXP...)</li>\r\n</ul>', 'p81_20250414043840.jpg', 'p81_20250414043840.jpg', 'resize_p81_20250414043840.jpg', 0, '', NULL, 1, 0, 0, 0, '41', 1, 1, '2025-04-14', '2025-04-14', '1744605520', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(42, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg7000-lovato', 'Đồng hồ đo đa năng DMG7000 LOVATO', NULL, '', NULL, 0, 0, '<p>Bộ phân tích chất lượng điện năng DMG7000 LOVATO màn hình màu LCD góc rộng, cấp chính xác Class 0.5s, phân tích sóng hài đến bậc 63, mở rộng tối đa 3 module EXP.</p>', 'Đồng hồ đo đa năng DMG7000 LOVATO', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Bộ phân tích chất lượng điện năng cao cấp với màn hình màu LCD góc rộng sắc nét. Nguồn nuôi phụ 100...240VAC. Có khả năng mở rộng với tối đa 3 module EXP…, phân tích sóng hài dòng điện đến bậc 63, tương thích với hệ thống giám sát năng lượng EASY BRANCH.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Bộ phân tích điện năng và hệ thống giám sát EASY BRANCH</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 0.5s (Class 0.5s theo IEC/EN 62053-22)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 1 (Class 1 theo IEC/EN 62053-24)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 63 (63rd order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> Không</li>\r\n	<li><b>Khả năng mở rộng:</b> Có (Mở rộng tối đa 3 module EXP...)</li>\r\n</ul>', 'p82_20250414043851.jpg', 'p82_20250414043851.jpg', 'resize_p82_20250414043851.jpg', 0, '', NULL, 1, 0, 0, 0, '42', 1, 1, '2025-04-14', '2025-04-14', '1744605531', '', '', '', '', '', '', '', '', '', '', '', 0, '', '');
INSERT INTO `cycletech_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `ctype`, `ccode`, `cproducts`, `cloai_tin`, `ctag`, `nview`, `fprice`, `fprice_sale`, `cdescription`, `fb_cdescription`, `cgioi_thieu`, `cdia_diem`, `nid_loai_tin`, `nid_loai_bds`, `nid_province`, `nid_district`, `nid_huong`, `cdien_tich`, `eng_cdetail`, `cdetail`, `cimage`, `cproduct_fb`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nhome`, `nnew`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `ctime_update`, `cphong_an`, `cnha_bep`, `csan_thuong`, `ccho_de_xe`, `cchinh_chu`, `cchieu_ngang`, `cchieu_dai`, `cso_lau`, `cso_phong_ngu`, `cphap_ly`, `cduong_truoc_nha`, `nspecial`, `ccode_product`, `ckeyword`) VALUES
(43, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg7500-lovato', 'Đồng hồ đo đa năng DMG7500 LOVATO', NULL, '', NULL, 0, 0, '<p>Bộ phân tích chất lượng điện năng DMG7500 LOVATO màn hình màu LCD, tích hợp cổng RS485, Class 0.5s, phân tích sóng hài bậc 63, mở rộng 3 module EXP, tương thích Easy Branch.</p>', 'Đồng hồ đo đa năng DMG7500 LOVATO', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Bộ phân tích chất lượng điện năng với màn hình màu LCD góc rộng. Nguồn nuôi phụ 100...240VAC. Có khả năng mở rộng với 3 module EXP..., tích hợp sẵn cổng truyền thông RS485, tương thích hoàn hảo với hệ thống giám sát điện năng Easy Branch.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Bộ phân tích điện năng và hệ thống giám sát EASY BRANCH</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 0.5s (Class 0.5s theo IEC/EN 62053-22)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 1 (Class 1 theo IEC/EN 62053-24)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 63 (63rd order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> RS485 (Modbus)</li>\r\n	<li><b>Khả năng mở rộng:</b> Có (Mở rộng tối đa 3 module EXP...)</li>\r\n</ul>', 'p82_20250414043900.jpg', 'p82_20250414043900.jpg', 'resize_p82_20250414043900.jpg', 0, '', NULL, 1, 0, 0, 0, '43', 1, 1, '2025-04-14', '2025-04-14', '1744605540', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(44, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg8000-lovato', 'Đồng hồ đo đa năng DMG8000 LOVATO', NULL, '', NULL, 0, 0, '<p>Bộ phân tích chất lượng điện năng DMG8000 LOVATO màn hình màu LCD, tích hợp cổng Ethernet, bộ nhớ Data Logging ghi nhật ký dữ liệu, Class 0.5s, phân tích sóng hài bậc 63.</p>', 'Đồng hồ đo đa năng DMG8000 LOVATO', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Bộ phân tích chất lượng điện năng với màn hình màu LCD góc rộng. Nguồn nuôi phụ 100...240VAC. Khả năng mở rộng với 3 module EXP..., tích hợp sẵn cổng mạng Ethernet, tích hợp bộ nhớ lưu trữ dữ liệu (Data memory for logging), tương thích hệ thống Easy Branch.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Bộ phân tích điện năng và hệ thống giám sát EASY BRANCH</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 0.5s (Class 0.5s theo IEC/EN 62053-22)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 1 (Class 1 theo IEC/EN 62053-24)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 63 (63rd order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> Ethernet</li>\r\n	<li><b>Khả năng mở rộng:</b> Có (Mở rộng tối đa 3 module EXP...)</li>\r\n</ul>', 'p82_20250414043907.jpg', 'p82_20250414043907.jpg', 'resize_p82_20250414043907.jpg', 0, '', NULL, 1, 0, 0, 0, '44', 1, 1, '2025-04-14', '2025-04-14', '1744605547', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(45, 6, 21, NULL, NULL, 'dong-ho-do-da-nang-dmg9000-lovato', 'Đồng hồ đo đa năng DMG9000 LOVATO', NULL, '', NULL, 0, 0, '<p>Bộ phân tích chất lượng điện năng cao cấp DMG9000 LOVATO tích hợp đồng thời cổng RS485 và Ethernet, bộ nhớ Data Logging, Class 0.5s, phân tích sóng hài bậc 63, mở rộng 3 module EXP.</p>', 'Đồng hồ đo đa năng DMG9000 LOVATO', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p>Bộ phân tích chất lượng điện năng hàng đầu với màn hình màu LCD góc rộng. Nguồn nuôi phụ 100...240VAC. Khả năng mở rộng linh hoạt với 3 module EXP..., tích hợp sẵn cả 2 cổng truyền thông RS485 và Ethernet, bộ nhớ ghi nhật ký dữ liệu (data logging), tương thích hoàn hảo với hệ thống giám sát Easy Branch.</p>\r\n\r\n<ul>\r\n	<li><b>Loại sản phẩm:</b> Bộ phân tích điện năng và hệ thống giám sát EASY BRANCH</li>\r\n	<li><b>Kiểu lắp đặt:</b> Lắp trên cánh tủ (Flush mounting)</li>\r\n	<li><b>Kiểu đấu nối dòng điện:</b> Qua biến dòng CT /5A /1A</li>\r\n	<li><b>Độ chính xác đo điện năng tác dụng (kWh):</b> Cấp 0.5s (Class 0.5s theo IEC/EN 62053-22)</li>\r\n	<li><b>Độ chính xác đo điện năng phản kháng (kvarh):</b> Cấp 1 (Class 1 theo IEC/EN 62053-24)</li>\r\n	<li><b>Phân tích sóng hài dòng điện:</b> Đến bậc 63 (63rd order)</li>\r\n	<li><b>Cổng truyền thông tích hợp:</b> RS485 và Ethernet</li>\r\n	<li><b>Khả năng mở rộng:</b> Có (Mở rộng tối đa 3 module EXP...)</li>\r\n</ul>', 'p82_20250414043915.jpg', 'p82_20250414043915.jpg', 'resize_p82_20250414043915.jpg', 0, '', NULL, 1, 0, 0, 0, '45', 1, 1, '2025-04-14', '2025-04-14', '1744605555', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(46, 3, 14, NULL, NULL, 'bo-loc-song-hai-chu-dong', 'Bộ lọc sóng hài chủ động', NULL, '', NULL, 0, 0, '\r\n<p><strong>Bộ lọc sóng hài chủ động (AHF) của Enjoypowers là giải pháp chất lượng điện năng tiên tiến giúp giảm thiểu sóng hài, cải thiện hệ số công suất và cân bằng tải ba pha.</strong></p>\r\n\r\n<ul>\r\n	<li>Đáp ứng tiêu chuẩn IEEE 519 về sóng hài</li>\r\n	<li>Giảm THDi xuống &lt;5%</li>\r\n	<li>Loại bỏ sóng hài dòng điện trung tính</li>\r\n	<li>Công nghệ cấu trúc ba cấp hợp tác với Infineon</li>\r\n	<li>Thiết kế mô-đun và có thể mở rộng</li>\r\n</ul>\r\n<script data-ts=\"1744688500835\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Bộ lọc sóng hài chủ động', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p><strong>Phạm vi điện áp</strong></p>\r\n\r\n<ul>\r\n	<li>Enjoypowers AHF hỗ trợ nhiều mức điện áp, bao gồm 200V, 400V, 480V, 690V và 800V, đảm bảo tích hợp liền mạch trên nhiều hệ thống điện khác nhau.</li>\r\n</ul>\r\n\r\n<p><strong>Công suất định mức</strong></p>\r\n\r\n<ul>\r\n	<li>Với công suất định mức từ 30A đến 200A, AHF của chúng tôi cung cấp các giải pháp lọc sóng hài có khả năng mở rộng cho nhiều ứng dụng công nghiệp và thương mại khác nhau.</li>\r\n</ul>\r\n\r\n<p><strong>Lệnh hài hòa</strong></p>\r\n\r\n<ul>\r\n	<li>Loại bỏ hiệu quả sóng hài bậc 2 đến bậc 50, cải thiện chất lượng điện năng, giảm THDi và đảm bảo tuân thủ tiêu chuẩn IEEE 519.​</li>\r\n</ul>\r\n\r\n<p><strong>Tổng quan về thông số kỹ thuật cốt lõi của AHF</strong></p>\r\n\r\n<ul>\r\n	<li>Tần số: 50/60Hz</li>\r\n	<li>Hiệu suất: &gt;97%</li>\r\n	<li>Thời gian phản hồi: &lt;10ms</li>\r\n	<li>Tỷ lệ loại bỏ sóng hài: &gt;95%</li>\r\n	<li>Kiểu dây: 3P3W/3P4W (Tương thích)</li>\r\n	<li>Giao diện truyền thông: RS485, Giao thức Modbus</li>\r\n	<li>Kiểu lắp đặt: Tủ gắn trên giá, tủ gắn tường và tủ đứng trên sàn</li>\r\n</ul>\r\n\r\n<p><strong>Nguyên lý hoạt động của AHF</strong></p>\r\n\r\n<ul>\r\n	<li>AHF phát hiện sóng hài theo thời gian thực và tạo ra dòng điện đối kháng để loại bỏ hiện tượng méo sóng hài, đảm bảo chất lượng điện năng.\r\n	<ul>\r\n		<li>Thuật toán nâng cao: Biến đổi Fourier nhanh (FFT) đảm bảo phản ứng hài hòa nhanh chóng và chính xác.</li>\r\n		<li>Phần cứng mạnh mẽ: Các linh kiện chất lượng cao giúp nâng cao hiệu quả và độ tin cậy của sản phẩm.</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Loại bỏ dòng điện trung tính với AHF</strong></p>\r\n\r\n<ul>\r\n	<li>Dòng điện trung tính xảy ra do sóng hài bậc ba và tải không cân bằng, dẫn đến dòng điện quá mức chạy qua dây trung tính. Điều này có thể gây ra quá nhiệt, hư hỏng thiết bị và kém hiệu quả trong hệ thống điện.</li>\r\n	<li>AHF loại bỏ hiệu quả dòng điện trung tính do méo hài, cải thiện tính ổn định và an toàn của hệ thống.</li>\r\n</ul>\r\n\r\n<p><strong>Thiết kế mô-đun</strong></p>\r\n\r\n<ul>\r\n	<li>Thiết kế siêu nhỏ gọn, cấu trúc gắn tường và gắn giá đỡ, phân bổ công suất hợp lý có thể đáp ứng đầy đủ nhu cầu của khách hàng, phù hợp cho các ứng dụng có không gian hạn chế, các dự án cải tạo.</li>\r\n	<li>Dễ vận chuyển và thay thế, dễ tích hợp vào tủ.</li>\r\n</ul>\r\n<script data-ts=\"1744688500832\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'song_hai_20250415033255.png', 'song_hai_20250415033255.png', 'resize_song_hai_20250415033255.png', 0, '', NULL, 0, 0, 0, 0, '46', 1, 1, '2025-04-15', '2025-04-15', '1744688501', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(47, 7, 22, NULL, NULL, 'bien-tan-sungrow-mg5rl-mg6rl', 'Biến Tần Sungrow Mg5rl/Mg6rl', NULL, '', NULL, 0, 0, '\r\n<p>Biến tần hòa lưới Sungrow MG5RL và MG6RL là bộ đôi giải pháp năng lượng thông minh, trong đó MG5RL tối ưu cho gia đình nhỏ với khả năng tiết kiệm điện vượt trội, còn MG6RL nổi bật nhờ sức mạnh linh hoạt hơn, phù hợp với nhu cầu tiêu thụ lớn và đảm bảo an toàn, ổn định cho hệ thống điện năng lượng mặt trời hiện đại</p>\r\n<script data-ts=\"1757083085373\" src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'Biến tần hòa lưới Sungrow MG5RL và MG6RL là bộ đôi giải pháp năng lượng thông minh, trong đó MG5RL tối ưu cho gia đình nhỏ với khả năng tiết kiệm điện vượt trội, còn MG6RL nổi bật nhờ sức mạnh linh hoạt hơn, phù hợp với nhu cầu tiêu thụ lớn và đảm bảo an toàn, ổn định cho hệ thống điện năng lượng mặt trời hiện đại', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<div class=\"table-container\">\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"video-container\">\r\n<video autoplay=\"\" class=\"responsive-video\" controls=\"\" loop=\"\" muted=\"\"><source src=\"https://toandanhco.com.vn/upload/video/bien-tan-sungrow-mg5rl-mg6rl.m4v\" type=\"video/mp4\"> Trình duyệt của bạn không hỗ trợ thẻ video HTML5.</video>\r\n</div>\r\n\r\n<p><b>Sungrow MG5RL/MG6RL</b> được trang bị đầy đủ các tính năng an toàn hàng đầu như bảo vệ chống sét lan truyền và chức năng AFCI, đảm bảo an toàn tuyệt đối cho hệ thống và người dùng. Hệ thống giám sát thông minh qua ứng dụng di động <b>iSolarCloud</b> cho phép bạn theo dõi sản lượng điện mọi lúc, mọi nơi. Thiết kế nhỏ gọn, dễ lắp đặt và hoạt động bền bỉ trong mọi điều kiện thời tiết.</p>\r\n\r\n<p><b>Biến tần Sungrow MG5RL/MG6RL</b> không chỉ là một thiết bị, mà còn là khoản đầu tư thông minh cho tương lai năng lượng bền vững. <b>Liên hệ ngay với chúng tôi để nhận tư vấn chi tiết và báo giá tốt nhất!</b>\"</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Thông số kỹ thuật</th>\r\n			<th>MG5RL</th>\r\n			<th>MG6RL</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>Công suất đầu vào PV khuyến nghị tối đa</td>\r\n			<td>8000 Wp</td>\r\n			<td>9600 Wp</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Điện áp đầu vào PV tối đa</td>\r\n			<td>500 V</td>\r\n			<td>500 V</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Điện áp tối thiểu / Khởi động</td>\r\n			<td>40 V / 50 V</td>\r\n			<td>40 V / 50 V</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Điện áp danh định</td>\r\n			<td>360 V</td>\r\n			<td>360 V</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dải điện áp hoạt động MPPT</td>\r\n			<td>40 V – 425 V</td>\r\n			<td>40 V – 425 V</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Số MPPT</td>\r\n			<td>2</td>\r\n			<td>2</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Số chuỗi PV mỗi MPPT</td>\r\n			<td>1 / 1</td>\r\n			<td>1 / 1</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dòng điện đầu vào PV tối đa</td>\r\n			<td>40 A (20 A / 20 A)</td>\r\n			<td>50 A (25 A / 25 A)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dòng ngắn mạch DC tối đa</td>\r\n			<td>50 A (25 A / 25 A)</td>\r\n			<td>60 A (30 A / 30 A)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dòng điện tối đa qua đầu nối DC</td>\r\n			<td>25 A</td>\r\n			<td>25 A</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Pin lưu trữ - Loại pin</td>\r\n			<td colspan=\"2\">Pin Lithium-ion</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Phạm vi điện áp</td>\r\n			<td>40 V – 60 V</td>\r\n			<td>40 V – 60 V</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dòng sạc/xả tối đa</td>\r\n			<td>120 A / 120 A</td>\r\n			<td>135 A / 135 A</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Công suất sạc/xả tối đa</td>\r\n			<td>5000 W</td>\r\n			<td>6000 W</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Ngõ vào / Ngõ ra AC - Công suất AC đầu vào tối đa từ lưới</td>\r\n			<td>8800 VA</td>\r\n			<td>8800 VA</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Công suất AC đầu ra danh định</td>\r\n			<td>5000 W</td>\r\n			<td>6000 W</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Công suất biểu kiến tối đa</td>\r\n			<td>5000 VA</td>\r\n			<td>6000 VA</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dòng điện đầu ra tối đa</td>\r\n			<td>22.7 A</td>\r\n			<td>27.3 A</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Điện áp danh định</td>\r\n			<td colspan=\"2\">220 V / 230 V / 240 V</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Phạm vi điện áp</td>\r\n			<td colspan=\"2\">154 V – 276 V</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Tần số danh định</td>\r\n			<td colspan=\"2\">50 Hz / 60 Hz</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Phạm vi tần số</td>\r\n			<td colspan=\"2\">45 Hz – 55 Hz / 55 Hz – 65 Hz</td>\r\n		</tr>\r\n		<tr>\r\n			<td>THD (tổng méo hài)</td>\r\n			<td colspan=\"2\">&lt; 3%</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hệ số công suất</td>\r\n			<td colspan=\"2\">&gt; 0.99 (mặc định)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Số pha / kết nối AC</td>\r\n			<td colspan=\"2\">1 / 1</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Backup (dữ liệu on grid mode) - Công suất danh định tải dự phòng</td>\r\n			<td>5000 W</td>\r\n			<td>6000 W</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dòng điện danh định tải dự phòng</td>\r\n			<td>22.7 A</td>\r\n			<td>27.3 A</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Công suất tối đa tải dự phòng</td>\r\n			<td>5500 W</td>\r\n			<td>6600 W</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dòng điện tối đa tải dự phòng</td>\r\n			<td>25 A</td>\r\n			<td>30 A</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dòng điện lưới qua tải liên tục tối đa</td>\r\n			<td>40 A</td>\r\n			<td>40 A</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Dữ liệu dự phòng - Điện áp danh định</td>\r\n			<td colspan=\"2\">220 V / 230 V / 240 V</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Tần số danh định</td>\r\n			<td colspan=\"2\">50 Hz / 60 Hz</td>\r\n		</tr>\r\n		<tr>\r\n			<td>THD(V)(tại tuyến tính)</td>\r\n			<td colspan=\"2\">&lt; 2%</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thời gian chuyển sang chế độ dự phòng</td>\r\n			<td colspan=\"2\">≤ 4 ms</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Công suất đầu ra danh định</td>\r\n			<td>5000 W / 5000 VA</td>\r\n			<td>6000 W / 6000 VA</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Công suất tải dự phòng tối đa</td>\r\n			<td>5500 W</td>\r\n			<td>6600 W</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Công suất đỉnh dự phòng</td>\r\n			<td colspan=\"2\">Gấp 2 lần công suất danh định trong 10 giây</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Hiệu suất tối đa / Hiệu suất châu Âu</td>\r\n			<td>97.6 %</td>\r\n			<td>96.7 %</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo vệ quá năng</td>\r\n			<td colspan=\"2\">Tích hợp</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Giảm sai lưới điện</td>\r\n			<td colspan=\"2\">Tích hợp</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo vệ ngược cực DC</td>\r\n			<td colspan=\"2\">Tích hợp</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo vệ ngắn mạch AC</td>\r\n			<td colspan=\"2\">Tích hợp</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo vệ dòng rò</td>\r\n			<td colspan=\"2\">Tích hợp</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Công tắc DC (ngõ vào mặt trời)</td>\r\n			<td colspan=\"2\">Tích hợp</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Bảo vệ chống sét</td>\r\n			<td colspan=\"2\">DC loại II / AC loại II</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Tích hợp chống PID</td>\r\n			<td colspan=\"2\">Tích hợp</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Tương thích microinverter</td>\r\n			<td colspan=\"2\">Tùy chọn</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Thông số chung - Topology (Biến tần)</td>\r\n			<td colspan=\"2\">Non-isolated</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Topology (Pin lưu trữ)</td>\r\n			<td colspan=\"2\">Isolated</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Cấp bảo vệ</td>\r\n			<td colspan=\"2\">IP65</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Thông số kỹ thuật</th>\r\n			<th>MG5RL</th>\r\n			<th>MG6RL</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>Kích thước (R x C x S)</td>\r\n			<td>532 mm * 340 mm * 208 mm</td>\r\n			<td>532 mm * 340 mm * 208 mm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Trọng lượng</td>\r\n			<td>19 kg</td>\r\n			<td>19 kg</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Cách lắp đặt</td>\r\n			<td colspan=\"2\">Gắn tường bằng giá đỡ</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Nhiệt độ hoạt động</td>\r\n			<t