INSERT INTO `cycletech_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `ctype`, `ccode`, `cproducts`, `cloai_tin`, `ctag`, `nview`, `fprice`, `fprice_sale`, `cdescription`, `fb_cdescription`, `cgioi_thieu`, `cdia_diem`, `nid_loai_tin`, `nid_loai_bds`, `nid_province`, `nid_district`, `nid_huong`, `cdien_tich`, `eng_cdetail`, `cdetail`, `cimage`, `cproduct_fb`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nhome`, `nnew`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `ctime_update`, `cphong_an`, `cnha_bep`, `csan_thuong`, `ccho_de_xe`, `cchinh_chu`, `cchieu_ngang`, `cchieu_dai`, `cso_lau`, `cso_phong_ngu`, `cphap_ly`, `cduong_truoc_nha`, `nspecial`, `ccode_product`, `ckeyword`) VALUES
(90, 2, 11, NULL, NULL, 'tru-sac-dc-30kw-hardhitter-cycle-ev', 'Trụ sạc DC 30KW HARDHITTER/CYCLE EV', NULL, '', 0, 0, 0, '\r\n<p data-path-to-node=\"3\">Dòng trạm sạc nhanh DC thế hệ mới là giải pháp tối ưu cho các bãi đỗ xe thương mại, đội xe bus và các điểm sạc công cộng. Với dải công suất linh hoạt từ <b data-index-in-node=\"153\" data-path-to-node=\"3\">30kW đến 80kW</b> và điện áp đầu ra rộng lên tới <b data-index-in-node=\"198\" data-path-to-node=\"3\">1000V</b>, thiết bị đáp ứng hoàn hảo nhu cầu sạc nhanh cho nhiều dòng xe điện hiện đại, từ xe con đến xe khách.</p>\r\n<script data-ts=\"1790678092513\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', '', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<div class=\"product-top-img\" style=\"width: 100%; margin-bottom: 30px;\"><img alt=\"Low Power DC Charging Pile\" src=\"/fileman/Uploads/lowPowerDc/top_img.jpg\" style=\"width: 100%; display: block; object-fit: cover;\"></div>\r\n\r\n<div class=\"introduction\" style=\"display: flex; align-items: center; gap: 40px; padding: 40px 5%; background: #fff; flex-wrap: wrap; margin-bottom: 20px; background-image: url(/fileman/Uploads/lowPowerDc/introduction_bg.jpg); background-size: 100% 100%; background-repeat: no-repeat;\">\r\n<div class=\"introduction-left\" style=\"flex: 1; min-width: 300px;\">\r\n<div class=\"title\" style=\"font-size: 32px; font-weight: bold; color: #333; margin-bottom: 20px;\">Giới thiệu sản phẩm</div>\r\n\r\n<div class=\"content\" style=\"font-size: 16px; line-height: 1.6; color: #666; margin-bottom: 30px;\">Sản phẩm hỗ trợ cả phương thức lắp đặt treo tường và lắp cột, sở hữu kích thước nhỏ gọn cùng ngoại hình thời thượng. Với bốn phiên bản dành cho mục đích dân dụng và vận hành, thiết bị tích hợp kiểm soát sạc thông minh và giám sát toàn diện quá trình sạc, đồng thời hỗ trợ điều khiển qua APP và giám sát dữ liệu hệ thống.</div>\r\n\r\n<div class=\"power-title\" style=\"font-size: 20px; font-weight: 600; margin-bottom: 15px; color: #000;\">Công suất sạc</div>\r\n<img alt=\"Công suất sạc\" class=\"power-img\" src=\"/fileman/Uploads/lowPowerDc/power-img.png\" style=\"max-width: 100%; height: auto;\"></div>\r\n<!-- Hình ảnh minh họa bên phải -->\r\n\r\n<div class=\"introduction-right\" style=\"flex: 1; min-width: 300px; display: flex; gap: 15px;\">\r\n<div style=\"flex: 2;\"><img src=\"/fileman/Uploads/lowPowerDc/first.png\" style=\"width: 100%; border-radius: 8px; box-shadow: 0 4px 10px rgba(0,0,0,0.1); object-fit: cover;\"></div>\r\n\r\n<div style=\"flex: 1; display: flex; flex-direction: column; gap: 15px;\"><img src=\"/fileman/Uploads/lowPowerDc/second.png\" style=\"width: 100%; border-radius: 8px; object-fit: cover;\"> <img src=\"/fileman/Uploads/lowPowerDc/third.png\" style=\"width: 100%; border-radius: 8px; object-fit: cover;\"></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"info-img-container\">\r\n<div class=\"info-item\" style=\"background-image:linear-gradient(rgba(0,0,0,0.2), rgba(0,0,0,0)), url(/fileman/Uploads/lowPowerDc/product_img01.jpg); background-size: cover; background-position: center; padding: 60px 40px; color: #fff; min-height: 350px; margin-bottom: 20px;\">\r\n<div class=\"title\" style=\"font-size: 24px; font-weight: bold; margin-bottom: 15px;\">Bảo vệ cấp độ cao</div>\r\n\r\n<div class=\"line\" style=\"width: 40px; height: 3px; background: #007bff; margin-bottom: 20px;\">&nbsp;</div>\r\n\r\n<div class=\"content\" style=\"font-size: 14px; opacity: 0.9;\">Sử dụng lưới chắn bụi hiệu suất cao, lọc bụi hiệu quả giúp cấp độ bảo vệ đạt IP55. Modun công suất được đổ keo hoàn toàn, mang lại độ tin cậy hệ thống cao và tuổi thọ lâu dài.</div>\r\n</div>\r\n\r\n<div class=\"info-item\" style=\"background-image:linear-gradient(rgba(0,0,0,0.2), rgba(0,0,0,0)), url(/fileman/Uploads/lowPowerDc/product_img02.jpg); background-size: cover; background-position: center; padding: 60px 40px; color: #fff; min-height: 350px; margin-bottom: 20px;\">\r\n<div class=\"title\" style=\"font-size: 24px; font-weight: bold; margin-bottom: 15px;\">Thiết kế nhỏ gọn</div>\r\n\r\n<div class=\"line\" style=\"width: 40px; height: 3px; background: #007bff; margin-bottom: 20px;\">&nbsp;</div>\r\n\r\n<div class=\"content\" style=\"font-size: 14px; opacity: 0.9;\">Hệ thống có kích thước nhỏ gọn, cực kỳ dễ dàng trong việc lắp đặt và kết nối dây dẫn.</div>\r\n</div>\r\n\r\n<div class=\"info-item\" style=\"background-image:linear-gradient(rgba(0,0,0,0.2), rgba(0,0,0,0)), url(/fileman/Uploads/lowPowerDc/product_img03.jpg); background-size: cover; background-position: center; padding: 60px 40px; color: #fff; min-height: 350px; margin-bottom: 20px;\">\r\n<div class=\"title\" style=\"font-size: 24px; font-weight: bold; margin-bottom: 15px;\">Khởi động đa năng</div>\r\n\r\n<div class=\"line\" style=\"width: 40px; height: 3px; background: #007bff; margin-bottom: 20px;\">&nbsp;</div>\r\n\r\n<div class=\"content\" style=\"font-size: 14px; opacity: 0.9;\">Hỗ trợ nhiều phương thức sạc như: quét mã QR, quẹt thẻ RFID, cắm là sạc (Plug &amp; Play), khởi động từ xa và sạc hẹn giờ.</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"technical-specifications\" style=\"padding: 60px 0; background: #f9f9f9; background-image: url(/fileman/Uploads/lowPowerDc/technical.jpg); background-size: 100% 100%; background-repeat: no-repeat;\">\r\n<div class=\"title\" style=\"font-size: 32px; font-weight: bold; text-align: center; margin-bottom: 50px;\">Thông số kỹ thuật</div>\r\n\r\n<div class=\"bottom-content\" style=\"display: flex; gap: 50px; flex-wrap: wrap; padding: 0 5%; align-items: flex-start;\"><!-- Hình Panorama -->\r\n<div class=\"img-wrapper\" style=\"flex: 1; min-width: 300px; text-align: center;\"><img alt=\"Sơ đồ sản phẩm\" src=\"/fileman/Uploads/lowPowerDc/panorama.png\" style=\"max-width: 100%; border-radius: 12px; height: auto; object-fit: cover;\"></div>\r\n<!-- Bảng thông số -->\r\n\r\n<div class=\"info-wrapper\" style=\"flex: 1.5; min-width: 350px; font-family: sans-serif;\"><!-- DC Output -->\r\n<div class=\"term\" style=\"margin-bottom: 25px;\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Đầu ra DC</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Công suất định mức</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30kW / 40kW / 60kW / 80kW</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Điện áp đầu ra</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">DC 200-1000V</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Dòng điện đầu ra</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30/40kW: CCS2 (Max 100/130A) | GBT (Max 100/130A)<br>\r\n60/80kW: CCS2 (Max 200/250A) | GBT (Max 200/250A)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Loại đầu nối</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">CCS2 / GBT</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Chiều dài dây sạc</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Xe con: 4.5m | Xe bus: 6m (tùy chọn)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Hiệu suất</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">≥95% (tỉ lệ tải ≥50%)</div>\r\n</div>\r\n</div>\r\n<!-- AC Input -->\r\n\r\n<div class=\"term\" style=\"margin-bottom: 25px;\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Đầu vào AC</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Điện áp đầu vào</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">AC 400V±10%, 3P+N+PE</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Tần số</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">45-65Hz</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Hệ số công suất</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">≥0.99 (tỉ lệ tải ≥50%)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">THDi</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">≤5% (tỉ lệ tải ≥50%)</div>\r\n</div>\r\n</div>\r\n<!-- Environmental Conditions -->\r\n\r\n<div class=\"term\" style=\"margin-bottom: 25px;\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Điều kiện môi trường</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Độ ẩm</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">5% ~ 95% (không ngưng tụ)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Độ cao so với mực nước biển</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">≤2000m</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Nhiệt độ vận hành</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">-40°C ~ 65°C (Giảm hiệu suất khi dưới -30°C hoặc trên 55°C)</div>\r\n</div>\r\n</div>\r\n<!-- Mechanical Specifications -->\r\n\r\n<div class=\"term\" style=\"margin-bottom: 25px;\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Thông số cơ khí</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Cấp bảo vệ</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">IP55 / IK10</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Phương thức đi dây</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Đi dây từ phía dưới (Bottom Incoming)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Trọng lượng xấp xỉ</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30/40kW: ~100kg (không bao gồm modun)<br>\r\n60/80kW: ~185kg (không bao gồm modun)</div>\r\n</div>\r\n</div>\r\n<!-- General Specifications -->\r\n\r\n<div class=\"term\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Thông số chung</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Giao diện người dùng</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30/40kW: Đèn LED | 60/80kW: LED + Màn hình LCD 7\"</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Chế độ khởi động</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30/40kW: APP | 60/80kW: APP / RFID (Tùy chọn)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Giao diện truyền thông</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Ethernet / 4G (tùy chọn) / WIFI (tùy chọn)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Giao thức truyền thông</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Hỗ trợ OCPP 1.6J (Tùy chọn 2.0)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Tiêu chuẩn sạc</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">IEC 61851-1 / -23 / -21-2</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Tiêu chuẩn EMC</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">EMC Class A</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Tính năng bảo vệ</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Quá dòng, quá áp, thấp áp, lỗi nối đất (bao gồm bảo vệ rò rỉ DC), chống sét lan truyền, quá nhiệt, v.v.</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script data-ts=\"1790678092508\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'HARDHITTER_03_20260928012825.png', NULL, 'resize_HARDHITTER_03_20260928012825.png', 0, '', NULL, 1, 1, 0, 1, '90', 1, 1, '2026-09-14', '2026-09-29', '1790678092', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(91, 2, 11, NULL, NULL, 'tru-sac-dc-60kw-hardhitter-cycle-ev', 'Trụ sạc DC 60KW HARDHITTER/CYCLE EV', NULL, '', 0, 0, 0, '\r\n<p data-path-to-node=\"3\">Dòng trạm sạc nhanh DC thế hệ mới là giải pháp tối ưu cho các bãi đỗ xe thương mại, đội xe bus và các điểm sạc công cộng. Với dải công suất linh hoạt từ <b data-index-in-node=\"153\" data-path-to-node=\"3\">30kW đến 80kW</b> và điện áp đầu ra rộng lên tới <b data-index-in-node=\"198\" data-path-to-node=\"3\">1000V</b>, thiết bị đáp ứng hoàn hảo nhu cầu sạc nhanh cho nhiều dòng xe điện hiện đại, từ xe con đến xe khách.</p>\r\n<script data-ts=\"1790678078179\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', '', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<div class=\"product-top-img\" style=\"width: 100%; margin-bottom: 30px;\"><img alt=\"Low Power DC Charging Pile\" src=\"/fileman/Uploads/lowPowerDc/top_img.jpg\" style=\"width: 100%; display: block; object-fit: cover;\"></div>\r\n\r\n<div class=\"introduction\" style=\"display: flex; align-items: center; gap: 40px; padding: 40px 5%; background: #fff; flex-wrap: wrap; margin-bottom: 20px; background-image: url(/fileman/Uploads/lowPowerDc/introduction_bg.jpg); background-size: 100% 100%; background-repeat: no-repeat;\">\r\n<div class=\"introduction-left\" style=\"flex: 1; min-width: 300px;\">\r\n<div class=\"title\" style=\"font-size: 32px; font-weight: bold; color: #333; margin-bottom: 20px;\">Giới thiệu sản phẩm</div>\r\n\r\n<div class=\"content\" style=\"font-size: 16px; line-height: 1.6; color: #666; margin-bottom: 30px;\">Sản phẩm hỗ trợ cả phương thức lắp đặt treo tường và lắp cột, sở hữu kích thước nhỏ gọn cùng ngoại hình thời thượng. Với bốn phiên bản dành cho mục đích dân dụng và vận hành, thiết bị tích hợp kiểm soát sạc thông minh và giám sát toàn diện quá trình sạc, đồng thời hỗ trợ điều khiển qua APP và giám sát dữ liệu hệ thống.</div>\r\n\r\n<div class=\"power-title\" style=\"font-size: 20px; font-weight: 600; margin-bottom: 15px; color: #000;\">Công suất sạc</div>\r\n<img alt=\"Công suất sạc\" class=\"power-img\" src=\"/fileman/Uploads/lowPowerDc/power-img.png\" style=\"max-width: 100%; height: auto;\"></div>\r\n<!-- Hình ảnh minh họa bên phải -->\r\n\r\n<div class=\"introduction-right\" style=\"flex: 1; min-width: 300px; display: flex; gap: 15px;\">\r\n<div style=\"flex: 2;\"><img src=\"/fileman/Uploads/lowPowerDc/first.png\" style=\"width: 100%; border-radius: 8px; box-shadow: 0 4px 10px rgba(0,0,0,0.1); object-fit: cover;\"></div>\r\n\r\n<div style=\"flex: 1; display: flex; flex-direction: column; gap: 15px;\"><img src=\"/fileman/Uploads/lowPowerDc/second.png\" style=\"width: 100%; border-radius: 8px; object-fit: cover;\"> <img src=\"/fileman/Uploads/lowPowerDc/third.png\" style=\"width: 100%; border-radius: 8px; object-fit: cover;\"></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"info-img-container\">\r\n<div class=\"info-item\" style=\"background-image:linear-gradient(rgba(0,0,0,0.2), rgba(0,0,0,0)), url(/fileman/Uploads/lowPowerDc/product_img01.jpg); background-size: cover; background-position: center; padding: 60px 40px; color: #fff; min-height: 350px; margin-bottom: 20px;\">\r\n<div class=\"title\" style=\"font-size: 24px; font-weight: bold; margin-bottom: 15px;\">Bảo vệ cấp độ cao</div>\r\n\r\n<div class=\"line\" style=\"width: 40px; height: 3px; background: #007bff; margin-bottom: 20px;\">&nbsp;</div>\r\n\r\n<div class=\"content\" style=\"font-size: 14px; opacity: 0.9;\">Sử dụng lưới chắn bụi hiệu suất cao, lọc bụi hiệu quả giúp cấp độ bảo vệ đạt IP55. Modun công suất được đổ keo hoàn toàn, mang lại độ tin cậy hệ thống cao và tuổi thọ lâu dài.</div>\r\n</div>\r\n\r\n<div class=\"info-item\" style=\"background-image:linear-gradient(rgba(0,0,0,0.2), rgba(0,0,0,0)), url(/fileman/Uploads/lowPowerDc/product_img02.jpg); background-size: cover; background-position: center; padding: 60px 40px; color: #fff; min-height: 350px; margin-bottom: 20px;\">\r\n<div class=\"title\" style=\"font-size: 24px; font-weight: bold; margin-bottom: 15px;\">Thiết kế nhỏ gọn</div>\r\n\r\n<div class=\"line\" style=\"width: 40px; height: 3px; background: #007bff; margin-bottom: 20px;\">&nbsp;</div>\r\n\r\n<div class=\"content\" style=\"font-size: 14px; opacity: 0.9;\">Hệ thống có kích thước nhỏ gọn, cực kỳ dễ dàng trong việc lắp đặt và kết nối dây dẫn.</div>\r\n</div>\r\n\r\n<div class=\"info-item\" style=\"background-image:linear-gradient(rgba(0,0,0,0.2), rgba(0,0,0,0)), url(/fileman/Uploads/lowPowerDc/product_img03.jpg); background-size: cover; background-position: center; padding: 60px 40px; color: #fff; min-height: 350px; margin-bottom: 20px;\">\r\n<div class=\"title\" style=\"font-size: 24px; font-weight: bold; margin-bottom: 15px;\">Khởi động đa năng</div>\r\n\r\n<div class=\"line\" style=\"width: 40px; height: 3px; background: #007bff; margin-bottom: 20px;\">&nbsp;</div>\r\n\r\n<div class=\"content\" style=\"font-size: 14px; opacity: 0.9;\">Hỗ trợ nhiều phương thức sạc như: quét mã QR, quẹt thẻ RFID, cắm là sạc (Plug &amp; Play), khởi động từ xa và sạc hẹn giờ.</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"technical-specifications\" style=\"padding: 60px 0; background: #f9f9f9; background-image: url(/fileman/Uploads/lowPowerDc/technical.jpg); background-size: 100% 100%; background-repeat: no-repeat;\">\r\n<div class=\"title\" style=\"font-size: 32px; font-weight: bold; text-align: center; margin-bottom: 50px;\">Thông số kỹ thuật</div>\r\n\r\n<div class=\"bottom-content\" style=\"display: flex; gap: 50px; flex-wrap: wrap; padding: 0 5%; align-items: flex-start;\"><!-- Hình Panorama -->\r\n<div class=\"img-wrapper\" style=\"flex: 1; min-width: 300px; text-align: center;\"><img alt=\"Sơ đồ sản phẩm\" src=\"/fileman/Uploads/lowPowerDc/panorama.png\" style=\"max-width: 100%; border-radius: 12px; height: auto; object-fit: cover;\"></div>\r\n<!-- Bảng thông số -->\r\n\r\n<div class=\"info-wrapper\" style=\"flex: 1.5; min-width: 350px; font-family: sans-serif;\"><!-- DC Output -->\r\n<div class=\"term\" style=\"margin-bottom: 25px;\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Đầu ra DC</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Công suất định mức</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30kW / 40kW / 60kW / 80kW</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Điện áp đầu ra</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">DC 200-1000V</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Dòng điện đầu ra</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30/40kW: CCS2 (Max 100/130A) | GBT (Max 100/130A)<br>\r\n60/80kW: CCS2 (Max 200/250A) | GBT (Max 200/250A)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Loại đầu nối</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">CCS2 / GBT</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Chiều dài dây sạc</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Xe con: 4.5m | Xe bus: 6m (tùy chọn)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Hiệu suất</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">≥95% (tỉ lệ tải ≥50%)</div>\r\n</div>\r\n</div>\r\n<!-- AC Input -->\r\n\r\n<div class=\"term\" style=\"margin-bottom: 25px;\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Đầu vào AC</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Điện áp đầu vào</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">AC 400V±10%, 3P+N+PE</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Tần số</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">45-65Hz</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Hệ số công suất</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">≥0.99 (tỉ lệ tải ≥50%)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">THDi</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">≤5% (tỉ lệ tải ≥50%)</div>\r\n</div>\r\n</div>\r\n<!-- Environmental Conditions -->\r\n\r\n<div class=\"term\" style=\"margin-bottom: 25px;\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Điều kiện môi trường</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Độ ẩm</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">5% ~ 95% (không ngưng tụ)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Độ cao so với mực nước biển</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">≤2000m</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Nhiệt độ vận hành</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">-40°C ~ 65°C (Giảm hiệu suất khi dưới -30°C hoặc trên 55°C)</div>\r\n</div>\r\n</div>\r\n<!-- Mechanical Specifications -->\r\n\r\n<div class=\"term\" style=\"margin-bottom: 25px;\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Thông số cơ khí</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Cấp bảo vệ</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">IP55 / IK10</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Phương thức đi dây</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Đi dây từ phía dưới (Bottom Incoming)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Trọng lượng xấp xỉ</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30/40kW: ~100kg (không bao gồm modun)<br>\r\n60/80kW: ~185kg (không bao gồm modun)</div>\r\n</div>\r\n</div>\r\n<!-- General Specifications -->\r\n\r\n<div class=\"term\">\r\n<div class=\"term-title\" style=\"display: flex; align-items: center; font-weight: bold; font-size: 18px; border-left: 4px solid #007bff; padding-left: 10px; margin-bottom: 15px; color: #000;\">Thông số chung</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Giao diện người dùng</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30/40kW: Đèn LED | 60/80kW: LED + Màn hình LCD 7\"</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Chế độ khởi động</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">30/40kW: APP | 60/80kW: APP / RFID (Tùy chọn)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Giao diện truyền thông</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Ethernet / 4G (tùy chọn) / WIFI (tùy chọn)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Giao thức truyền thông</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Hỗ trợ OCPP 1.6J (Tùy chọn 2.0)</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Tiêu chuẩn sạc</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">IEC 61851-1 / -23 / -21-2</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Tiêu chuẩn EMC</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">EMC Class A</div>\r\n</div>\r\n\r\n<div class=\"item\" style=\"display: flex; border-bottom: 1px solid #ddd; padding: 8px 0;\">\r\n<div style=\"flex: 1; color: #666;\">Tính năng bảo vệ</div>\r\n\r\n<div style=\"flex: 1; font-weight: 500;\">Quá dòng, quá áp, thấp áp, lỗi nối đất (bao gồm bảo vệ rò rỉ DC), chống sét lan truyền, quá nhiệt, v.v.</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script data-ts=\"1790678078171\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'HARDHITTER_04_20260928012914.png', NULL, 'resize_HARDHITTER_04_20260928012914.png', 0, '', NULL, 1, 1, 0, 1, '91', 1, 1, '2026-09-14', '2026-09-29', '1790678078', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(92, 2, 11, NULL, NULL, 'tru-sac-dc-120kw-hardhitter-cycle-ev', 'Trụ sạc DC 120KW HARDHITTER/CYCLE EV', NULL, '', 0, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1790577022965\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', '', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1790577022964\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n\r\n\r\n<div class=\"product-content-gallery\" style=\"margin-top: 30px; padding-top: 20px; border-top: 1px dashed #e2e8f0; width: 100%; box-sizing: border-box;\"><h3 style=\"font-size: 1.15rem; font-weight: 700; color: #00703c; margin-bottom: 16px;\">Hình ảnh chi tiết sản phẩm</h3><div style=\"display: flex; width: 100%; gap: 12px; box-sizing: border-box; align-items: stretch;\"><div style=\"flex: 1; min-width: 0; height: 210px; border-radius: 8px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 2px 8px rgba(0,0,0,0.06); cursor: pointer; background: #f8fafc;\" onclick=\"openImagePopup(\'/fileman/Uploads/HARDHITTERCYCLE/1.jpg\')\"><img src=\"/fileman/Uploads/HARDHITTERCYCLE/1.jpg\" alt=\"Ảnh chi tiết 1\" style=\"width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.3s;\" onmouseover=\"this.style.transform=\'scale(1.08)\'\" onmouseout=\"this.style.transform=\'scale(1)\'\" /></div><div style=\"flex: 1; min-width: 0; height: 210px; border-radius: 8px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 2px 8px rgba(0,0,0,0.06); cursor: pointer; background: #f8fafc;\" onclick=\"openImagePopup(\'/fileman/Uploads/HARDHITTERCYCLE/2.jpg\')\"><img src=\"/fileman/Uploads/HARDHITTERCYCLE/2.jpg\" alt=\"Ảnh chi tiết 2\" style=\"width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.3s;\" onmouseover=\"this.style.transform=\'scale(1.08)\'\" onmouseout=\"this.style.transform=\'scale(1)\'\" /></div><div style=\"flex: 1; min-width: 0; height: 210px; border-radius: 8px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 2px 8px rgba(0,0,0,0.06); cursor: pointer; background: #f8fafc;\" onclick=\"openImagePopup(\'/fileman/Uploads/HARDHITTERCYCLE/3.jpg\')\"><img src=\"/fileman/Uploads/HARDHITTERCYCLE/3.jpg\" alt=\"Ảnh chi tiết 3\" style=\"width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.3s;\" onmouseover=\"this.style.transform=\'scale(1.08)\'\" onmouseout=\"this.style.transform=\'scale(1)\'\" /></div><div style=\"flex: 1; min-width: 0; height: 210px; border-radius: 8px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 2px 8px rgba(0,0,0,0.06); cursor: pointer; background: #f8fafc;\" onclick=\"openImagePopup(\'/fileman/Uploads/HARDHITTERCYCLE/4.jpg\')\"><img src=\"/fileman/Uploads/HARDHITTERCYCLE/4.jpg\" alt=\"Ảnh chi tiết 4\" style=\"width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.3s;\" onmouseover=\"this.style.transform=\'scale(1.08)\'\" onmouseout=\"this.style.transform=\'scale(1)\'\" /></div><div style=\"flex: 1; min-width: 0; height: 210px; border-radius: 8px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 2px 8px rgba(0,0,0,0.06); cursor: pointer; background: #f8fafc;\" onclick=\"openImagePopup(\'/fileman/Uploads/HARDHITTERCYCLE/5.jpg\')\"><img src=\"/fileman/Uploads/HARDHITTERCYCLE/5.jpg\" alt=\"Ảnh chi tiết 5\" style=\"width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.3s;\" onmouseover=\"this.style.transform=\'scale(1.08)\'\" onmouseout=\"this.style.transform=\'scale(1)\'\" /></div></div></div>\r\n', 'HARDHITTER_05_20260928013023.png', NULL, 'resize_HARDHITTER_05_20260928013023.png', 0, '', NULL, 1, 1, 1, 1, '92', 1, 1, '2026-09-14', '2026-09-28', '1790577024', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(93, 2, 12, NULL, NULL, 'tru-sac-ac-7kw-fes-power-cycle-ev', 'Trụ sạc AC 7KW FES POWER/CYCLE EV', NULL, '', 0, 0, 0, '<p><strong>Trụ sạc AC 7KW FES POWER/CYCLE EV (EC01)</strong> là giải pháp sạc xe điện thông minh gắn tường (Wallbox) cao cấp dành cho hộ gia đình và bãi đỗ xe thương mại. Thiết bị sở hữu công suất 7KW (230V - 32A), chuẩn súng sạc Type 2 tương thích hoàn hảo mọi dòng ô tô điện tại Việt Nam (VinFast, Hyundai, Kia, Porsche, BMW, Mercedes...), tích hợp điều khiển App thông minh, quẹt thẻ NFC và công nghệ bảo vệ chống rò dòng AC/DC tối tân.</p>', '', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<h3>TỔNG QUAN VỀ TRỤ SẠC AC 7KW FES POWER/CYCLE EV</h3>\r\n<p><strong>Trụ sạc AC 7KW FES POWER/CYCLE EV (Model: EC01)</strong> là dòng thiết bị sạc xe điện treo tường (Home Wallbox) thế hệ mới, được thiết kế tối ưu cho nguồn điện 1 pha dân dụng tại Việt Nam. Thiết bị kết hợp giữa kiểu dáng hiện đại, nhỏ gọn cùng khả năng vận hành thông minh, an toàn tuyệt đối, mang đến giải pháp nạp năng lượng tiện lợi ngay tại nhà hoặc các trạm dừng nghỉ, tòa nhà văn phòng và khách sạn.</p>\r\n\r\n<hr />\r\n\r\n<h3>ĐẶC ĐIỂM NỔI BẬT</h3>\r\n\r\n<h4>1. Công suất sạc 7KW tối ưu cho điện 1 pha</h4>\r\n<p>Với dòng sạc tối đa 32A và công suất 7KW trên nguồn điện xoay chiều 1 pha 230V, thiết bị giúp rút ngắn thời gian sạc đầy xe qua đêm chỉ từ <strong>6 – 8 tiếng</strong> mà không gây quá tải cho hệ thống điện sinh hoạt gia đình.</p>\r\n\r\n<h4>2. Chuẩn súng sạc Type 2 (IEC 62196-2) tương thích toàn diện</h4>\r\n<p>Trang bị chuẩn sạc Type 2 tiêu chuẩn quốc tế, phù hợp 100% với tất cả các dòng ô tô điện hiện hành tại Việt Nam như: <em>VinFast (VF3, VF5, VF6, VF7, VF8, VF9), Hyundai Ioniq 5, Kia EV6, Porsche Taycan, Mercedes-Benz EQ Series, BMW i Series, Audi e-tron...</em></p>\r\n\r\n<h4>3. Đa dạng phương thức xác thực và điều khiển thông minh</h4>\r\n<ul>\r\n    <li><strong>Cắm sạc tự động (Plug & Play):</strong> Tiện lợi, chỉ cần cắm súng sạc là thiết bị tự động kích hoạt.</li>\r\n    <li><strong>Thẻ từ NFC / RFID:</strong> Quẹt thẻ thông minh để khởi động hoặc dừng sạc, chống tình trạng sử dụng trái phép.</li>\r\n    <li><strong>Ứng dụng di động (Mobile App):</strong> Kết nối qua <strong>Bluetooth, Wi-Fi</strong> (tùy chọn modem <strong>4G</strong>) giúp hẹn giờ sạc giờ thấp điểm, theo dõi công suất tiêu thụ và kiểm tra lịch sử sạc theo thời gian thực.</li>\r\n</ul>\r\n\r\n<h4>4. Thiết kế cao cấp & Lắp đặt linh hoạt</h4>\r\n<ul>\r\n    <li><strong>Kiểu lắp đặt:</strong> Gắn tường (Wall-mounted) gọn gàng tiết kiệm diện tích hoặc gắn trên trụ đứng độc lập (Pedestal/Floor Stand) ngoài trời.</li>\r\n    <li><strong>Đèn LED RGB trực quan:</strong> Dải đèn LED báo trạng thái vận hành thời gian thực (Xanh dương: Chế độ chờ / Xanh lá: Đang sạc / Đỏ: Cảnh báo sự cố).</li>\r\n    <li><strong>Cáp sạc cao cấp 5 mét:</strong> Cáp bọc cách điện chuyên dụng, chống mài mòn, chịu thời tiết khắc nghiệt.</li>\r\n</ul>\r\n\r\n<h4>5. An toàn điện tối đa – Bảo vệ toàn diện</h4>\r\n<ul>\r\n    <li><strong>Tích hợp bảo vệ chống rò kép:</strong> Chống rò xoay chiều <strong>Type A 30mA AC</strong> kết hợp cảm biến dòng rò một chiều <strong>6mA DC</strong> theo tiêu chuẩn IEC khắt khe, không cần lắp thêm RCD Type B đắt tiền bên ngoài.</li>\r\n    <li><strong>Đầy đủ cơ chế bảo vệ phần cứng & phần mềm:</strong> Bảo vệ quá nhiệt (OTP), quá áp (OVP), thấp áp (UVP), quá dòng (OCP), ngắn mạch, chống sét lan truyền (Surge Protection), kiểm soát tiếp địa chống giật.</li>\r\n    <li><strong>Chứng nhận tiêu chuẩn quốc tế:</strong> Đạt chứng nhận <strong>CE (Châu Âu: EN 61851-1, EN 61000-6)</strong>, tiêu chuẩn <strong>GB/T</strong> và tiêu chuẩn vật liệu an toàn <strong>RoHS</strong>.</li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h3>BẢNG THÔNG SỐ KỸ THUẬT ĐIỆN</h3>\r\n\r\n<table style=\"width: 100%; border-collapse: collapse;\">\r\n    <thead>\r\n        <tr>\r\n            <th style=\"width: 35%; padding: 10px; background-color: #f8fafc; border: 1px solid #e2e8f0; color: #103460;\">Thông Số</th>\r\n            <th style=\"width: 65%; padding: 10px; background-color: #f8fafc; border: 1px solid #e2e8f0; color: #103460;\">Chi Tiết Kỹ Thuật</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Model</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">FES POWER EC01-7KW</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Điện áp danh định</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">230Vac ± 10% (1 pha) / 50-60Hz</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Công suất ngõ ra</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>7 KW (Tối đa 32A)</strong></td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Chuẩn đầu súng sạc</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">Type 2 (IEC 62196-2) / Tùy chọn Type 1 hoặc GB/T</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Chiều dài cáp sạc</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">5 mét tiêu chuẩn (Hỗ trợ mở rộng theo yêu cầu)</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Kết nối mạng</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">Bluetooth, Wi-Fi (Tùy chọn modem 4G)</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Phương thức kích hoạt</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">Plug & Play / Thẻ từ NFC (RFID) / Mobile App</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Chống rò dòng</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">Type A 30mA AC + 6mA DC tích hợp</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Nhiệt độ vận hành</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">-30°C đến +55°C</td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\"><strong>Chứng nhận tiêu chuẩn</strong></td>\r\n            <td style=\"padding: 9px 12px; border: 1px solid #e2e8f0;\">CE, RoHS, IEC 61851-1, IEC 61000-6</td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n\r\n<hr />\r\n\r\n<p><strong>Cycle Electric</strong> cam kết cung cấp sản phẩm chính hãng, tư vấn giải pháp lắp đặt an toàn kỹ thuật và chính sách bảo hành, hỗ trợ kỹ thuật tận nơi 24/7.</p>', 'FES_01_20260928013159.png', NULL, 'resize_FES_01_20260928013159.png', 0, '', NULL, 1, 1, 0, 1, '93', 1, 1, '2026-09-14', '2026-09-28', '1790577120', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(94, 2, 12, NULL, NULL, 'tru-sac-ac-11kw-fes-power-cycle-ev', 'Trụ sạc AC 11KW FES POWER/CYCLE EV', NULL, '', 0, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1790578147631\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', '', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1790578147629\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'FES_01_20260928014908.png', NULL, 'resize_FES_01_20260928014908.png', 0, '', NULL, 0, 1, 0, 1, '94', 1, 1, '2026-09-14', '2026-09-28', '1790578148', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(95, 2, 12, NULL, NULL, 'tru-sac-dc-30kw-fes-power-cycle-ev', 'Trụ sạc DC 30KW FES POWER/CYCLE EV', NULL, '', 0, 0, 0, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1790577209886\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', '', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '\r\n<p>&nbsp;</p>\r\n<script data-ts=\"1790577209885\" src=\"https://cdn.n1ed.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', 'FES02_20260928013330.png', NULL, 'resize_FES02_20260928013330.png', 0, '', NULL, 0, 1, 0, 1, '95', 1, 1, '2026-09-14', '2026-09-28', '1790577211', '', '', '', '', '', '', '', '', '', '', '', 0, '', ''),
(96, 2, 12, NULL, NULL, 'tru-sac-dc-60kw-fes-power-cycle-ev', 'Trụ sạc DC 60KW FES POWER/CYCLE EV', NULL, '', 0, 0, 0, '<p>Trụ sạc nhanh DC 60KW FES POWER / CYCLE EV công suất 60kW, chuẩn súng sạc CCS2, nạp nhanh từ 20% lên 80% chỉ trong 30 - 45 phút. Dải điện áp đầu ra siêu rộng 200V - 1000V DC tương thích cả xe 400V và 800V cao cấp, màn hình cảm ứng 7 inch sắc nét, quản trị thông minh qua OCPP 1.6J, cấp bảo vệ IP54 &amp; IK10 chuyên dụng ngoài trời.</p>\r\n', '', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p><strong>Trụ sạc DC 60KW FES POWER / CYCLE EV</strong> là dòng trụ sạc nhanh DC thương mại thế hệ mới, được thiết kế tối ưu cho các trạm sạc dịch vụ, bãi đỗ xe công cộng, tòa nhà văn phòng, trạm dừng nghỉ và trung tâm thương mại. Thiết bị mang lại giải pháp sạc nhanh an toàn, độ bền cao và hiệu suất vượt trội cho hầu hết các dòng xe điện hiện nay.</p>\r\n\r\n<h3>Đặc điểm & Tính năng nổi bật:</h3>\r\n<ul>\r\n	<li><strong>Sạc nhanh hiệu suất cao 60kW:</strong> Rút ngắn thời gian sạc đáng kể, nạp từ 20% lên 80% pin chỉ trong khoảng 30 - 45 phút, đáp ứng hoàn hảo nhu cầu luân chuyển xe liên tục.</li>\r\n	<li><strong>Dải điện áp ngõ ra siêu rộng (200V - 1000V DC):</strong> Tương thích linh hoạt với mọi dòng xe điện trên thị trường, từ các dòng xe sử dụng hệ pin 400V tiêu chuẩn đến các dòng xe điện cao cấp kiến trúc 800V.</li>\r\n	<li><strong>Chuẩn súng sạc CCS2 tiêu chuẩn:</strong> Tương thích hoàn toàn với các dòng xe điện phổ biến tại Việt Nam (VinFast, Hyundai, Kia, Porsche, Mercedes-Benz, BMW, Audi,...).</li>\r\n	<li><strong>Hiệu suất chuyển đổi năng lượng vượt trội (>95%):</strong> Hệ số công suất PF &ge; 0.98 giúp tiết kiệm tối đa điện năng tiêu thụ và tối ưu chi phí vận hành cho chủ đầu tư.</li>\r\n	<li><strong>Quản lý trạm sạc thông minh qua OCPP 1.6J:</strong> Dễ dàng kết nối đồng bộ với hệ thống quản lý trạm sạc trung tâm (CSMS), quản lý thanh toán tự động, giám sát doanh thu và cảnh báo sự cố từ xa qua mạng 4G, Ethernet (LAN) và Wi-Fi.</li>\r\n	<li><strong>Giao diện thân thiện & Vận hành linh hoạt:</strong> Trang bị màn hình cảm ứng LCD 7 inch sắc nét hiển thị đầy đủ thông số sạc theo thời gian thực; hỗ trợ kích hoạt sạc linh hoạt qua thẻ RFID/NFC, Ứng dụng di động (Mobile App) hoặc cắm sạc tự động (Plug &amp; Charge).</li>\r\n	<li><strong>An toàn tuyệt đối chuẩn công nghiệp:</strong> Tích hợp bảo vệ rò dòng DC Type B (6mA DC), kiểm tra cách điện và nối đất tự động, bảo vệ quá áp/thấp áp, quá tải, ngắn mạch, quá nhiệt và nút ngắt khẩn cấp cơ học.</li>\r\n	<li><strong>Thiết kế bền bỉ ngoài trời:</strong> Đạt cấp độ bảo vệ chống nước, chống bụi IP54 và vỏ kim loại sơn tĩnh điện chống va đập chuẩn IK10, hoạt động bền bỉ trong điều kiện thời tiết khắc nghiệt.</li>\r\n</ul>\r\n\r\n<h3>Thông số kỹ thuật chi tiết:</h3>\r\n<div class=\"table-container\">\r\n<table class=\"table table-bordered\">\r\n	<thead>\r\n		<tr style=\"background-color: #f8fafc;\">\r\n			<th style=\"width: 30%;\">Hạng mục</th>\r\n			<th style=\"width: 70%;\">Thông số kỹ thuật</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>Model / Công suất định mức</strong></td>\r\n			<td>Trụ sạc nhanh DC 60kW</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Nguồn cấp đầu vào (AC Input)</strong></td>\r\n			<td>3 Pha 5 Dây (L1, L2, L3, N, PE), 380V ~ 415V AC &plusmn; 15%, 50/60Hz</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Dòng điện đầu vào định mức</strong></td>\r\n			<td>Tối đa ~110A</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hệ số công suất &amp; Hiệu suất</strong></td>\r\n			<td>PF &ge; 0.98 | Hiệu suất chuyển đổi &ge; 95%</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Điện áp đầu ra (DC Output)</strong></td>\r\n			<td>200V ~ 1000V DC</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Dòng điện sạc tối đa</strong></td>\r\n			<td>Lên đến 150A - 200A DC</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Chuẩn súng sạc &amp; Cáp sạc</strong></td>\r\n			<td>Chuẩn súng sạc CCS2, chiều dài dây cáp tiêu chuẩn 4m (tùy chọn 5m)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Giao thức sạc EV</strong></td>\r\n			<td>ISO 15118, DIN 70121</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Giao diện hiển thị</strong></td>\r\n			<td>Màn hình cảm ứng màu LCD 7 inch (Touch Screen) + Đèn LED trạng thái</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Phương thức xác thực</strong></td>\r\n			<td>Thẻ RFID/NFC (ISO 14443 A/B), Ứng dụng di động (Mobile App), Nút dừng khẩn cấp</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kết nối truyền thông</strong></td>\r\n			<td>Giao thức OCPP 1.6J, 4G Modem, Cổng mạng Ethernet (RJ45), Wi-Fi</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Cấp bảo vệ &amp; Chống va đập</strong></td>\r\n			<td>IP54 (Lắp đặt ngoài trời), IK10 (Vỏ thép sơn tĩnh điện chịu lực cao)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Phương thức làm mát</strong></td>\r\n			<td>Làm mát cưỡng bức bằng quạt gió thông minh (Forced Air Cooling)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Nhiệt độ &amp; Độ ẩm vận hành</strong></td>\r\n			<td>-20&deg;C đến +50&deg;C | Độ ẩm: 5% ~ 95% (không ngưng tụ)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Tính năng an toàn</strong></td>\r\n			<td>Bảo vệ rò dòng DC Type B (6mA DC), quá áp/thấp áp, quá tải, quá dòng, ngắn mạch, quá nhiệt, chống sét lan truyền, giám sát tiếp địa liên tục</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n</div>', 'FES05_20260928015017.png', NULL, 'resize_FES05_20260928015017.png', 0, '', NULL, 1, 1, 1, 1, '96', 1, 1, '2026-09-14', '2026-09-28', '1790578217', '', '', '', '', '', '', '', '', '', '', '', 0, '', '');
INSERT INTO `cycletech_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `ctype`, `ccode`, `cproducts`, `cloai_tin`, `ctag`, `nview`, `fprice`, `fprice_sale`, `cdescription`, `fb_cdescription`, `cgioi_thieu`, `cdia_diem`, `nid_loai_tin`, `nid_loai_bds`, `nid_province`, `nid_district`, `nid_huong`, `cdien_tich`, `eng_cdetail`, `cdetail`, `cimage`, `cproduct_fb`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nhome`, `nnew`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `ctime_update`, `cphong_an`, `cnha_bep`, `csan_thuong`, `ccho_de_xe`, `cchinh_chu`, `cchieu_ngang`, `cchieu_dai`, `cso_lau`, `cso_phong_ngu`, `cphap_ly`, `cduong_truoc_nha`, `nspecial`, `ccode_product`, `ckeyword`) VALUES
(97, 2, 12, NULL, NULL, 'tru-sac-dc-120kw-fes-power-cycle-ev', 'Trụ sạc DC 120KW FES POWER/CYCLE EV', NULL, '', 0, 0, 0, '<p>Trụ sạc siêu nhanh DC 120KW FES POWER / CYCLE EV công suất cực đại 120kW, trang bị 2 súng sạc CCS2 với công nghệ cân bằng tải động (Dynamic Load Balancing: 60kW + 60kW hoặc 120kW đơn). Sạc 80% pin chỉ từ 15 - 25 phút, dải điện áp 200V - 1000V DC tương thích xe 400V và 800V cao cấp, hiệu suất chuyển đổi &ge; 96%, quản trị qua OCPP 1.6J, màn hình cảm ứng 7 inch, chuẩn IP54 &amp; IK10 siêu bền.</p>\r\n', '', '', '', NULL, NULL, 0, 0, NULL, '', NULL, '<p><strong>Trụ sạc DC 120KW FES POWER / CYCLE EV</strong> là dòng trụ sạc siêu nhanh công suất cao chuyên dụng cho các trạm sạc dịch vụ thương mại, hub sạc công cộng trên cao tốc, bến bãi đỗ xe vận tải (Depot), đội xe taxi điện, xe buýt điện và trung tâm dịch vụ ô tô điện. Thiết bị tích hợp công nghệ phân bổ công suất động thông minh và hỗ trợ hệ pin điện áp cao lên đến 1000V DC.</p>\r\n\r\n<h3>Đặc điểm & Tính năng nổi bật:</h3>\r\n<ul>\r\n	<li><strong>Sạc siêu nhanh công suất cao 120kW:</strong> Cung cấp dòng điện sạc mạnh mẽ lên đến 250A, nạp đầy 80% pin chỉ từ 15 đến 25 phút, tối ưu hóa năng suất hoạt động và giải tỏa xe nhanh chóng tại các trạm sạc đông đúc.</li>\r\n	<li><strong>Công nghệ cân bằng tải động (Dynamic Power Sharing):</strong> Hỗ trợ 2 súng sạc CCS2 hoạt động đồng thời với thuật toán phân bổ tải thông minh (tự động chia 60kW + 60kW khi sạc 2 xe hoặc tập trung toàn bộ 120kW khi chỉ có 1 xe sạc).</li>\r\n	<li><strong>Dải điện áp siêu rộng 200V - 1000V DC:</strong> Phục vụ hoàn hảo cả thế hệ xe điện nền tảng 400V thông dụng lẫn các dòng xe điện cao cấp nền tảng 800V (Porsche Taycan, Hyundai Ioniq 5/6, Kia EV6, xe thương mại cỡ lớn).</li>\r\n	<li><strong>Hiệu suất chuyển đổi đỉnh cao lên tới 96%:</strong> Tiết kiệm điện năng tối đa, giảm phát sinh nhiệt, tối ưu hóa chi phí vận hành cho nhà đầu tư hạ tầng trạm sạc.</li>\r\n	<li><strong>Kết nối quản trị thông minh chuẩn OCPP 1.6J:</strong> Dễ dàng tích hợp với mọi nền tảng phần mềm quản lý trạm sạc (CSMS), hỗ trợ quản lý người dùng, thanh toán ví điện tử/ngân hàng tự động, giám sát trạng thái và cập nhật firmware từ xa (OTA) qua 4G/Ethernet/Wi-Fi.</li>\r\n	<li><strong>Màn hình cảm ứng 7 inch & Trải nghiệm trực quan:</strong> Màn hình cảm ứng LCD hiển thị chi tiết tiến trình sạc, công suất tức thời, điện năng tiêu thụ và chi phí; khởi động sạc tiện lợi qua thẻ RFID/NFC hoặc App di động.</li>\r\n	<li><strong>Hệ thống bảo vệ đa tầng đạt chuẩn quốc tế:</strong> Trang bị bảo vệ rò dòng DC chuẩn Type B (cảm biến 6mA DC), tự động ngắt khi phát hiện chạm chập, quá nhiệt, quá áp, sụt áp, quá dòng, chống sét lan truyền và nút bấm dừng khẩn cấp phản hồi tức thì.</li>\r\n	<li><strong>Cấp độ bền bỉ IP54 & IK10:</strong> Thân vỏ thép mạ kẽm sơn tĩnh điện cao cấp, chống ăn mòn hóa chất và thời tiết khắc nghiệt, đảm bảo tuổi thọ vận hành lâu dài ngoài trời.</li>\r\n</ul>\r\n\r\n<h3>Thông số kỹ thuật chi tiết:</h3>\r\n<div class=\"table-container\">\r\n<table class=\"table table-bordered\">\r\n	<thead>\r\n		<tr style=\"background-color: #f8fafc;\">\r\n			<th style=\"width: 30%;\">Hạng mục</th>\r\n			<th style=\"width: 70%;\">Thông số kỹ thuật</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>Model / Công suất định mức</strong></td>\r\n			<td>Trụ sạc siêu nhanh DC 120kW (Khả năng mở rộng cấu hình lên đến 160kW / 180kW)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Nguồn cấp đầu vào (AC Input)</strong></td>\r\n			<td>3 Pha 5 Dây (L1, L2, L3, N, PE), 380V ~ 415V AC &plusmn; 15%, 50/60Hz</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Dòng điện đầu vào định mức</strong></td>\r\n			<td>Tối đa ~220A (ở tải định mức)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hệ số công suất &amp; Hiệu suất</strong></td>\r\n			<td>PF &ge; 0.98 | Hiệu suất chuyển đổi cực đại lên đến 96%</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Điện áp đầu ra (DC Output)</strong></td>\r\n			<td>200V ~ 1000V DC (Dải điện áp siêu rộng hỗ trợ cả xe 400V và 800V)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Dòng điện sạc tối đa</strong></td>\r\n			<td>Lên đến 250A DC</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Chuẩn súng súng sạc &amp; Cáp sạc</strong></td>\r\n			<td>2 Súng sạc CCS2 (Dual CCS2 Guns), chiều dài dây cáp tiêu chuẩn 4m (tùy chọn 5m)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Cơ chế phân bổ công suất</strong></td>\r\n			<td>Cân bằng tải động thông minh (Dynamic Load Balancing: 60kW + 60kW hoặc 120kW đơn)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Giao thức sạc EV</strong></td>\r\n			<td>ISO 15118, DIN 70121</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Giao diện hiển thị</strong></td>\r\n			<td>Màn hình cảm ứng màu LCD 7 inch (Touch Screen) + Dải đèn LED trạng thái</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Phương thức xác thực</strong></td>\r\n			<td>Thẻ RFID/NFC (ISO 14443 A/B), Ứng dụng di động (Mobile App), Nút ngắt khẩn cấp cơ học</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kết nối truyền thông</strong></td>\r\n			<td>Giao thức OCPP 1.6J (Sẵn sàng nâng cấp OCPP 2.0.1), 4G Modem, Cổng LAN (RJ45), Wi-Fi</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Cấp bảo vệ &amp; Chống va đập</strong></td>\r\n			<td>IP54 (Chuyên dụng ngoài trời), IK10 (Thân vỏ thép cường lực chống va đập)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Phương thức làm mát</strong></td>\r\n			<td>Làm mát bằng luồng không khí cưỡng bức thông minh (Forced Air Cooling) &le; 65dB</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Nhiệt độ &amp; Độ ẩm vận hành</strong></td>\r\n			<td>-20&deg;C đến +50&deg;C | Độ ẩm: 5% ~ 95% (không ngưng tụ) | Độ cao &le; 2000m</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Tính năng an toàn</strong></td>\r\n			<td>Bảo vệ rò dòng DC Type B (6mA DC), quá áp/thấp áp, quá tải, ngắn mạch, quá nhiệt, chống sét lan truyền, kiểm tra tiếp địa và cách điện tự động</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n</div>', 'FES05_20260928015118.png', NULL, 'resize_FES05_20260928015118.png', 0, '', NULL, 1, 1, 1, 1, '97', 1, 1, 